Object.assign(window.BATCH_NOTES,{"生物11":{"11.1":{"subject":"生物","subject_code":"biology","chapter_id":11,"section_id":"11.1","goals":["用机制解释人类活动的生态后果","评估环境数据的因果边界"],"prerequisites":["食物网与分解者","物质循环"],"flow":["土地利用","营养与耗氧","污染物浓度","气候尺度","入侵与过度利用"],"concept_relation":"土地利用；营养与耗氧；污染物浓度；气候尺度；入侵与过度利用","deep":["某些难降解物质可在个体组织中积累；在适当物质性质和食物网条件下，较高营养级可出现更高浓度。生物累积描述个体随时间或暴露的积聚，生物放大描述营养级间浓度变化，二者不能互换，也不能推断所有污染物都必定逐级放大。","温室效应是大气某些气体吸收并再辐射地表长波辐射的物理过程，天然效应与人类增强效应应分开。气候变化会影响温度、降水、极端事件和分布范围；一次寒冷天气不能独立否定长期趋势，一次高温也不足以单独归因某个具体排放源。","外来物种不一定成为入侵种，但当其建立、扩散并造成显著生态或其他危害时，可能改变竞争、捕食及病原关系。缺乏天敌是某些案例的因素，不是所有外来种影响的唯一解释。过度捕捞还可能通过食物网间接改变其他营养级。","环境评价需要时间序列、适当对照、重复与背景条件。污染源附近生物少可以提示关联，但还要排查水流、底质、季节、其他排放和采样方法；提出机制与验证方案比简单把任何差异归因人类更有解释力。"],"derive":["富营养化的条件链：外源营养输入增加 → 初级生产或藻量变化 → 死亡有机物与分解耗氧增加 → 特定条件下溶氧下降。","浓度=污染物质量/样品质量；营养级间比较必须使用相同基准单位。","相对变化=(处理后−基准)/基准；相关数据仍需可比设计才能支持因果解释。"],"examples":[{"q":"某湖接受含磷径流后藻量增加，随后清晨溶氧降低，解释一条合理机制。","given":"有营养输入、藻量与溶氧的时间变化。","analysis":"连接营养、生物量及耗氧过程。","method":"按过程链解释并限定。","principle":"分解者和生物呼吸消耗氧。","steps":["营养增加可促进藻类繁殖。","死亡有机物增加使微生物分解耗氧增强，夜间无光合补氧时风险可增。"],"ans":"富营养化相关过程可导致缺氧，仍需排除其他因素。","verification":"若只是肥料直接结合氧，不能解释有机物分解的延迟。","pitfall":"只写藻类多所以氧少，不说过程。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":11,"primary_section":"11.1","related_sections":[]},{"q":"浮游生物污染物0.02 mg/kg，小鱼0.2 mg/kg，大鱼1 mg/kg，说明什么？","given":"同一物质、同一质量基准，给定食物关系。","analysis":"比较浓度而非每个体总质量。","method":"计算营养级浓度比。","principle":"生物放大以营养级间浓度递增为特征。","steps":["小鱼为浮游生物的10倍。","大鱼为小鱼5倍、浮游生物50倍。"],"ans":"该数据支持此食物链中出现生物放大。","verification":"统一mg/kg后比例才有意义，不能直接推广其他物质。","pitfall":"把体型大总含量高当作浓度放大。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":11,"primary_section":"11.1","related_sections":[]},{"q":"河流下游物种少于上游，是否足以证明唯一原因是某工厂？","given":"仅一次上下游比较。","analysis":"上下游还有自然与人为混杂。","method":"列重复、参照与机制检测。","principle":"因果需时间与空间可比证据。","steps":["补测排放前后、多个参照点及污染指标。","控制水流、底质和季节等，并检查暴露—效应关系。"],"ans":"不足以确定唯一原因。","verification":"若无排放时同样差异存在，单次比较不能归因。","pitfall":"把空间相关直接写成唯一因果。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":11,"primary_section":"11.1","related_sections":[]}],"practice":[{"q":"生物累积与生物放大是否同义？","given":"比较不同层次。","analysis":"一个体内时间变化与营养级比较不同。","method":"分别定义。","principle":"浓度的比较轴决定概念。","steps":["累积可指个体吸收超过排出。","放大比较较高营养级的浓度升高。"],"ans":"不同。","verification":"个体可累积某物而未见食物链逐级放大。","pitfall":"看到污染物就套同一术语。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":11,"primary_section":"11.1","related_sections":[]},{"q":"两片保护林总面积相同，物种保护效果必相同吗？","given":"一片连续，一片分为隔离小斑块。","analysis":"面积不能代替连接性和边缘效应。","method":"比较迁移与小种群风险。","principle":"破碎化影响生态过程。","steps":["隔离限制迁移与基因流。","边缘比例和局部灭绝后的恢复也可不同。"],"ans":"不必相同。","verification":"空间布局即使面积相同仍不同。","pitfall":"只比较面积一项。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":11,"primary_section":"11.1","related_sections":[]},{"q":"某地一天异常寒冷，能据此否定全球长期变暖趋势吗？","given":"短时局地天气。","analysis":"时空尺度不同。","method":"区分天气与气候统计。","principle":"长期趋势需要长时序广域数据。","steps":["单日波动可与长期趋势并存。","应看多年温度及其他指标，而非挑单一天。"],"ans":"不能。","verification":"上升趋势的数据仍可包含低于均值的点。","pitfall":"用单点代替趋势。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":11,"primary_section":"11.1","related_sections":[]},{"q":"一污染物从0.04升到0.10 mg/kg，增加百分之几？这能证明存在营养级放大吗？","given":"同类样品两次测量，无营养级资料。","analysis":"数值增加不自动给出食物链机制。","method":"先算变化再审查概念。","principle":"相对增加除原值。","steps":["(0.10−0.04)/0.04=1.5=150%。","缺不同营养级与食物关系，不能据此证明放大。"],"ans":"增加150%；不能单据此证明生物放大。","verification":"新值为原来2.5倍，与增加1.5倍区别。","pitfall":"把时间增长当作营养级放大。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":11,"primary_section":"11.1","related_sections":[]}],"quiz":{"q":"所有外来物种都应直接称为入侵物种吗？","given":"仅知并非原产。","analysis":"来源与造成危害是不同条件。","method":"核是否建立扩散及产生影响。","principle":"外来是来源属性，入侵还涉及建立扩散等及危害。","steps":["有些外来种未建立。","已建立也需评价扩散和实际危害，不能只按来源下结论。"],"ans":"不能一概称入侵。","verification":"概念能区分风险监测与已发生影响。","pitfall":"将外来与入侵无条件等同。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":11,"primary_section":"11.1","related_sections":[]},"exam":["环境机制题写输入、过程、后果及限制，避免口号","食物链数据统一浓度基准，区分倍数与增加率","归因题提出替代解释、对照与重复，不只写加强环保"],"quick":["土地利用","营养与耗氧","污染物浓度","气候尺度","入侵与过度利用"],"exam_evidence":[],"content_sources":[{"source_id":"directory_bio","url":"https://elearning.dongzong.my/pluginfile.php/77546/mod_resource/content/1/高中生物.pdf","page":4,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_bio_11.1","url":"https://openstax.org/books/biology-2e/pages/47-3-threats-to-biodiversity","page_or_section":"47-3-threats-to-biodiversity","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_bio","url":"https://elearning.dongzong.my/pluginfile.php/77546/mod_resource/content/1/高中生物.pdf","page":4,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_bio_11.1","url":"https://openstax.org/books/biology-2e/pages/47-3-threats-to-biodiversity","page_or_section":"47-3-threats-to-biodiversity","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"环境机制题写输入、过程、后果及限制，避免口号","method":"列重复、参照与机制检测。","principle":"因果需时间与空间可比证据。","worked_example_index":2,"verification":"若无排放时同样差异存在，单次比较不能归因。","pitfall":"把空间相关直接写成唯一因果。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“用机制解释人类活动的生态后果”的抽样复核：若只是肥料直接结合氧，不能解释有机物分解的延迟。；若出现“只写藻类多所以氧少，不说过程。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“评估环境数据的因果边界”的抽样复核：若无排放时同样差异存在，单次比较不能归因。；若出现“把空间相关直接写成唯一因果。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"将外来与入侵无条件等同。","correction":"不能一概称入侵。","verification":"概念能区分风险监测与已发生影响。"}],"illustration_spec":{"title":"富营养化因果链与浓度比较","objects":["营养径流","藻类","死亡有机物","分解者","溶氧曲线","三营养级"],"relations":["耗氧连到呼吸和分解而非肥料直接吸氧","食物链放大用相同mg/kg"],"labels":["营养输入","分解耗氧","条件性缺氧","浓度≠总量"],"format":"SVG","priority":"P0","reuse":"V22生态图局部可复用但需新增机制","english":"Show nutrient enrichment, algal growth, organic matter decomposition and conditional oxygen depletion. Use a separate food-chain panel with consistent mg/kg concentration units; do not equate concentration with total mass."}},"11.2":{"subject":"生物","subject_code":"biology","chapter_id":11,"section_id":"11.2","goals":["比较就地与迁地保护的作用","依据目标设计保育监测和权衡"],"prerequisites":["种群与群落","遗传多样性"],"flow":["保护层次","就地","迁地","恢复与连接","监测调整"],"concept_relation":"保护层次；就地；迁地；恢复与连接；监测调整","deep":["小种群可能经历遗传漂变、近交和随机事件风险，维持有效基因交流有助于保留适应潜力。廊道有时能促进迁移，也可能带来疾病、入侵或人为干扰；“任何走廊都必定好”忽略了对象、尺度与风险。","生态恢复以修复结构、功能或过程为目标，不能只比较种了多少棵树。单一快速生长树种的人工林未必等同原生群落。评价应包括本地物种建立、自然更新、土壤水文和其他生物返回，并注意时间尺度。","保育方案往往需要与当地居民共同决策，分析生计、资源使用、成本和受益分配。忽略社会条件可能让纸面保护失败。伦理判断要把价值选择与可实测的生态结论分开，不以一句“科学证明必须这样”代替讨论。","监测采用实施前后及参照区域的比较，比仅报告处理后数量更能识别效果；仍需注意参照是否可比。明确成功标准、时间安排与可调整措施，才能在数据不支持时修正方案，而不是把任何投入都宣告为成功。"],"derive":["多样性至少分遗传、物种、生态系统三个层次，指标之间不可互相完全替代。","简化前后—参照比较：措施区变化−参照区变化，可帮助扣除共同趋势，但依赖参照可比等假设。","保育决策链：明确对象与威胁 → 选措施 → 定可测指标与时间 → 监测 → 调整。"],"examples":[{"q":"把濒危植物种子放进种子库，属于就地还是迁地保护？是否已替代原生境？","given":"保存于原生境以外。","analysis":"方法分类与完整效果不同。","method":"按地点分类再评局限。","principle":"迁地保存资源不等于维持整个生态系统。","steps":["种子库属迁地保护。","还需保护授粉者、生境及自然更新等过程。"],"ans":"迁地；不能完全替代原生境。","verification":"原生境消失时即使有种子仍缺恢复条件。","pitfall":"把保存一种遗传材料说成保全生态系统。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":11,"primary_section":"11.2","related_sections":[]},{"q":"措施区数量由100到140，参照区100到120，简化扣除共同趋势的变化是多少？","given":"同一时段，可比性为工作假设。","analysis":"原始增长40含背景共同变化。","method":"比较两地前后差。","principle":"差中之差用于帮助控制共同趋势。","steps":["措施区变化40。","参照区变化20，差为40−20=20。"],"ans":"约多增加20个，不能忽略假设。","verification":"若两区共同都增20，措施区额外部分为20。","pitfall":"把全部40都归功措施。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":11,"primary_section":"11.2","related_sections":[]},{"q":"恢复项目种下一万棵单一树种就宣布生态系统恢复成功，如何评价？","given":"没有本地物种、存活和功能资料。","analysis":"投入数量与结果不同。","method":"提出结构、功能和长期监测指标。","principle":"生态恢复需评价过程与系统。","steps":["调查存活、自然更新与本地物种组成。","比较土壤水文和其他生物恢复，并设参照与长期追踪。"],"ans":"证据不足，不能只凭种植数量判成功。","verification":"全部树死亡或成为单一林都可能不满足目标。","pitfall":"把植树投入当作完整生态结果。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":11,"primary_section":"11.2","related_sections":[]}],"practice":[{"q":"保护物种数不变，是否遗传多样性必不变？","given":"只给物种层指标。","analysis":"层次不同。","method":"考虑同种内部等位基因变化。","principle":"遗传多样性存在于种群内及之间。","steps":["每种仍在但种群可缩小。","等位基因可能丢失，即物种数不变仍有遗传损失。"],"ans":"不一定。","verification":"小种群漂变提供合理机制。","pitfall":"以物种计数替代全部多样性。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":11,"primary_section":"11.2","related_sections":[]},{"q":"生态廊道是否永远没有代价？","given":"问无条件优点。","analysis":"连接也可能传播不利因素。","method":"比较迁移收益与风险。","principle":"方案须与对象及空间尺度匹配。","steps":["可提高基因交流。","也可能促成疾病或入侵扩散，需评估监测。"],"ans":"并非没有代价。","verification":"同一连接能运输本地生物和不利因素。","pitfall":"只写好处不检验对象。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":11,"primary_section":"11.2","related_sections":[]},{"q":"在原生森林设保护区属于哪类保护？为何不能只设牌？","given":"保护在自然生境。","analysis":"类别不等于执行效果。","method":"分类并列管理条件。","principle":"就地保护需有效管理威胁。","steps":["属就地保护。","仍需处理盗猎、周边破碎化与资源等。"],"ans":"就地；需要持续管理。","verification":"没有执法或威胁控制可能仍下降。","pitfall":"以名义面积等同效果。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":11,"primary_section":"11.2","related_sections":[]},{"q":"实施前两区各50，措施后75、参照后65，额外变化多少？若参照另遭洪灾，解释有什么问题？","given":"先按可比假设计算，再审查冲击。","analysis":"计算与因果效力需分开。","method":"作差后检查共同趋势假设。","principle":"独特冲击削弱参照可比。","steps":["(75−50)−(65−50)=10。","若参照受独有洪灾，差10可能混入灾害效应。"],"ans":"算得10，但因果解释受限。","verification":"同一数学结果并不保证方案效应。","pitfall":"把统计运算当作自动消除所有混杂。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":11,"primary_section":"11.2","related_sections":[]}],"quiz":{"q":"保育繁殖个体数量增加，是否足以证明已维持原野种群的全部遗传代表性？","given":"仅有数量，无亲本构成。","analysis":"数量与遗传代表性不同。","method":"核亲本来源及繁殖贡献。","principle":"少数亲本大量繁殖可使总数多而多样性低。","steps":["调查参与繁殖的个体与谱系。","检测遗传多样性并与原野种群比较。"],"ans":"不足以证明。","verification":"100个后代若来自极少亲本可缺很多原有变异。","pitfall":"把个体多等同有效遗传多样性高。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":11,"primary_section":"11.2","related_sections":[]},"exam":["方案题按威胁选措施，写机制、指标、限制和调整","比较题分别说明就地生态关系与迁地备份作用","评价题区分投入、产出与长期成效，给可测监测设计"],"quick":["保护层次","就地","迁地","恢复与连接","监测调整"],"exam_evidence":[],"content_sources":[{"source_id":"directory_bio","url":"https://elearning.dongzong.my/pluginfile.php/77546/mod_resource/content/1/高中生物.pdf","page":4,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_bio_11.2","url":"https://openstax.org/books/biology-2e/pages/47-4-preserving-biodiversity","page_or_section":"47-4-preserving-biodiversity","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_bio","url":"https://elearning.dongzong.my/pluginfile.php/77546/mod_resource/content/1/高中生物.pdf","page":4,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_bio_11.2","url":"https://openstax.org/books/biology-2e/pages/47-4-preserving-biodiversity","page_or_section":"47-4-preserving-biodiversity","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"方案题按威胁选措施，写机制、指标、限制和调整","method":"提出结构、功能和长期监测指标。","principle":"生态恢复需评价过程与系统。","worked_example_index":2,"verification":"全部树死亡或成为单一林都可能不满足目标。","pitfall":"把植树投入当作完整生态结果。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“比较就地与迁地保护的作用”的抽样复核：原生境消失时即使有种子仍缺恢复条件。；若出现“把保存一种遗传材料说成保全生态系统。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“依据目标设计保育监测和权衡”的抽样复核：全部树死亡或成为单一林都可能不满足目标。；若出现“把植树投入当作完整生态结果。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"把个体多等同有效遗传多样性高。","correction":"不足以证明。","verification":"100个后代若来自极少亲本可缺很多原有变异。"}],"illustration_spec":{"title":"保育措施与评价矩阵","objects":["就地生境","种子库","恢复地","廊道","监测指标"],"relations":["就地与迁地互补而非等价","廊道有收益与风险","投入与成效分开"],"labels":["遗传","物种","生态系统","前后与参照","长期监测"],"format":"SVG","priority":"P1","reuse":"未有完整对应图","english":"Compare in-situ habitat protection, ex-situ seed banking and restoration. Link each measure to a specific threat and measurable outcome, with benefits and limitations; do not present corridors as universally risk-free."}},"11.3":{"subject":"生物","subject_code":"biology","chapter_id":11,"section_id":"11.3","goals":["按系统边界比较减排方案","区分碳流、能流与可持续性指标"],"prerequisites":["碳循环","能量守恒与比例"],"flow":["确定服务与边界","活动量×因子","比较基线","材料再用","长期监测"],"concept_relation":"确定服务与边界；活动量×因子；比较基线；材料再用；长期监测","deep":["节能减少为达到同样服务所需的能量，能源替代改变能量来源，二者可互补。能量不会在生态系统像碳一样循环而反复完全利用：能量转换中可用能量逐步分散为热；“循环经济”主要讨论材料和产品利用，不能据名称否定能量流的方向。","减少、重复使用和回收有不同作用。回收可降低部分原生材料需求，但收集、运输、分选和再加工仍需能量，并非所有材料都可无限无损循环。减少不必要消费和延长寿命可避免上游负担，具体结果仍取决替代与使用方式。","碳汇吸收并储存碳，但储存持续性、土地利用变化与火灾等风险须纳入。新种树吸收碳需要时间，不能在没有数量和时间对照时宣称一次植树立即抵销任何排放；同时要顾及生物多样性、水资源和当地需求。","行动评估可从可测基线出发，记录活动量和因子，估计不确定性并追踪实际结果。个人选择、学校设施、产业与公共政策共同影响结果；教学讨论应提出有机制和证据的方案，而不是将系统性问题归结为单一个人的道德标签。"],"derive":["估计排放E=活动量A×排放因子f；多来源时E总=ΣAᵢfᵢ，单位必须相消。","减排率=(基线排放−方案排放)/基线排放；相同服务量与同一系统边界是可比前提。","碳收支与能量收支分别追踪：碳可在库间循环，能量转换后向环境分散，不能画成完全闭合能量循环。"],"examples":[{"q":"学校用电1000 kWh，题设因子0.6 kg CO₂e/kWh，估计多少排放？","given":"只计题设电力环节，不代表实际地区因子。","analysis":"活动量与单位因子相乘。","method":"E=Af并核单位。","principle":"同一边界下的排放估算。","steps":["1000×0.6=600。","kWh相消，余kg CO₂e。"],"ans":"600 kg CO₂e。","verification":"每100 kWh为60 kg，十份为600。","pitfall":"将kg误写为kWh。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":11,"primary_section":"11.3","related_sections":[]},{"q":"相同服务的基线排放800 kg，方案排放600 kg，减排率多少？","given":"系统边界一致。","analysis":"求减少量相对基线。","method":"(E₀−E₁)/E₀。","principle":"百分比以基线为分母。","steps":["减少800−600=200 kg。","200/800=0.25=25%。"],"ans":"25%。","verification":"新排放是原来75%，与减少25%互补。","pitfall":"除以600得到不同指标。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":11,"primary_section":"11.3","related_sections":[]},{"q":"设备甲使用端0排放、制造500 kg；乙制造100 kg且每年使用排100 kg。只用1年能说甲全周期更低吗？","given":"忽略其他环节且功能相同。","analysis":"使用端优势可能被制造负担抵销。","method":"按相同寿命求总量并给边界。","principle":"生命周期比较需累计各环节。","steps":["一年甲500，乙100+100=200 kg。","在此简化一年边界甲较高；若使用更久，结果可能改变。"],"ans":"不能；题设一年甲更高。","verification":"五年时两者分别500与600，说明时间改变结论。","pitfall":"只看使用端零排放。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":11,"primary_section":"11.3","related_sections":[]}],"practice":[{"q":"把所有材料回收，是否意味着不再消耗能量？","given":"讨论回收处理。","analysis":"材料循环与能量流不同。","method":"列分选运输再加工。","principle":"过程仍需能量并产生分散热。","steps":["回收运输和处理需要能量。","即使材料再用，也不能使能量完全循环。"],"ans":"不意味着。","verification":"符合能量守恒并伴可用能量分散。","pitfall":"把循环经济当作永动循环。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":11,"primary_section":"11.3","related_sections":[]},{"q":"公共交通每人公里40 g，单人驾车150 g，走10人公里各多少？","given":"题设因子与人数边界一致。","analysis":"先统一服务量。","method":"因子乘人公里。","principle":"相同服务下可比较排放。","steps":["公交40×10=400 g。","单人驾车150×10=1500 g。"],"ans":"400 g与1500 g，差1100 g。","verification":"10倍各自单位因子，单位相消正确。","pitfall":"将车辆公里与人公里混用。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":11,"primary_section":"11.3","related_sections":[]},{"q":"种下一棵树即可立即抵销一次任意排放，这句话缺什么？","given":"未给树种、增长和排放量。","analysis":"吸收是随时间发生且有风险的过程。","method":"要求数量时间与持续性。","principle":"收支必须同单位同边界比较。","steps":["明确排放总量和时点。","估计树的净吸收、时间及存活与储存风险，不能说任意抵销。"],"ans":"缺数量、时间及持续性等证据。","verification":"刚栽种时尚无所声称的未来累计吸收。","pitfall":"把未来潜力当立即已实现。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":11,"primary_section":"11.3","related_sections":[]},{"q":"基线用电2000 kWh，节能后1500，因子0.5 kg/kWh不变，排放各多少、减排率多少？","given":"比较同样服务，题设因子不变。","analysis":"活动量变化传到排放。","method":"分别估算再求减少率。","principle":"E=Af。","steps":["基线1000 kg，方案750 kg。","减少250/1000=25%。"],"ans":"1000与750 kg，减25%。","verification":"用电也减500/2000=25%，因子固定时比例一致。","pitfall":"认为减500 kWh就是减500 kg。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":11,"primary_section":"11.3","related_sections":[]}],"quiz":{"q":"“电动设备使用端无燃烧，因此全生命周期温室气体排放为零”，哪一步不成立？","given":"仅知使用端没有燃烧。","analysis":"局部边界不能推出全生命周期。","method":"补发电制造与处置等环节。","principle":"总排放含边界内各环节。","steps":["使用端无燃烧可降低该环节直接排放。","仍需计电源和制造等，且地区因子不一。"],"ans":"从一个环节零排放跳到全部环节零排放。","verification":"完整边界求和后才可评价总量。","pitfall":"把间接排放漏出边界。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":11,"primary_section":"11.3","related_sections":[]},"exam":["估算题先写功能单位、边界、因子和单位","方案比较说明使用年限与上游排放，不只用绿色标签","议论题同时评价排放、生态与社会影响，并给可跟踪指标"],"quick":["确定服务与边界","活动量×因子","比较基线","材料再用","长期监测"],"exam_evidence":[],"content_sources":[{"source_id":"directory_bio","url":"https://elearning.dongzong.my/pluginfile.php/77546/mod_resource/content/1/高中生物.pdf","page":4,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_bio_11.3","url":"https://openstax.org/books/biology-2e/pages/46-3-biogeochemical-cycles","page_or_section":"46-3-biogeochemical-cycles","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_bio","url":"https://elearning.dongzong.my/pluginfile.php/77546/mod_resource/content/1/高中生物.pdf","page":4,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_bio_11.3","url":"https://openstax.org/books/biology-2e/pages/46-3-biogeochemical-cycles","page_or_section":"46-3-biogeochemical-cycles","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"估算题先写功能单位、边界、因子和单位","method":"按相同寿命求总量并给边界。","principle":"生命周期比较需累计各环节。","worked_example_index":2,"verification":"五年时两者分别500与600，说明时间改变结论。","pitfall":"只看使用端零排放。"},"diagnostics":[{"goal_index":0,"question_ref":"e2","review_module":4,"feedback":"目标“按系统边界比较减排方案”的抽样复核：五年时两者分别500与600，说明时间改变结论。；若出现“只看使用端零排放。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"p0","review_module":5,"feedback":"目标“区分碳流、能流与可持续性指标”的抽样复核：符合能量守恒并伴可用能量分散。；若出现“把循环经济当作永动循环。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"把间接排放漏出边界。","correction":"从一个环节零排放跳到全部环节零排放。","verification":"完整边界求和后才可评价总量。"}],"illustration_spec":{"title":"低碳方案的系统边界","objects":["原料制造","运输","能源生产","使用","处置回收","碳汇"],"relations":["各环节排放累加","相同服务与年限比较","碳汇标时间和不确定性"],"labels":["kg CO₂e","功能单位","直接/间接","活动量×因子","非通用因子"],"format":"SVG","priority":"P1","reuse":"V22碳循环可作原理背景，非足够全生命周期图","english":"Draw a lifecycle boundary including raw materials, manufacture, energy supply, transport, use and end of life. Compare equal services over equal lifetimes using explicitly hypothetical emission factors. Mark carbon-sink storage time and uncertainty."}}},"生物13":{"13.1":{"subject":"生物","subject_code":"biology","chapter_id":13,"section_id":"13.1","goals":["按着丝粒与DNA分子分别计数","解释阶段变化和检查点作用"],"prerequisites":["DNA复制","同源与姐妹的区别"],"flow":["S期复制","中期姐妹相连","后期姐妹分开","胞质分配","检查点控制"],"concept_relation":"S期复制；中期姐妹相连；后期姐妹分开；胞质分配；检查点控制","deep":["后期姐妹染色单体分开成为独立子染色体，在一个尚未分开的细胞内，着丝粒计数会暂时加倍。这不是DNA再次复制。末期两套染色体到达两极并重建细胞核；胞质分裂可与后期、末期重叠，核分裂和胞质分裂不能当作完全相同的事件。","动物细胞常以收缩环形成分裂沟，植物通常在中央形成细胞板并向外扩展。植物有细胞壁，不能套用动物向内缢裂的图。标准有丝分裂把复制产物分别给两个子细胞，使染色体数通常保持；突变或分离错误须另作分析。","检查点是根据DNA状态、复制完成情况和纺锤体连接等信息调控周期的关口。药物处理后中期细胞比例增大，可能因为该阶段停留延长；不能仅凭比例证明增殖更快，更不能自动把药物称为致癌物。","显微图判断先看染色体是否凝缩、排列或向两极分开，再用计数辅助。压片、染色、观察视野和取样组织都会影响结果。根尖分生组织适合观察，成熟伸长区不能仅因细胞更大就视为更合适。"],"derive":["未复制二倍体为2n条、2C；S期后为2n条、4C，每条有两条姐妹。","后期全细胞为4n条子染色体、DNA总量仍4C；每极得到2n条、2C。n与C分别描述套数和DNA量，不可互换。","分裂指数=分裂期细胞数/总观察细胞数。只有随机取样、近似稳态等条件下，阶段比例才可辅助估计相对停留时间。"],"examples":[{"q":"2n=6的正常细胞完成S期并进入中期，有几条染色体、几个核DNA分子？","given":"复制完成，姐妹未分离。","analysis":"两种数量的计数单位不同。","method":"分别数着丝粒与染色单体。","principle":"复制增加DNA而不立即增加着丝粒单位。","steps":["复制前6条、6个DNA分子。","复制后仍6条染色体，共12条姐妹染色单体，各含1个DNA分子。"],"ans":"6条、12个。","verification":"DNA从2C到4C，染色体仍2n。","pitfall":"把复制直接当成染色体数加倍。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":13,"primary_section":"13.1","related_sections":[]},{"q":"同一2n=6细胞到后期但胞质未分开，全细胞和每一极各有几条染色体？","given":"正常分离且无丢失。","analysis":"必须先区分整细胞与单极。","method":"计分离后的着丝粒，再分配。","principle":"姐妹分离后成为独立子染色体，DNA没有再复制。","steps":["全细胞有12条。","每极6条；总DNA仍12个，每极6个。"],"ans":"全细胞12，每极6。","verification":"两极6+6=12，最终子细胞各回到2n=6。","pitfall":"把每极结果当成整个细胞结果。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":13,"primary_section":"13.1","related_sections":[]},{"q":"对照1000细胞中100个分裂，处理组1000中250个分裂且多数停中期，能否证明增殖更快？","given":"两组同样取样，但未追踪周期完成时间。","analysis":"比例增大也可能是中期阻滞。","method":"计算指数，再列区分解释所需证据。","principle":"阶段占比由进入及离开该阶段共同决定。","steps":["指数分别10%和25%。","中期积累可能是检查点阻滞。","追踪完成分裂时间、活细胞总量及死亡率，才能判断净增殖。"],"ans":"不能，已知的是分裂期占比上升。","verification":"完全阻滞时指数可很高而新子细胞几乎不增加。","pitfall":"把横截面比例当成单位时间分裂次数。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":13,"primary_section":"13.1","related_sections":[]}],"practice":[{"q":"正常S期染色体数是否随DNA量一起加倍？","given":"尚未发生姐妹分离。","analysis":"复制和分离不同。","method":"分别描述计数规则。","principle":"染色体按着丝粒单位计。","steps":["DNA逐渐增加。","S期完成仍2n，到姐妹分离才改变全细胞计数。"],"ans":"不会随之加倍。","verification":"与中期2n、4C一致。","pitfall":"数线条而不数着丝粒。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":13,"primary_section":"13.1","related_sections":[]},{"q":"显微图见染色体分成两极，是否必为减数分裂？","given":"只给两极形态。","analysis":"有丝后期也有两极。","method":"结合配对、数目及分离对象判断。","principle":"分姐妹与分同源是不同事件。","steps":["寻找同源配对等证据。","再判断分开的是同源还是姐妹。"],"ans":"不能仅据两极判断。","verification":"分姐妹可见于有丝后期或减Ⅱ后期。","pitfall":"只凭两极贴标签。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":13,"primary_section":"13.1","related_sections":[]},{"q":"植物胞质分裂形成的是赤道板还是细胞板？","given":"问真实物质结构。","analysis":"几何平面与新结构不同。","method":"按时期及功能区分。","principle":"赤道板是中期排列平面，细胞板参与分隔。","steps":["中期染色体在赤道板排列。","胞质分裂形成细胞板并参与新细胞壁。"],"ans":"细胞板。","verification":"两者物质性质与出现阶段不同。","pitfall":"名字相近便认为相同。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":13,"primary_section":"13.1","related_sections":[]},{"q":"200细胞中前期12、中期6、后期2、末期4，求分裂指数并写一项限制。","given":"分类不重叠。","analysis":"分母须包括间期细胞。","method":"相加分裂数再除总数。","principle":"指数是比例，不直接给绝对增殖速率。","steps":["分裂数=12+6+2+4=24。","24/200=12%；取样是否随机、周期是否稳态限制解释。"],"ans":"12%；不能单凭此算每小时增殖数。","verification":"24+176=200。","pitfall":"只用分裂细胞作分母。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":13,"primary_section":"13.1","related_sections":[]}],"quiz":{"q":"2n=8细胞后期全细胞有16条子染色体，是否说明多复制了一次DNA？","given":"胞质未分开。","analysis":"计数变化来自姐妹分离。","method":"比较中期和后期DNA总量。","principle":"后期不是S期。","steps":["中期8条复制染色体含16个DNA。","后期16条子染色体仍含16个DNA。"],"ans":"不是，DNA总量未再增加。","verification":"最终两子细胞各8个DNA，总量守恒。","pitfall":"把染色体计数改变当成复制证据。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":13,"primary_section":"13.1","related_sections":[]},"exam":["计数题先写单核、全细胞、每极或子细胞，再列时期","图像题先辨分开的结构，再用数目辅助，不用线多就猜阶段","药物题区分观察比例与因果结论，提出追踪周期及对照"],"quick":["S期复制","中期姐妹相连","后期姐妹分开","胞质分配","检查点控制"],"exam_evidence":[],"content_sources":[{"source_id":"directory_bio","url":"https://elearning.dongzong.my/pluginfile.php/77546/mod_resource/content/1/高中生物.pdf","page":4,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_bio_13.1","url":"https://openstax.org/books/biology-2e/pages/10-2-the-cell-cycle","page_or_section":"10-2-the-cell-cycle","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_bio","url":"https://elearning.dongzong.my/pluginfile.php/77546/mod_resource/content/1/高中生物.pdf","page":4,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_bio_13.1","url":"https://openstax.org/books/biology-2e/pages/10-2-the-cell-cycle","page_or_section":"10-2-the-cell-cycle","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"计数题先写单核、全细胞、每极或子细胞，再列时期","method":"计算指数，再列区分解释所需证据。","principle":"阶段占比由进入及离开该阶段共同决定。","worked_example_index":2,"verification":"完全阻滞时指数可很高而新子细胞几乎不增加。","pitfall":"把横截面比例当成单位时间分裂次数。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“按着丝粒与DNA分子分别计数”的抽样复核：DNA从2C到4C，染色体仍2n。；若出现“把复制直接当成染色体数加倍。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“解释阶段变化和检查点作用”的抽样复核：完全阻滞时指数可很高而新子细胞几乎不增加。；若出现“把横截面比例当成单位时间分裂次数。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"把染色体计数改变当成复制证据。","correction":"不是，DNA总量未再增加。","verification":"最终两子细胞各8个DNA，总量守恒。"}],"illustration_spec":{"title":"有丝分裂计数与胞质分裂","objects":["2n=4复制前后","中期","后期全细胞/每极","分裂沟","细胞板"],"relations":["复制后DNA加倍但染色体数不变","后期DNA总量守恒","植物不画分裂沟"],"labels":["2n","2C","4C","着丝粒","姐妹","细胞板"],"format":"SVG","priority":"P0","reuse":"V22 B42计数图可复用，胞质分裂需另图","english":"Track chromosome and DNA counts in a 2n=4 mitosis model. Separate whole-cell anaphase from each pole and compare animal cleavage furrow with plant cell plate."}},"13.2":{"subject":"生物","subject_code":"biology","chapter_id":13,"section_id":"13.2","goals":["辨认两次分裂的分离对象","用染色体行为解释遗传变异"],"prerequisites":["有丝分裂","同源染色体与等位基因"],"flow":["一次复制","减Ⅰ分同源","减Ⅱ分姐妹","交换与独立取向","受精恢复组数"],"concept_relation":"一次复制；减Ⅰ分同源；减Ⅱ分姐妹；交换与独立取向；受精恢复组数","deep":["以2n=4的模型追踪：复制前2n、2C；复制后2n、4C；减Ⅰ完成后各细胞n、2C；减Ⅱ完成后各细胞n、1C。观察全细胞时后期的计数须另注明范围，不能把最终配子数目直接套到尚未胞质分裂的后期细胞。","同源对在中期Ⅰ的独立取向，使不同对的父母来源可有不同组合。在忽略交换且正常独立分配时，n对同源可形成2的n次方种来源组合；这不是单次减数分裂一定同时得到的不同配子数，也不是含交换时的全部基因型上限。","交换可重新组合一条染色体上的等位基因组合，随机受精再增加后代组合。正常减数分裂解释重组与分离，不负责创造所有新等位基因；新等位基因通常需追溯突变。等位基因分离与染色体行为的关联还须限定正常分离及所处位置。","不分离可发生在第一次或第二次分裂，产生染色体数目异常的配子。分析图时先判断同源还是姐妹未分开，再分别追踪各个子细胞；只背诵“异常配子一半”会把不同阶段混淆。动物精子、卵的形成在胞质分配上不同，不能把四个产物一律画成四个同样功能的卵。"],"derive":["正常二倍体：2n、2C → DNA复制 → 2n、4C → 减Ⅰ → n、2C → 减Ⅱ → n、1C。","无交换的来源组合数为2ⁿ，n是同源染色体对数；这是多次减数分裂可能产生的来源组合。","若n=2，第一次分裂某对不分离，最终四个产物对该染色体的拷贝数为2、2、0、0，而正常应各为1。"],"examples":[{"q":"某生物2n=8，正常减Ⅰ完成后每个细胞有几条染色体和几个DNA分子？","given":"DNA复制完成且正常同源分离。","analysis":"减Ⅰ分同源而不分姐妹。","method":"先减半染色体数，再按每条两条姐妹计DNA。","principle":"减Ⅰ后为n、2C。","steps":["n=4，每细胞4条染色体。","每条仍含两条姐妹，核DNA分子为8个。"],"ans":"4条、8个DNA分子。","verification":"减Ⅱ后每个配子4个DNA分子，进一步减半而染色体数仍4。","pitfall":"减Ⅰ后直接把DNA也算成4个。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":13,"primary_section":"13.2","related_sections":[]},{"q":"2n=6，不计交换，配子染色体父母来源最多有多少组合？一次减数分裂会出现全部组合吗？","given":"三对同源正常独立取向。","analysis":"理论可能性与一次分裂产物数量不同。","method":"用2ⁿ并检查一次产物。","principle":"各对有两种来源选择。","steps":["n=3，2³=8。","一次减数分裂通常形成四个产物，忽略交换时不能同时给出8种组合。"],"ans":"可能8种；一次不会同时出现全部。","verification":"一细胞四个产物的数量小于8。","pitfall":"把群体概率空间当作一次分裂的实际结果。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":13,"primary_section":"13.2","related_sections":[]},{"q":"一次减数分裂中某对同源在减Ⅰ未分离，减Ⅱ正常，该染色体在四个配子中的数目怎样？","given":"不考虑其他染色体，正常每配子应有1条。","analysis":"异常在同源分配的第一步。","method":"画两次分配树。","principle":"同源一起进一侧，随后姐妹各自正常分离。","steps":["减Ⅰ两细胞对该类染色体分别有2条复制染色体和0条。","减Ⅱ后前者给出两个各含2条的配子，后者给出两个0条配子。"],"ans":"2、2、0、0；均对该类数目异常。","verification":"四产物拷贝总数4，与复制后总量一致。","pitfall":"套用减Ⅱ不分离的2、0、1、1。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":13,"primary_section":"13.2","related_sections":[]}],"practice":[{"q":"减Ⅱ前是否要再次复制全部核DNA？","given":"正常减数分裂。","analysis":"一次复制服务于两次分裂。","method":"比较减Ⅰ与减Ⅱ之间DNA量。","principle":"减Ⅰ后染色体仍含姐妹。","steps":["减Ⅰ后为n、2C。","减Ⅱ分姐妹后为n、1C，无需再S期复制。"],"ans":"一般不再复制。","verification":"若再复制，最终DNA量不能按正常过程降至1C。","pitfall":"把每次分裂都配一个S期。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":13,"primary_section":"13.2","related_sections":[]},{"q":"同源染色体交换发生在姐妹还是非姐妹之间？","given":"问正常减Ⅰ前期的交换。","analysis":"同源与姐妹是不同分类。","method":"按参与者来源作答。","principle":"交换涉及联会的同源染色体。","steps":["辨认父母来源同源。","交换位于其中非姐妹染色单体之间。"],"ans":"同源染色体的非姐妹染色单体。","verification":"复制后的同一条姐妹交换不能解释父母来源重组模型。","pitfall":"把联会的两条线都叫姐妹。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":13,"primary_section":"13.2","related_sections":[]},{"q":"细胞2n=4，减Ⅱ后每产物的核DNA分子数？","given":"正常分离，无突变。","analysis":"最终每条染色体不再有两条姐妹。","method":"求n再按单染色单体计。","principle":"减Ⅱ后n、1C。","steps":["n=2。","每个产物2条染色体、2个核DNA分子。"],"ans":"2个。","verification":"四产物合计8个，等于S期后8个。","pitfall":"继续乘2把姐妹算进去。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":13,"primary_section":"13.2","related_sections":[]},{"q":"某一减Ⅱ细胞的某条染色体姐妹不分离，另一减Ⅱ细胞正常，四个配子该染色体拷贝数？","given":"减Ⅰ正常，减Ⅱ只有一侧异常。","analysis":"两个减Ⅱ细胞须分别追踪。","method":"列异常侧与正常侧的产物。","principle":"异常侧给2与0，正常侧给1与1。","steps":["追踪异常侧得到2、0。","正常侧得到1、1，合计四个拷贝。"],"ans":"2、0、1、1。","verification":"与减Ⅰ不分离的2、2、0、0不同。","pitfall":"把两次分裂异常结果混为一谈。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":13,"primary_section":"13.2","related_sections":[]}],"quiz":{"q":"一幅图中同源已分开但姐妹仍相连，能说是有丝后期吗？","given":"图明确表示分离对象是同源。","analysis":"分离对象比“两极”形状更有辨识力。","method":"比较减Ⅰ和有丝后期。","principle":"有丝后期分姐妹；减Ⅰ后期分同源。","steps":["同源分开符合减Ⅰ后期。","姐妹仍连不符合正常有丝后期姐妹已分离的特征。"],"ans":"不能，应考虑减Ⅰ后期。","verification":"再检查配对与每极组数以支持判断。","pitfall":"见到两极就断定有丝后期。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":13,"primary_section":"13.2","related_sections":[]},"exam":["阶段图题先问分同源还是分姐妹，再数每个细胞","组合题写明是否忽略交换以及一次还是多次","异常分配题逐代画分配树，不背不加条件的比例"],"quick":["一次复制","减Ⅰ分同源","减Ⅱ分姐妹","交换与独立取向","受精恢复组数"],"exam_evidence":[],"content_sources":[{"source_id":"directory_bio","url":"https://elearning.dongzong.my/pluginfile.php/77546/mod_resource/content/1/高中生物.pdf","page":4,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_bio_13.2","url":"https://openstax.org/books/biology-2e/pages/11-1-the-process-of-meiosis","page_or_section":"11-1-the-process-of-meiosis","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_bio","url":"https://elearning.dongzong.my/pluginfile.php/77546/mod_resource/content/1/高中生物.pdf","page":4,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_bio_13.2","url":"https://openstax.org/books/biology-2e/pages/11-1-the-process-of-meiosis","page_or_section":"11-1-the-process-of-meiosis","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"阶段图题先问分同源还是分姐妹，再数每个细胞","method":"画两次分配树。","principle":"同源一起进一侧，随后姐妹各自正常分离。","worked_example_index":2,"verification":"四产物拷贝总数4，与复制后总量一致。","pitfall":"套用减Ⅱ不分离的2、0、1、1。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“辨认两次分裂的分离对象”的抽样复核：减Ⅱ后每个配子4个DNA分子，进一步减半而染色体数仍4。；若出现“减Ⅰ后直接把DNA也算成4个。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“用染色体行为解释遗传变异”的抽样复核：四产物拷贝总数4，与复制后总量一致。；若出现“套用减Ⅱ不分离的2、0、1、1。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"见到两极就断定有丝后期。","correction":"不能，应考虑减Ⅰ后期。","verification":"再检查配对与每极组数以支持判断。"}],"illustration_spec":{"title":"减数分裂的分离对象与DNA量","objects":["两对同源染色体","联会与非姐妹交换","减Ⅰ","减Ⅱ","四个产物"],"relations":["只在分裂前复制一次","减Ⅰ同源分离","减Ⅱ姐妹分离"],"labels":["2n=4","4C","n=2","2C","1C"],"format":"SVG","priority":"P0","reuse":"可复核复用V22 B46、B56","english":"Show one DNA replication followed by homolog separation in meiosis I and sister separation in meiosis II. Use two homolog pairs and label DNA content per cell."}},"13.3":{"subject":"生物","subject_code":"biology","chapter_id":13,"section_id":"13.3","goals":["解释周期调控失常与肿瘤发展的关系","区分风险因素、相关性与诊断证据"],"prerequisites":["细胞周期与检查点","基因表达和突变"],"flow":["周期信号","损伤应答","异常克隆","侵袭与转移","证据边界"],"concept_relation":"周期信号；损伤应答；异常克隆；侵袭与转移；证据边界","deep":["良性与恶性肿瘤都可能是异常增殖形成的细胞团，但恶性肿瘤可侵袭周围组织并可能转移。转移包含局部侵袭、进入循环、在其他部位定植等环节；不能画成所有肿瘤细胞一出现就立即随血液扩散。某些癌症也不以明显实体肿块开始。","风险因素如烟草相关暴露、紫外线、某些病毒感染和遗传易感性，可经不同机制增加风险。病毒相关癌症不代表所有癌症都能直接传染；具有遗传易感变异也不等于癌症本身必然由亲代传给子代。必须区分体细胞突变与可遗传的生殖系变异。","实验研究可比较增殖、死亡、侵袭等指标，并设置对照、重复和适当浓度范围。体外细胞被一种物质杀死并不足以证明它是安全有效的治疗：正常细胞毒性、体内到达浓度与临床结局均未得到回答。教学实验结果应限定在观察条件内。","预防和早期发现的建议须依据可靠卫生指南，课堂模型不能用来个人诊断。治疗可能涉及手术、放疗、药物等并由专业团队按病种和个体状况决定；本节学习周期与证据判断，不把原创题中的比例解释成个体患病概率。"],"derive":["调控模型：促进生长的信号受调节 + 抑制与修复机制 → 协调细胞数量；多环节失调可能促成异常克隆扩增。","净细胞数量变化=新产生细胞数−死亡或离开系统的细胞数；分裂比例不是净增长率。","相对风险比较需要明确观察人数、事件数及可比条件，观察性相关不能单独证明某一分子机制。"],"examples":[{"q":"组织甲分裂细胞多，组织乙少，能仅据此断言甲是癌组织吗？","given":"仅有分裂比例，无侵袭、调控或病理证据。","analysis":"正常组织更新也可快。","method":"列可替代解释及需要的证据。","principle":"增殖是癌症相关行为之一，但不构成独立诊断。","steps":["甲可能处于生长或修复。","还需病理形态、持续失调和组织行为等专业证据。"],"ans":"不能。","verification":"正常根尖或胚胎的高分裂率也是反例。","pitfall":"把单一相关指标当作充分诊断条件。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":13,"primary_section":"13.3","related_sections":[]},{"q":"培养24小时内甲新生120细胞、死亡20；乙新生150、死亡80，哪组净增加更多？","given":"起始和观察条件可比，忽略迁入迁出。","analysis":"比较净变化不能只看新生数。","method":"分别作产生减死亡。","principle":"数量守恒。","steps":["甲净增120−20=100。","乙净增150−80=70。"],"ans":"甲净增加更多，差30。","verification":"甲虽新生少30，却死亡少60，净效应多30。","pitfall":"只按150>120判断。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":13,"primary_section":"13.3","related_sections":[]},{"q":"候选物使癌细胞存活率降至20%，正常细胞也降至18%，能称为已证实安全的抗癌药吗？","given":"只有单一体外条件，无体内或临床资料。","analysis":"杀伤不等于选择性与安全性。","method":"比较两类细胞并列证据缺口。","principle":"治疗评价需有效性、安全性及可达暴露。","steps":["两种细胞均受强烈损伤。","尚不能显示对癌细胞更有选择性。","需重复、剂量反应、体内与临床等进一步证据。"],"ans":"不能；只说明本实验条件下有细胞毒性。","verification":"正常细胞18%低于癌细胞20%，并不支持明显选择优势。","pitfall":"用体外杀细胞直接宣传治疗效果。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":13,"primary_section":"13.3","related_sections":[]}],"practice":[{"q":"原癌基因在正常细胞中是否必定有害？","given":"问正常功能。","analysis":"名称不等于正常时已致癌。","method":"区分正常调控与异常激活。","principle":"正常生长需要相应信号通路。","steps":["正常原癌基因可参与受控生长。","异常激活才可能推动不受控过程。"],"ans":"不是。","verification":"没有正常生长调控同样不利组织功能。","pitfall":"把名称中的癌理解为存在就患癌。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":13,"primary_section":"13.3","related_sections":[]},{"q":"DNA受损后一定发生癌变吗？","given":"未给修复与细胞结局。","analysis":"损伤和稳定癌变之间有多个关口。","method":"列损伤应答。","principle":"修复、周期停滞与死亡可限制扩增。","steps":["损伤可被修复。","无法修复的细胞可能停滞或死亡，多变化积累才可能导致癌变。"],"ans":"不一定。","verification":"风险增加并非确定事件。","pitfall":"省略调控与选择过程。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":13,"primary_section":"13.3","related_sections":[]},{"q":"具有癌症易感性的家族，是否所有成员都会患同一种癌？","given":"有遗传易感信息而无个体诊断。","analysis":"易感是风险变化不是必然结果。","method":"结合其他遗传、环境与随机因素。","principle":"外显与发病受多因素影响。","steps":["同一易感变异可增加风险。","其他因素与防护使结局仍可不同。"],"ans":"不能推断所有成员必患。","verification":"风险不是100%的同义词。","pitfall":"把易感变异直接当作疾病已发生。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":13,"primary_section":"13.3","related_sections":[]},{"q":"甲培养组原有1000细胞，新生200、死亡150；乙原有1000，新生100、死亡10。比较末数量并解释为什么分裂多未必长得多。","given":"封闭体系，观察时间相同。","analysis":"需要计算净变化。","method":"原数加产生减死亡。","principle":"细胞总数守恒。","steps":["甲1000+200−150=1050。","乙1000+100−10=1090，比甲多40。"],"ans":"甲1050，乙1090；乙净增长更多。","verification":"甲净50，乙净90。","pitfall":"把分裂数和净增数等同。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":13,"primary_section":"13.3","related_sections":[]}],"quiz":{"q":"“癌细胞会转移，所以任何癌症都能通过接触患者传染。”这一推理错误在哪里？","given":"比较体内转移与个体间传播。","analysis":"两种过程所跨越的边界不同。","method":"定义后指出不能推出的结论。","principle":"转移指癌细胞在同一个体内扩散定植；感染性风险因素是另一问题。","steps":["先说明转移发生在体内组织间。","部分病毒可增加某些癌症风险，不等于癌细胞通过日常接触普遍传染。"],"ans":"把体内转移混同个体间传染。","verification":"能解释病毒相关性，也不错误推广所有癌症。","pitfall":"由一个词的扩散含义作无条件类推。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":13,"primary_section":"13.3","related_sections":[]},"exam":["判断题先分正常增殖、异常调控、侵袭与转移","实验题分别评价肿瘤细胞、正常细胞和对照，结论限定观察条件","风险题用可能性语言，不把相关性、易感与确诊混写"],"quick":["周期信号","损伤应答","异常克隆","侵袭与转移","证据边界"],"exam_evidence":[],"content_sources":[{"source_id":"directory_bio","url":"https://elearning.dongzong.my/pluginfile.php/77546/mod_resource/content/1/高中生物.pdf","page":4,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_bio_13.3","url":"https://openstax.org/books/biology-2e/pages/10-4-cancer-and-the-cell-cycle","page_or_section":"10-4-cancer-and-the-cell-cycle","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_bio","url":"https://elearning.dongzong.my/pluginfile.php/77546/mod_resource/content/1/高中生物.pdf","page":4,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_bio_13.3","url":"https://openstax.org/books/biology-2e/pages/10-4-cancer-and-the-cell-cycle","page_or_section":"10-4-cancer-and-the-cell-cycle","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"判断题先分正常增殖、异常调控、侵袭与转移","method":"比较两类细胞并列证据缺口。","principle":"治疗评价需有效性、安全性及可达暴露。","worked_example_index":2,"verification":"正常细胞18%低于癌细胞20%，并不支持明显选择优势。","pitfall":"用体外杀细胞直接宣传治疗效果。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“解释周期调控失常与肿瘤发展的关系”的抽样复核：正常根尖或胚胎的高分裂率也是反例。；若出现“把单一相关指标当作充分诊断条件。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“区分风险因素、相关性与诊断证据”的抽样复核：正常细胞18%低于癌细胞20%，并不支持明显选择优势。；若出现“用体外杀细胞直接宣传治疗效果。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"由一个词的扩散含义作无条件类推。","correction":"把体内转移混同个体间传染。","verification":"能解释病毒相关性，也不错误推广所有癌症。"}],"illustration_spec":{"title":"周期调控失常与证据边界","objects":["正常生长信号","检查点","损伤修复","异常克隆","局部侵袭","转移"],"relations":["损伤不必然癌变","多环节失调增加异常扩增可能","转移为同一个体内过程"],"labels":["正常调控","修复/停滞/死亡","异常扩增","证据不足不能诊断"],"format":"SVG","priority":"P1","reuse":"无完全匹配旧图","english":"Compare regulated growth with a multistep loss of control. Show repair, arrest and cell death as alternative responses to DNA damage; distinguish local invasion from metastasis within one individual."}}},"生物18":{"18.1":{"subject":"生物","subject_code":"biology","chapter_id":18,"section_id":"18.1","goals":["由结构推断细菌的生命活动","区分原核结构与真核细胞器"],"prerequisites":["细胞膜与核糖体","扩散与渗透"],"flow":["细胞膜","拟核与质粒","核糖体","细胞壁差异","附属结构"],"concept_relation":"细胞膜；拟核与质粒；核糖体；细胞壁差异；附属结构","deep":["部分细菌有荚膜或其他糖被，可影响附着、抗干燥与宿主相互作用；部分有菌毛或鞭毛，功能取决于具体结构。菌毛不等于所有鞭毛的简称，附着结构也不能一概解释成游动器官。结构图应标明“典型模型、部分结构并非每种都有”。","主染色体之外，部分细菌还有能独立复制的质粒。质粒可携带抗性等基因，但不能说所有抗性都在质粒上，或细菌没有质粒就无法生存。二分裂复制并分配遗传物质，不经过真核有丝分裂的纺锤体阶段。","细胞体积小带来较大的表面积体积比，有利于物质交换，但生长速率仍受营养、温度、氧等多因素限制。用球菌、杆菌、螺旋形等形态可作初步描述，不能只凭外形确定致病性或具体物种。","观察图像先区分边界层，再辨认DNA、核糖体和附属结构。光学显微镜和电子显微镜分辨能力不同，一张简单染色光学照片不能支持“已看见质粒双链”之类精细结论。图示放大比例也不能当作各结构在真实细胞中精确的大小比例。"],"derive":["球形模型表面积A=4πr²、体积V=4πr³/3，所以A/V=3/r；半径减半，表面积体积比加倍。","细菌能量代谢的论证应从膜、酶和反应途径出发，不能由“无粒线体”推出“无ATP”。","结构识别须区分必备的细胞膜、核糖体等与部分细菌才有的质粒、荚膜和鞭毛。"],"examples":[{"q":"某细胞无核膜，有细胞膜、拟核和核糖体，是否能因无细胞核而判它不是细胞？","given":"观察到膜、DNA集中区和核糖体。","analysis":"核膜有无用于区分原核与真核，不用于否定细胞性。","method":"依次检查细胞组织特征。","principle":"原核细胞不具有膜包围的细胞核。","steps":["拟核说明有遗传物质区域。","膜与核糖体符合细胞结构，可考虑原核细胞。"],"ans":"不能；这些特征支持原核细胞。","verification":"病毒本身没有这样的核糖体和完整细胞质体系。","pitfall":"将无核膜误写为无DNA。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":18,"primary_section":"18.1","related_sections":[]},{"q":"两个近似球形细菌半径为0.5 μm和1 μm，表面积体积比各是多少？","given":"只作球形几何模型。","analysis":"相对交换面积取决于A/V。","method":"推导3/r再代入。","principle":"同形缩放时面积按长度平方、体积按立方。","steps":["0.5 μm者A/V=3/0.5=6 μm⁻¹。","1 μm者A/V=3 μm⁻¹。"],"ans":"6 μm⁻¹和3 μm⁻¹。","verification":"半径小一半，比值大一倍。","pitfall":"把较大细胞的总面积与单位体积交换能力混同。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":18,"primary_section":"18.1","related_sections":[]},{"q":"学生说细菌没有线粒体，因此任何细菌都不能有氧呼吸。如何评价？","given":"确定没有真核线粒体。","analysis":"反应途径与真核细胞器位置不能无条件绑定。","method":"区分结构缺少与代谢能力。","principle":"某些细菌的呼吸链位于细胞膜等结构。","steps":["无粒线体仅说明细胞器结构不同。","能否有氧呼吸要核对其酶和电子传递系统，不能由此否定。"],"ans":"结论错误，部分细菌能有氧呼吸。","verification":"与需氧细菌的生长事实相容。","pitfall":"把真核反应场所当成所有生物的必要细胞器。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":18,"primary_section":"18.1","related_sections":[]}],"practice":[{"q":"质粒是否就是被核膜包围的小细胞核？","given":"问细菌质粒。","analysis":"DNA分子与细胞器不同。","method":"比较构成和边界。","principle":"质粒是染色体之外可复制的DNA分子。","steps":["不以核膜包围。","部分细菌具有，不构成真核细胞核。"],"ans":"不是。","verification":"原核定义仍成立。","pitfall":"见到独立DNA就叫细胞核。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":18,"primary_section":"18.1","related_sections":[]},{"q":"一张细菌模式图画了荚膜、鞭毛、质粒，是否表示所有细菌都有？","given":"图为典型教学模型。","analysis":"模式图可汇集并非普遍的结构。","method":"读取适用范围并分别分类。","principle":"附属结构存在与否因种类而异。","steps":["细胞膜和核糖体属基本细胞结构。","荚膜、鞭毛与质粒不能无条件普及到全部细菌。"],"ans":"不是，需注明部分细菌才有。","verification":"无鞭毛细菌仍可存活。","pitfall":"将模式图当作所有个体的清单。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":18,"primary_section":"18.1","related_sections":[]},{"q":"用鞭毛数量能直接确定一种细菌是否致病吗？","given":"仅有运动附属结构信息。","analysis":"致病性需要其他机制及宿主证据。","method":"区分结构功能与疾病结论。","principle":"运动能力不等于致病性。","steps":["鞭毛可参与运动。","是否致病还需毒力、感染及宿主等证据。"],"ans":"不能。","verification":"有运动结构也可为非致病种。","pitfall":"把可能接近宿主当作充分致病证据。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":18,"primary_section":"18.1","related_sections":[]},{"q":"半径从1 μm增至2 μm，球形模型体积与A/V分别变几倍？","given":"形状不变。","analysis":"两量按不同缩放规律变化。","method":"分别计算立方与倒数。","principle":"V∝r³，A/V∝1/r。","steps":["体积变2³=8倍。","A/V从3变1.5 μm⁻¹，即原来1/2。"],"ans":"体积8倍，比值1/2。","verification":"总表面积4倍而体积8倍，4/8=1/2。","pitfall":"把体积变化套成面积的4倍。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":18,"primary_section":"18.1","related_sections":[]}],"quiz":{"q":"显微图上没有画出质粒，是否证明该细菌一定没有抗性基因？","given":"模式图未标质粒，无基因检测。","analysis":"图示遗漏与不存在不同。","method":"列基因所在位置及证据限制。","principle":"抗性可与染色体或质粒基因等有关。","steps":["图未画出不能当作检测阴性。","即使无质粒，也不能排除染色体相关抗性。"],"ans":"不能证明。","verification":"须用相应遗传或表型实验判断。","pitfall":"从示意图缺失推出分子不存在。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":18,"primary_section":"18.1","related_sections":[]},"exam":["结构题先写结构—作用—适用范围，不机械罗列器官名称","推断题区分无某细胞器与无某反应能力","图像题说明分辨率限制，不能把模式图当实测比例"],"quick":["细胞膜","拟核与质粒","核糖体","细胞壁差异","附属结构"],"exam_evidence":[],"content_sources":[{"source_id":"directory_bio","url":"https://elearning.dongzong.my/pluginfile.php/77546/mod_resource/content/1/高中生物.pdf","page":6,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_bio_18.1","url":"https://openstax.org/books/biology-2e/pages/22-2-structure-of-prokaryotes","page_or_section":"22-2-structure-of-prokaryotes","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_bio","url":"https://elearning.dongzong.my/pluginfile.php/77546/mod_resource/content/1/高中生物.pdf","page":6,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_bio_18.1","url":"https://openstax.org/books/biology-2e/pages/22-2-structure-of-prokaryotes","page_or_section":"22-2-structure-of-prokaryotes","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"结构题先写结构—作用—适用范围，不机械罗列器官名称","method":"区分结构缺少与代谢能力。","principle":"某些细菌的呼吸链位于细胞膜等结构。","worked_example_index":2,"verification":"与需氧细菌的生长事实相容。","pitfall":"把真核反应场所当成所有生物的必要细胞器。"},"diagnostics":[{"goal_index":0,"question_ref":"e2","review_module":4,"feedback":"目标“由结构推断细菌的生命活动”的抽样复核：与需氧细菌的生长事实相容。；若出现“把真核反应场所当成所有生物的必要细胞器。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e0","review_module":5,"feedback":"目标“区分原核结构与真核细胞器”的抽样复核：病毒本身没有这样的核糖体和完整细胞质体系。；若出现“将无核膜误写为无DNA。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"从示意图缺失推出分子不存在。","correction":"不能证明。","verification":"须用相应遗传或表型实验判断。"}],"illustration_spec":{"title":"典型细菌结构及适用边界","objects":["细胞膜","肽聚糖壁","拟核","核糖体","可选质粒荚膜鞭毛"],"relations":["DNA无核膜包围","核糖体无膜","可选结构须标部分细菌具有"],"labels":["拟核","核糖体","细胞膜","细胞壁","部分细菌具有"],"format":"SVG","priority":"P0","reuse":"V22现有图需逐结构对照后决定","english":"Draw a typical bacterium without a nucleus or mitochondria. Label nucleoid, ribosomes, membrane and peptidoglycan wall. Clearly mark capsule, plasmid and flagellum as optional structures."}},"18.2":{"subject":"生物","subject_code":"biology","chapter_id":18,"section_id":"18.2","goals":["用条件解释生长曲线与实验结果","按可比设计评价抑菌实验"],"prerequisites":["二分裂","浓度与对照实验"],"flow":["营养与水","温度pH和氧","指数与限制","生长曲线","测量对象"],"concept_relation":"营养与水；温度pH和氧；指数与限制；生长曲线；测量对象","deep":["氧的作用因代谢类型不同：专性需氧、专性厌氧、兼性厌氧等对氧有不同需求或耐受。不能以“呼吸需要氧”把所有细菌置于有氧条件，也不能把缺氧下的生长一律解释成发酵，具体电子受体和代谢途径还需证据。","封闭液体培养的典型曲线包括调整期、对数期、稳定期与衰亡期。调整期可有代谢适应，未见数量明显增加并非完全无生命活动；稳定期净数量变化接近零，也不代表所有细胞停止分裂；衰亡期活菌数下降不一定与总颗粒数同步。","研究一个条件应尽量保持其余变量一致，设合适对照和重复，并说明测量的是浊度、菌落形成单位还是直接计数。浊度不能简单等于活菌数；一个菌落可能来自一团细胞，CFU不是任何条件下准确的单细胞数。","学校实验须采用批准的低风险材料、遵守指导和废弃物处理要求，不培养来源不明的人体或环境微生物。以下题目只分析给定数据，不能当作在家培养病原体的操作指南。抑菌圈大小同时受扩散、浓度等影响，不能只凭直径排名临床疗效。"],"derive":["理想倍增：N=N₀×2ᵏ，k=t/g，g为稳定条件下代时；只适用于相应指数阶段。","平板计数估算原液浓度=菌落数/(接种体积×稀释倍数)，单位CFU/mL；依赖可培养、分散和计数范围等条件。","净数量变化=繁殖产生−死亡；不同测量方式可能给不同曲线。"],"examples":[{"q":"给定理想对数期初有500个细胞，代时30 min，90 min后有多少？","given":"无死亡且条件稳定。","analysis":"先算倍增次数。","method":"N=N₀×2^(t/g)。","principle":"每代二分裂使数量乘2。","steps":["k=90/30=3。","N=500×2³=4000。"],"ans":"4000个。","verification":"依次1000、2000、4000，共三代。","pitfall":"把90当作倍增次数。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":18,"primary_section":"18.2","related_sections":[]},{"q":"10⁻⁵稀释液0.1 mL产生80 CFU，估算原液CFU/mL并说明限制。","given":"计数在允许范围，假定样品均匀。","analysis":"原液等效体积小于接种体积。","method":"用菌落数除原液等效体积。","principle":"浓度×体积对应可培养单位数。","steps":["原液等效体积=0.1×10⁻⁵=10⁻⁶ mL。","80/10⁻⁶=8×10⁷ CFU/mL；菌团与不可培养细胞影响解释。"],"ans":"8×10⁷ CFU/mL，非必然等于单细胞总数。","verification":"该浓度稀释10⁵倍后每0.1 mL为80 CFU。","pitfall":"忘记0.1 mL而少算10倍。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":18,"primary_section":"18.2","related_sections":[]},{"q":"药物甲抑菌圈大于乙，能否仅凭此认定甲在人体内疗效更好？","given":"培养与纸片实验结果，无体内资料。","analysis":"直径同时取决扩散等因素。","method":"列控制条件及临床证据缺口。","principle":"体外抑菌与人体安全有效性不同。","steps":["需核浓度、扩散和对照。","体内还涉及吸收、组织暴露、毒性与病原敏感性。"],"ans":"不能。","verification":"扩散快即使效力不更强也可能圈更大。","pitfall":"把单一体外指标直接当成治疗排名。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":18,"primary_section":"18.2","related_sections":[]}],"practice":[{"q":"冷藏是否等于灭菌？","given":"只降低储存温度。","analysis":"抑制与杀灭不同。","method":"比较过程目标。","principle":"低温通常减慢部分微生物代谢。","steps":["存活细菌可在恢复适宜条件后再增殖。","灭菌需经验证的相应过程。"],"ans":"不等于。","verification":"冷藏食品仍有保存期限。","pitfall":"把暂时不增殖当作死亡。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":18,"primary_section":"18.2","related_sections":[]},{"q":"稳定期活菌总数近似不变，是否说明分裂数为零？","given":"测得净数量稳定。","analysis":"净值为零可能是产生与死亡相抵。","method":"列数量平衡式。","principle":"净增=产生−死亡。","steps":["若每小时产生100又死亡100，净增0。","因此须测周转才能判断分裂。"],"ans":"不一定。","verification":"两项非零但差为零即反例。","pitfall":"把净变化当作单向过程。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":18,"primary_section":"18.2","related_sections":[]},{"q":"比较pH对生长的影响，温度是否可同时任意改变？","given":"目标为单因素解释。","analysis":"混杂变量会妨碍因果判断。","method":"保持温度等可比并重复。","principle":"只改变自变量以隔离效应。","steps":["设置多个pH水平。","温度、培养时间、起始量等尽量一致。"],"ans":"不可任意改变。","verification":"否则无法区分pH与温度效应。","pitfall":"用多变量变化却归因于一个因素。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":18,"primary_section":"18.2","related_sections":[]},{"q":"200个细胞代时20 min，理想生长1 h后几倍、多少？若晚期营养耗尽还能照算吗？","given":"前1 h在指数阶段。","analysis":"公式含条件限制。","method":"先计算再审查外推。","principle":"二分裂指数模型只在稳定代时条件下。","steps":["k=60/20=3，倍数8。","N=200×8=1600；营养耗尽后不能继续用原代时无限外推。"],"ans":"8倍、1600；不能无条件外推。","verification":"三次倍增对应400、800、1600。","pitfall":"将理想曲线延伸至所有培养阶段。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":18,"primary_section":"18.2","related_sections":[]}],"quiz":{"q":"浊度近似不变而CFU下降，是否必然实验错误？","given":"两种测量读数不同。","analysis":"浊度与可培养活菌并非同一指标。","method":"比较各自测量对象。","principle":"死细胞和颗粒也可能散射光，CFU只计相应培养条件下单位。","steps":["活菌失去培养能力可使CFU下降。","颗粒仍在时浊度未必同步下降。"],"ans":"不必然，先检查指标与方法。","verification":"结论同时解释两种读数，无需预设全部颗粒消失。","pitfall":"把所有计数方法视为等价。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":18,"primary_section":"18.2","related_sections":[]},"exam":["曲线题先看纵轴是活菌、总数还是浊度，再解释阶段","倍增题列代时条件，稀释题用等效原液体积验算","实验题控制起始量等变量，并区分抑制、杀灭、临床效力"],"quick":["营养与水","温度pH和氧","指数与限制","生长曲线","测量对象"],"exam_evidence":[],"content_sources":[{"source_id":"directory_bio","url":"https://elearning.dongzong.my/pluginfile.php/77546/mod_resource/content/1/高中生物.pdf","page":6,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_bio_18.2","url":"https://openstax.org/books/biology-2e/pages/22-3-prokaryotic-metabolism","page_or_section":"22-3-prokaryotic-metabolism","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_bio","url":"https://elearning.dongzong.my/pluginfile.php/77546/mod_resource/content/1/高中生物.pdf","page":6,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_bio_18.2","url":"https://openstax.org/books/biology-2e/pages/22-3-prokaryotic-metabolism","page_or_section":"22-3-prokaryotic-metabolism","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"曲线题先看纵轴是活菌、总数还是浊度，再解释阶段","method":"列控制条件及临床证据缺口。","principle":"体外抑菌与人体安全有效性不同。","worked_example_index":2,"verification":"扩散快即使效力不更强也可能圈更大。","pitfall":"把单一体外指标直接当成治疗排名。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“用条件解释生长曲线与实验结果”的抽样复核：依次1000、2000、4000，共三代。；若出现“把90当作倍增次数。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“按可比设计评价抑菌实验”的抽样复核：扩散快即使效力不更强也可能圈更大。；若出现“把单一体外指标直接当成治疗排名。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"把所有计数方法视为等价。","correction":"不必然，先检查指标与方法。","verification":"结论同时解释两种读数，无需预设全部颗粒消失。"}],"illustration_spec":{"title":"细菌生长曲线与测量边界","objects":["时间轴","活菌数对数轴","四时期","浊度与CFU对照"],"relations":["对数期直线对应原数量指数增加","稳定期净增长近零","死细胞可仍贡献浊度"],"labels":["调整期","对数期","稳定期","衰亡期","log活菌数"],"format":"SVG","priority":"P0","reuse":"无完全匹配旧图","english":"Plot viable bacterial count on a logarithmic vertical axis against time, showing lag, exponential, stationary and death phases. Explain that turbidity and CFU measure different things."}},"18.3":{"subject":"生物","subject_code":"biology","chapter_id":18,"section_id":"18.3","goals":["由核酸与衣壳描述病毒","解释病毒为何依赖宿主而非自行分裂"],"prerequisites":["DNA与RNA","蛋白质合成"],"flow":["基因组","衣壳","可选包膜","宿主识别","依赖翻译"],"concept_relation":"基因组；衣壳；可选包膜；宿主识别；依赖翻译","deep":["病毒不具有完整的核糖体与代谢系统，通常依赖宿主的物质、能量及翻译装置产生新组分。它并非在细胞外靠摄食生长后自行二分裂；复制是合成核酸与蛋白质再组装产生颗粒。某些病毒携带或编码必需的酶，这不等于已经有完整独立代谢。","宿主范围和组织嗜性与识别、进入以及细胞内部能否支持复制等条件有关。有受体并非任何条件下都足以使细胞被生产性感染，没有合适受体也不能据某一种途径推断所有途径都绝对不可能；题目应限定病毒与系统。","噬菌体感染细菌，是病毒的一类，并非细菌的一部分。常用带头部和尾部的模型只代表某些噬菌体，不能把所有动物、植物病毒都画成同一种“登月器”形状。动物病毒、植物病毒的进入方式和外形也不统一。","比较生物特征时，病毒有遗传与变异能力，却缺乏细胞结构和宿主之外的自主繁殖。可以据不同定义讨论其生命边界，但不能用“有无生命”替代具体机制。抗细菌药物作用于细胞壁合成等靶点时，对没有这些结构的病毒通常无相同直接作用。"],"derive":["结构最低模型：病毒基因组 + 衣壳；部分另有包膜及表面蛋白。","基因组类型须具体到所讨论病毒，不能把DNA病毒和RNA病毒的路线合并成一张无条件流程图。","病毒增殖不是细胞二分裂：宿主内合成组分 → 组装 → 释放，依赖条件须逐项说明。"],"examples":[{"q":"发现一个颗粒含RNA和蛋白质衣壳，无核糖体，是否可因为有遗传物质就称为细胞？","given":"无细胞质与独立翻译体系。","analysis":"遗传物质不是细胞性的充分条件。","method":"比较病毒与细胞组织。","principle":"细胞需膜围住的细胞质及相应生命活动体系。","steps":["RNA可作为病毒基因组。","衣壳与无核糖体的组合符合病毒模型，不能仅凭RNA称细胞。"],"ans":"不能；需结合证据考虑病毒。","verification":"真核与原核细胞都有核糖体，与该模型不同。","pitfall":"把所有含核酸实体都归为细胞。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":18,"primary_section":"18.3","related_sections":[]},{"q":"某病毒外有脂质包膜，能否据此说它有细胞膜所以是细胞？","given":"包膜含病毒表面蛋白。","analysis":"膜的存在不自动构成完整细胞。","method":"解释包膜来源与内部缺失。","principle":"包膜常由宿主膜获得，病毒无完整细胞代谢体系。","steps":["外层包膜参与保护与进入。","内部仍是基因组、衣壳等病毒组分，并非完整细胞质组织。"],"ans":"不能，包膜不等于细胞性。","verification":"无包膜病毒也能感染，细胞性不由该单项决定。","pitfall":"按有一层膜作全部分类。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":18,"primary_section":"18.3","related_sections":[]},{"q":"药物阻止细菌肽聚糖合成，是否应直接抑制所有病毒增殖？","given":"只知药物该靶点，不假设其他作用。","analysis":"病毒无肽聚糖细胞壁。","method":"按结构—靶点关系判断。","principle":"特异作用必须有相应靶标。","steps":["细菌壁合成可被影响。","病毒缺该壁，不能从此靶点推出抗病毒效果。"],"ans":"不能据此推出。","verification":"病毒依赖宿主不代表它拥有宿主或细菌全部结构。","pitfall":"把感染性实体混为同一药物靶点。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":18,"primary_section":"18.3","related_sections":[]}],"practice":[{"q":"所有病毒都有包膜吗？","given":"比较基本与可选结构。","analysis":"包膜不是普遍条件。","method":"列核心与部分结构。","principle":"衣壳和基因组构成基本模型。","steps":["部分病毒有包膜。","无包膜病毒亦可具有感染性。"],"ans":"不是。","verification":"模型图须注明部分具有。","pitfall":"把特定病毒图推广至全部。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":18,"primary_section":"18.3","related_sections":[]},{"q":"病毒依赖宿主，是否说明它没有任何基因？","given":"问题混合独立性和遗传。","analysis":"依赖不能推出无基因组。","method":"区分遗传信息与表达装置。","principle":"病毒基因组编码相应组分但翻译依赖宿主。","steps":["遗传信息仍存在。","缺独立核糖体等使它依赖细胞。"],"ans":"不是。","verification":"没有基因组无法说明其稳定遗传特性。","pitfall":"把无独立代谢说成无遗传。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":18,"primary_section":"18.3","related_sections":[]},{"q":"噬菌体的宿主是细菌，能说噬菌体就是细菌吗？","given":"按感染关系命名。","analysis":"宿主与感染者分类不同。","method":"列两者细胞结构差异。","principle":"噬菌体是病毒。","steps":["细菌具有细胞膜、核糖体。","噬菌体以基因组和衣壳等组成，利用细菌复制。"],"ans":"不能。","verification":"感染对象不等于自身分类。","pitfall":"把寄生者与宿主当作同一实体。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":18,"primary_section":"18.3","related_sections":[]},{"q":"一病毒图画DNA和RNA两条链都标为同一病毒的基因组，却未说明特殊情况或中间体，应怎样修正？","given":"拟描述一般单一病毒类型。","analysis":"无条件拼接不同类型会误导。","method":"先指定病毒模型，再标基因组及必要中间体。","principle":"基因组类型与复制过程产物须分开。","steps":["选择明确DNA或RNA基因组示例。","若表示逆转录，应把另一核酸标成复制中间体并写条件。"],"ans":"区分基因组与中间体，不能都无条件标为基因组。","verification":"结构与生命周期图应互相一致。","pitfall":"将所有复制相关核酸都叫基因组。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":18,"primary_section":"18.3","related_sections":[]}],"quiz":{"q":"两个颗粒一大一小，可否仅凭尺寸判大者是细菌、小者是病毒？","given":"无结构和复制证据。","analysis":"尺寸范围可有重叠且图比例不一定相同。","method":"要求结构与宿主依赖证据。","principle":"分类应依据组织结构及生命活动方式。","steps":["检查膜、核糖体、拟核等。","再判断是否依赖细胞组装增殖，并核实实际标尺。"],"ans":"不能只据尺寸。","verification":"即使常见趋势存在，也不能作为无例外判据。","pitfall":"把示意图大小当实测分类标准。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":18,"primary_section":"18.3","related_sections":[]},"exam":["比较题用细胞结构、核糖体、基因组、增殖方式逐项对照","药物题先找靶点再判断对象，不用病毒比细菌小作理由","流程题先指明病毒类型，明确基因组与中间体"],"quick":["基因组","衣壳","可选包膜","宿主识别","依赖翻译"],"exam_evidence":[],"content_sources":[{"source_id":"directory_bio","url":"https://elearning.dongzong.my/pluginfile.php/77546/mod_resource/content/1/高中生物.pdf","page":6,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_bio_18.3","url":"https://openstax.org/books/biology-2e/pages/21-1-viral-evolution-morphology-and-classification","page_or_section":"21-1-viral-evolution-morphology-and-classification","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_bio","url":"https://elearning.dongzong.my/pluginfile.php/77546/mod_resource/content/1/高中生物.pdf","page":6,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_bio_18.3","url":"https://openstax.org/books/biology-2e/pages/21-1-viral-evolution-morphology-and-classification","page_or_section":"21-1-viral-evolution-morphology-and-classification","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"比较题用细胞结构、核糖体、基因组、增殖方式逐项对照","method":"按结构—靶点关系判断。","principle":"特异作用必须有相应靶标。","worked_example_index":2,"verification":"病毒依赖宿主不代表它拥有宿主或细菌全部结构。","pitfall":"把感染性实体混为同一药物靶点。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“由核酸与衣壳描述病毒”的抽样复核：真核与原核细胞都有核糖体，与该模型不同。；若出现“把所有含核酸实体都归为细胞。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"p1","review_module":5,"feedback":"目标“解释病毒为何依赖宿主而非自行分裂”的抽样复核：没有基因组无法说明其稳定遗传特性。；若出现“把无独立代谢说成无遗传。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"把示意图大小当实测分类标准。","correction":"不能只据尺寸。","verification":"即使常见趋势存在，也不能作为无例外判据。"}],"illustration_spec":{"title":"病毒、细菌与细胞结构对比","objects":["无包膜病毒","有包膜病毒","细菌","基因组","衣壳","核糖体"],"relations":["病毒图不画核糖体或完整胞质","包膜标部分具有","外形不统一"],"labels":["DNA或RNA基因组","衣壳","部分病毒有包膜","非按比例"],"format":"SVG","priority":"P0","reuse":"须核现有病毒图类型后复用","english":"Compare an explicitly identified non-enveloped virus, enveloped virus and bacterium. Do not give virions ribosomes, cytoplasm or peptidoglycan. Mark figures as not to scale and distinguish genome from replication intermediates."}},"18.4":{"subject":"生物","subject_code":"biology","chapter_id":18,"section_id":"18.4","goals":["按条件说明病毒生命周期","区分个体内增殖与个体间传播"],"prerequisites":["病毒结构","细胞膜与核酸复制"],"flow":["进入与脱壳","合成组分","组装释放","裂解与溶原","传播链与预防"],"concept_relation":"进入与脱壳；合成组分；组装释放；裂解与溶原；传播链与预防","deep":["动物病毒可通过膜融合或内吞等途径进入，基因组复制与基因表达依类型而异。有包膜病毒可通过出芽获得膜，释放未必立即裂解宿主；无包膜与有包膜也不能简单对应“必死”和“不死”，宿主损伤须具体分析。","逆转录病毒以RNA为基因组，经逆转录形成DNA，再参与后续过程；其路线与一般直接将DNA转录成RNA的叙述不同。抗病毒药物可针对某些病毒特有的酶或进入步骤，但是否有效及安全须经验证，不能从流程图任意推断治疗方案。","传播描述病毒从一个宿主或来源到另一个易感宿主的过程，可能与呼吸道、体液、接触、媒介等有关，具体依病毒及环境而定。体内复制速度与人群传播能力不是同一个量；单一传播途径也不能推广所有病毒。","预防措施应对应实际传播链环节，疫苗主要通过免疫准备降低感染或严重结局风险，不能说任何疫苗都保证完全阻断所有感染。抗生素不能因“感染”一词便当作抗病毒药；如有细菌并发感染，治疗判断属另一证据层面。"],"derive":["裂解模型：吸附 → 遗传物质进入 → 组分合成 → 组装 → 释放；进入细胞的成分须依病毒类型画清。","若理想每个感染细胞释放b个可感染颗粒，连续k轮的数量上限模型可写N₀bᵏ；前提是宿主充足、颗粒全部成功感染等，不可当作真实传播预测。","个体内病毒复制、感染性颗粒数、个体间新病例是不同变量，不能无条件互换。"],"examples":[{"q":"某噬菌体图中尾部留在细胞外而遗传物质进入，能否把整个噬菌体都画进细胞？","given":"图描述特定注入式噬菌体模型。","analysis":"进入成分已由题设限定。","method":"按进入方式重画边界。","principle":"该模型中衣壳通常留于外部。","steps":["遗传物质穿过包被进入。","衣壳尾部保留在外侧，随后细胞内合成新组分。"],"ans":"不能在此模型把完整颗粒画入。","verification":"后续新衣壳由细胞内合成而非旧衣壳直接复制。","pitfall":"套用动物病毒内吞模型。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":18,"primary_section":"18.4","related_sections":[]},{"q":"理想系统10个细胞各被一个颗粒感染，每细胞释放50个感染性颗粒，一轮后多少？能预测实际人群病例吗？","given":"无失败与损失，仅一轮。","analysis":"颗粒产量与病例数不同。","method":"先计算再限定结论。","principle":"产量=细胞数×单细胞产量。","steps":["10×50=500个感染性颗粒。","病例还受接触、宿主易感性和进入效率等限制。"],"ans":"500个；不能直接作为病例数。","verification":"单位是颗粒而非人。","pitfall":"把病毒数当作感染人数。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":18,"primary_section":"18.4","related_sections":[]},{"q":"细胞长期带有前噬菌体DNA而未裂解，是否证明噬菌体遗传物质没有复制？","given":"宿主在生长并复制DNA。","analysis":"溶原复制不同于大量组装释放。","method":"追踪前噬菌体随宿主复制。","principle":"整合状态可随宿主遗传物质传递。","steps":["细菌复制其染色体时可一并复制前噬菌体。","未裂解只说明未观察到裂解释放，不能推出DNA未复制。"],"ans":"不能证明。","verification":"宿主后代继续含该序列支持遗传传递。","pitfall":"把不释放颗粒等同于无复制。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":18,"primary_section":"18.4","related_sections":[]}],"practice":[{"q":"病毒是否都通过宿主立即裂解释放？","given":"比较出芽与裂解。","analysis":"释放方式有差异。","method":"列反例并限定。","principle":"某些有包膜病毒可出芽。","steps":["出芽可取得膜。","未必立即导致细胞裂解，实际损伤依病毒而异。"],"ans":"不是。","verification":"与裂解噬菌体模型并不矛盾。","pitfall":"将一种生命周期推广全部。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":18,"primary_section":"18.4","related_sections":[]},{"q":"逆转录指RNA到DNA还是DNA到RNA？","given":"问该酶作用方向。","analysis":"名称相对常见转录方向。","method":"标底物与产物。","principle":"逆转录以RNA为模板合成DNA。","steps":["先识别RNA模板。","DNA产物可进入后续生命周期。"],"ans":"RNA到DNA。","verification":"DNA到RNA为通常转录。","pitfall":"把方向箭头反画。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":18,"primary_section":"18.4","related_sections":[]},{"q":"一种病毒经媒介传播，是否可推出全部病毒都经同一种媒介？","given":"只知单一病毒途径。","analysis":"样本范围有限。","method":"限定结论至对象。","principle":"传播依病毒生态与宿主环境。","steps":["该病毒的防护需针对相应传播链。","其他病毒需各自证据，不能沿用。"],"ans":"不能。","verification":"呼吸道与媒介等途径不同。","pitfall":"将局部途径当普遍规律。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":18,"primary_section":"18.4","related_sections":[]},{"q":"理想每轮感染性颗粒乘20，从5个起始经两轮多少？为什么这不是可靠的人群预测？","given":"全部成功感染且宿主无限的假设。","analysis":"数学上可算，现实条件严格。","method":"5×20²并列假设失效点。","principle":"逐轮乘积模型。","steps":["一轮100个。","二轮2000个；真实宿主、免疫和传播瓶颈使模型受限。"],"ans":"2000个，非2000病例预测。","verification":"100×20=2000，单位仍颗粒。","pitfall":"把理想模型写成现实确定结果。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":18,"primary_section":"18.4","related_sections":[]}],"quiz":{"q":"已知疫苗训练免疫系统，能否声称所有接种者绝不会感染？","given":"没有具体疫苗效果数据。","analysis":"免疫准备不等于绝对屏障。","method":"区分降低风险与完全阻断。","principle":"效果依疫苗、病原与个体等。","steps":["疫苗可改善免疫应答并降低部分风险。","不能用无条件百分之百替代证据。"],"ans":"不能作绝对保证。","verification":"感染、重症与传播风险应分别评价。","pitfall":"用预防作用推出零风险。","question_origin":"original","paper_no":null,"subject_code":"biology","chapter_id":18,"primary_section":"18.4","related_sections":[]},"exam":["生命周期题先定病毒类型再标进入、合成、组装与释放","过程干预题明确药物靶步骤，不能由示意图宣称临床有效","传播题区分颗粒产量、个体内复制与人群新病例"],"quick":["进入与脱壳","合成组分","组装释放","裂解与溶原","传播链与预防"],"exam_evidence":[],"content_sources":[{"source_id":"directory_bio","url":"https://elearning.dongzong.my/pluginfile.php/77546/mod_resource/content/1/高中生物.pdf","page":6,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_bio_18.4","url":"https://openstax.org/books/biology-2e/pages/21-2-virus-infections-and-hosts","page_or_section":"21-2-virus-infections-and-hosts","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_bio","url":"https://elearning.dongzong.my/pluginfile.php/77546/mod_resource/content/1/高中生物.pdf","page":6,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_bio_18.4","url":"https://openstax.org/books/biology-2e/pages/21-2-virus-infections-and-hosts","page_or_section":"21-2-virus-infections-and-hosts","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"生命周期题先定病毒类型再标进入、合成、组装与释放","method":"追踪前噬菌体随宿主复制。","principle":"整合状态可随宿主遗传物质传递。","worked_example_index":2,"verification":"宿主后代继续含该序列支持遗传传递。","pitfall":"把不释放颗粒等同于无复制。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“按条件说明病毒生命周期”的抽样复核：后续新衣壳由细胞内合成而非旧衣壳直接复制。；若出现“套用动物病毒内吞模型。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e1","review_module":5,"feedback":"目标“区分个体内增殖与个体间传播”的抽样复核：单位是颗粒而非人。；若出现“把病毒数当作感染人数。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"用预防作用推出零风险。","correction":"不能作绝对保证。","verification":"感染、重症与传播风险应分别评价。"}],"illustration_spec":{"title":"病毒增殖类型与传播层次","objects":["噬菌体裂解/溶原分支","宿主细胞边界","动物病毒出芽","宿主间传播单独框"],"relations":["不得把所有病毒画成注入式噬菌体","复制与传播分开","逆转录方向RNA到DNA"],"labels":["吸附","合成","组装","释放","前噬菌体","非所有病毒相同"],"format":"SVG","priority":"P0","reuse":"现有生命周期图须按类型复核","english":"Draw explicitly separated examples of phage lytic and lysogenic cycles and enveloped animal-virus budding. Distinguish intracellular replication from between-host transmission; label reverse transcription RNA to DNA only in the appropriate example."}}},"化学26":{"26.1":{"subject":"化学","subject_code":"chemistry","chapter_id":26,"section_id":"26.1","goals":["按组成与结构解释有机化合物分类","由燃烧数据求最简式并检查证据限制"],"prerequisites":["物质的量","化学式与配平"],"flow":["碳的连接","有机与无机约定","烃与衍生物","最简式分子式","结构证据"],"concept_relation":"碳的连接；有机与无机约定；烃与衍生物；最简式分子式；结构证据","deep":["分子式给出一个分子的原子种类和数目，最简式给出最小整数比，结构式进一步显示连接。相同分子式可对应不同连接或空间排列，所以元素分析或燃烧分析本身通常不能唯一确定结构。","完全燃烧分析把样品中的碳转为CO₂、氢转为H₂O，在产物定量收集且无其他来源等条件下，可由n(C)=n(CO₂)、n(H)=2n(H₂O)求元素比。若样品还含氧且仅含C、H、O，可用样品质量减碳氢质量求氧，不能在未知元素存在时随意用差值全部算成氧。","由元素比求最简式时先换为摩尔数再除最小值，处理接近简单分数的比例须结合测量不确定性；不是一律对每个比值直接四舍五入。要确定分子式，还需要相对分子质量等独立信息，倍数应为接近整数。","本章的结构与计算是后续官能团和反应规律的基础。所有例题为原创分析模型，不代表已确认正式UEC出题频率。真实实验的完全燃烧、产物吸收和样品纯度均会影响数据解释，课堂理想数据不等于任何装置都能无误差复现。"],"derive":["完全燃烧且定量收集：n(C)=n(CO₂)，n(H)=2n(H₂O)。","仅含C/H/O时，m(O)=m样−m(C)−m(H)，再n(O)=m(O)/16 g·mol⁻¹。","分子式=(最简式)ₖ，k=M分子/M最简式；k应为正整数，结构仍需其他证据。"],"examples":[{"q":"CH₄、C₂H₅OH、CO₂、Na₂CO₃中，按通常学科约定哪些属有机物，哪些属烃？","given":"按本节常见分类约定。","analysis":"有机物与烃不是同一集合。","method":"先判有机，再核是否仅C/H。","principle":"烃只含碳氢，CO₂和碳酸盐通常归无机。","steps":["CH₄和C₂H₅OH归有机。","其中CH₄仅含C/H属烃；乙醇含O不属烃。"],"ans":"有机：甲烷、乙醇；烃：仅甲烷。","verification":"其余两项虽含C但在约定无机类。","pitfall":"把所有含碳物都叫烃。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.1","related_sections":[]},{"q":"0.30 g仅含C/H/O样品完全燃烧得0.44 g CO₂和0.18 g H₂O，求最简式。取C12、H1、O16。","given":"产物定量且碳氢均来自样品。","analysis":"由产物先求C/H，氧用质量差。","method":"摩尔数及元素质量守恒。","principle":"CO₂每摩尔含1 mol C，H₂O含2 mol H。","steps":["n(C)=0.44/44=0.010 mol；n(H)=2×0.18/18=0.020 mol。","mC=0.12 g，mH=0.02 g，mO=0.30−0.14=0.16 g，nO=0.010 mol。","比C:H:O=1:2:1。"],"ans":"CH₂O。","verification":"最简式质量分数C40%、H约6.67%、O约53.33%，对应0.30 g各质量。","pitfall":"将水的摩尔数直接当H原子摩尔数。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.1","related_sections":[]},{"q":"某物质最简式CH₂O，相对分子质量60，能确定分子式和唯一结构吗？","given":"最简式式量30。","analysis":"分子式倍数可定，连接不可仅此定。","method":"k=60/30。","principle":"元素比例和分子量约束原子数，不唯一约束连接。","steps":["k=2，分子式C₂H₄O₂。","同分子式可存在不同结构，需结构或反应等证据。"],"ans":"分子式C₂H₄O₂，不能唯一确定结构。","verification":"式量24+4+32=60。","pitfall":"把最简式当分子式或直接认定唯一官能团。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.1","related_sections":[]}],"practice":[{"q":"C₆H₁₂O₆的最简式是？它是烃吗？","given":"只按分子式分析。","analysis":"先约简再分类。","method":"各下标除最大公因数。","principle":"最简式为最小整数比，烃不能含O。","steps":["6:12:6除6得1:2:1。","含氧，不能归烃。"],"ans":"CH₂O；不是烃。","verification":"(CH₂O)₆恢复原式。","pitfall":"把有机物自动当烃。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.1","related_sections":[]},{"q":"某样品除C/H外还可能有N，能把剩余质量全算O吗？","given":"元素种类未确定。","analysis":"差值可能包含N等。","method":"先确定元素组成。","principle":"质量守恒不提供未知元素身份。","steps":["减去C/H只得其余元素总质量。","需氮等检测或题给仅C/H/O才能归O。"],"ans":"不能。","verification":"若剩余全部为N，氧差值法会完全错误。","pitfall":"以差值法替代元素鉴定。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.1","related_sections":[]},{"q":"最简式CH，相对分子质量78，分子式？取C12、H1。","given":"式量13。","analysis":"求整数倍。","method":"78/13=6。","principle":"原子比例放大同倍数。","steps":["k=6。","分子式C₆H₆，式量72+6=78。"],"ans":"C₆H₆。","verification":"C:H仍1:1。","pitfall":"只把C乘6而H不乘。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.1","related_sections":[]},{"q":"仅含C/H的0.28 g样品燃烧得0.88 g CO₂、0.36 g H₂O，求最简式并用质量检查。","given":"完全燃烧且产物定量。","analysis":"先C/H摩尔比，再总质量。","method":"nC=nCO₂，nH=2nH₂O。","principle":"原子数与质量守恒。","steps":["nC=.88/44=.020；nH=2×.36/18=.040 mol。","比1:2，最简式CH₂。","mC=.24、mH=.04，共.28 g。"],"ans":"CH₂，与样品质量相符。","verification":"无须由最简式推断一定为某一特定烯烃。","pitfall":"比值2就直接说分子式C₂H₄。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.1","related_sections":[]}],"quiz":{"q":"同一最简式的两个物质，是否必有相同分子式和性质？","given":"未给分子量与结构。","analysis":"最简比例信息有限。","method":"分别列可能倍数与连接差异。","principle":"分子式和结构层次比最简式更具体。","steps":["最简式可用不同整数倍构成分子式。","即使分子式相同也可能结构不同、性质不同。"],"ans":"不必。","verification":"CH₂O与C₂H₄O₂最简式同而分子式不同。","pitfall":"以相同比例推出同种物质。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.1","related_sections":[]},"exam":["分类题逐项查元素和约定例外，烃只是有机物子类","燃烧题先产物摩尔数再数C/H原子，氧差值需仅含C/H/O","结构推断题写清最简式、分子式与连接分别需要何证据"],"quick":["碳的连接","有机与无机约定","烃与衍生物","最简式分子式","结构证据"],"exam_evidence":[],"content_sources":[{"source_id":"directory_chem","url":"https://elearning.dongzong.my/pluginfile.php/77540/mod_resource/content/1/高中化学.pdf","page":13,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_chem_26.1","url":"https://openstax.org/books/chemistry-2e/pages/20-1-hydrocarbons","page_or_section":"20-1-hydrocarbons","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_chem","url":"https://elearning.dongzong.my/pluginfile.php/77540/mod_resource/content/1/高中化学.pdf","page":13,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_chem_26.1","url":"https://openstax.org/books/chemistry-2e/pages/20-1-hydrocarbons","page_or_section":"20-1-hydrocarbons","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"分类题逐项查元素和约定例外，烃只是有机物子类","method":"k=60/30。","principle":"元素比例和分子量约束原子数，不唯一约束连接。","worked_example_index":2,"verification":"式量24+4+32=60。","pitfall":"把最简式当分子式或直接认定唯一官能团。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“按组成与结构解释有机化合物分类”的抽样复核：其余两项虽含C但在约定无机类。；若出现“把所有含碳物都叫烃。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e1","review_module":5,"feedback":"目标“由燃烧数据求最简式并检查证据限制”的抽样复核：最简式质量分数C40%、H约6.67%、O约53.33%，对应0.30 g各质量。；若出现“将水的摩尔数直接当H原子摩尔数。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"以相同比例推出同种物质。","correction":"不必。","verification":"CH₂O与C₂H₄O₂最简式同而分子式不同。"}],"illustration_spec":{"title":"组成、分子式与结构的信息层次","objects":["分类集合","CO₂/H₂O燃烧产物","C/H/O摩尔比","最简式","分子式","结构证据"],"relations":["烃仅C/H","nH=2nH₂O","氧差值需元素范围条件","分子式不能自动唯一结构"],"labels":["有机物","烃","CH₂O","C₂H₄O₂","定量收集"],"format":"SVG","priority":"P0","reuse":"可复用物质的量流程局部，非完整有机分类图","english":"Show hydrocarbons as the carbon-and-hydrogen-only subset, with CO2 and carbonates treated as conventional inorganic exceptions. Trace quantitative combustion products to C/H atom amounts, then empirical and molecular formulas; require extra evidence for unique connectivity."}},"26.2":{"subject":"化学","subject_code":"chemistry","chapter_id":26,"section_id":"26.2","goals":["用结构与分子间作用解释常见性质趋势","识别概括规律的例外并评价实验结论"],"prerequisites":["共价键与分子间作用","溶解与导电"],"flow":["结构差异","分子间作用","溶解与电离","燃烧条件","趋势与例外"],"concept_relation":"结构差异；分子间作用；溶解与电离；燃烧条件；趋势与例外","deep":["许多纯共价有机物不含自由移动离子，因而导电弱，但有机酸在水中可电离，有机盐或其他有机材料也可导电。实验必须分清纯物质、溶液及浓度，不能用一次无明显电流排除所有有机物。","不少含碳氢有机物可燃，完全燃烧可生成CO₂、H₂O等；氧不足可能生成CO和烟炱，含其他元素还可能有别的产物。仅看产生烟不能唯一判定物质身份，也不能认为完全燃烧的全部有机物产物只有两种。","有机反应常涉及特定官能团与条件，可能产生混合物、经历多步骤或有副反应，但有些反应也很快。反应速率、平衡与产率是不同概念：反应快不自动给高纯度或高产率，反应慢也不表示热力学上不可发生。","把趋势用于题目时先确定比较对象属于哪类结构，并核温度、溶剂、压力及纯度等条件。用结构推理提出可检验预测，然后与数据比较；如果有例外，追查结构或条件，而不是删去不合口诀的数据。"],"derive":["分子内键决定连接；熔沸常涉及分子间作用，两者不能混同。","同类结构比较氢键、极性、相对分子质量和形状，避免单因素无条件推断。","电导须有可移动载流子；水溶性与导电性不是同一性质。"],"examples":[{"q":"学生说乙醇沸腾必把每个C—C键断开，为什么不对？","given":"正常沸腾而非分解。","analysis":"相变与化学分解不同。","method":"区分分子内键与分子间吸引。","principle":"汽化主要使分子彼此分离。","steps":["液态转气态时乙醇分子通常仍保留连接。","所克服主要是分子间作用，包括氢键等。"],"ans":"把相变误当分子内化学键断裂。","verification":"蒸气冷凝仍可回到乙醇，不需重新合成C—C键。","pitfall":"以所有吸引都叫键而混淆层次。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.2","related_sections":[]},{"q":"甲乙分子大小近似，甲有可形成分子间氢键的OH，乙无且极性弱，预测沸点并说明限制。","given":"其他结构尽量相近，不指定具体数值。","analysis":"氢键可增强相互吸引。","method":"按分子间作用比较。","principle":"较强分子间作用通常需更高温度分离。","steps":["甲通常有较高沸点的理由。","仍需核实际形状、其他作用与压力，不把预测当无例外定理。"],"ans":"通常预测甲较高，需实测或可靠数据确认。","verification":"没有结构可比条件时不能只看一个基团。","pitfall":"把OH数量当唯一决定因素。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.2","related_sections":[]},{"q":"糖溶液几乎不导电，醋酸溶液能弱导电，能否说后者不属有机物？","given":"两者均为相应有机物水溶液。","analysis":"导电取决移动离子，不是有机分类判据。","method":"比较是否产生离子。","principle":"酸可在水中部分电离。","steps":["糖主要以分子溶解。","醋酸可产生少量离子，故可导电而仍属有机。"],"ans":"不能；有机物也可形成导电溶液。","verification":"溶于水不自动离子化，分类与电离不同。","pitfall":"把有机物不导电当绝对规律。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.2","related_sections":[]}],"practice":[{"q":"有机物都不溶于水吗？","given":"问普遍命题。","analysis":"需要反例和机制。","method":"用可形成氢键小分子说明。","principle":"水溶性依结构与相互作用。","steps":["乙醇等小分子可与水良好混合。","非极性长链又常难溶，不能统一。"],"ans":"不是。","verification":"同属有机物仍有不同极性和碳链。","pitfall":"把常见烃的性质推广所有有机物。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.2","related_sections":[]},{"q":"一种有机物不完全燃烧产CO，能说违反碳守恒吗？","given":"氧可能不足。","analysis":"守恒原子不要求只生成CO₂。","method":"配平简单示例。","principle":"原子可分配到不同产物。","steps":["2CH₄+3O₂→2CO+4H₂O。","两侧C2、H8、O6守恒。"],"ans":"不违反。","verification":"氧不足使产物分布不同，碳仍守恒。","pitfall":"把完全燃烧产物当唯一可能。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.2","related_sections":[]},{"q":"某反应很快，是否产率必为100%？","given":"未给平衡、副反应与收集。","analysis":"速率和产率不同。","method":"列造成产率损失的过程。","principle":"产率是实际目标产物/理论量。","steps":["快速可能也快速生成副产物。","平衡、分离和损失仍可降低目标收率。"],"ans":"不必。","verification":"快只说明时间尺度，不提供目标产物总量。","pitfall":"把快、完全、纯三者混同。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.2","related_sections":[]},{"q":"乙醇样品0.10 mol完全燃烧，理论CO₂与H₂O各多少？若实测水少能直接说H不守恒吗？","given":"C₂H₅OH+3O₂→2CO₂+3H₂O。","analysis":"先按配平计量，后审实验收集。","method":"产物摩尔比2与3。","principle":"原子守恒与测量边界。","steps":["CO₂=.20 mol，H₂O=.30 mol。","水少可能因未定量收集、未完全反应等，不能据此宣称守恒失效。"],"ans":"0.20与0.30 mol；须查条件。","verification":"C原子.20 mol、H原子.60 mol与原料相合。","pitfall":"用测量损失否定守恒。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.2","related_sections":[]}],"quiz":{"q":"一种分子含OH又有很长烃链，能仅凭OH断言它与水任意比例互溶吗？","given":"同时有亲水与非极性部分。","analysis":"需比较整体结构。","method":"分析两类作用竞争并需数据。","principle":"溶解由综合相互作用决定。","steps":["OH可增强与水相互作用。","长烃链可降低水溶性，不能只凭单一基团给无限互溶结论。"],"ans":"不能。","verification":"同类醇随碳链增长可出现不同溶解行为。","pitfall":"只见官能团而忽略骨架。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.2","related_sections":[]},"exam":["性质解释题从结构、作用、宏观性质三层连接","分类题不能把溶解或电导当单一判据，先辨纯物质/溶液","实验异常题查纯度、条件和收集，不用绝对口诀覆盖数据"],"quick":["结构差异","分子间作用","溶解与电离","燃烧条件","趋势与例外"],"exam_evidence":[],"content_sources":[{"source_id":"directory_chem","url":"https://elearning.dongzong.my/pluginfile.php/77540/mod_resource/content/1/高中化学.pdf","page":13,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_chem_26.2","url":"https://openstax.org/books/chemistry-2e/pages/20-2-alcohols-and-ethers","page_or_section":"20-2-alcohols-and-ethers","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_chem","url":"https://elearning.dongzong.my/pluginfile.php/77540/mod_resource/content/1/高中化学.pdf","page":13,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_chem_26.2","url":"https://openstax.org/books/chemistry-2e/pages/20-2-alcohols-and-ethers","page_or_section":"20-2-alcohols-and-ethers","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"性质解释题从结构、作用、宏观性质三层连接","method":"比较是否产生离子。","principle":"酸可在水中部分电离。","worked_example_index":2,"verification":"溶于水不自动离子化，分类与电离不同。","pitfall":"把有机物不导电当绝对规律。"},"diagnostics":[{"goal_index":0,"question_ref":"e1","review_module":4,"feedback":"目标“用结构与分子间作用解释常见性质趋势”的抽样复核：没有结构可比条件时不能只看一个基团。；若出现“把OH数量当唯一决定因素。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“识别概括规律的例外并评价实验结论”的抽样复核：溶于水不自动离子化，分类与电离不同。；若出现“把有机物不导电当绝对规律。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"只见官能团而忽略骨架。","correction":"不能。","verification":"同类醇随碳链增长可出现不同溶解行为。"}],"illustration_spec":{"title":"结构与宏观性质的条件关系","objects":["分子内共价键","分子间氢键","水与小分子醇","长链醇","分子与离子溶液"],"relations":["相变不画C—C键普遍断裂","OH亲水性须结合碳链","导电依可移动离子"],"labels":["共价键","分子间作用","非极性部分","可移动离子","趋势非绝对"],"format":"SVG","priority":"P1","reuse":"氢键旧图可局部复用，需核乙醇羟基连接","english":"Distinguish intramolecular covalent bonds from intermolecular hydrogen bonding during boiling. Contrast a small alcohol with a long hydrocarbon chain bearing OH, and neutral molecular solutes with ion-producing solutes. Never imply all organic compounds are insoluble or nonconducting."}},"26.3":{"subject":"化学","subject_code":"chemistry","chapter_id":26,"section_id":"26.3","goals":["按骨架与官能团分别分类","以连接关系解释同分子式不同类别"],"prerequisites":["碳四价","结构式与分子式"],"flow":["骨架分类","关键连接","官能团","多官能团","证据与价键"],"concept_relation":"骨架分类；关键连接；官能团；多官能团；证据与价键","deep":["识别官能团要核原子连接环境：醇羟基与饱和碳相连，酚羟基直接连芳香环；羧基中的OH属于羧基整体，不能因为看到OH就把羧酸简单归醇。醚有C—O—C连接，酯有C(=O)—O—C，额外羰基改变类别。","醛常用—CHO表示，羰基碳连接H；酮羰基碳连接两个碳基团。羧酸有—COOH，酯的酸性OH被相应烃基氧连接形式替代。使用缩写时不漏必要原子，例如—CHO的O与C双键不能画成任意串联单键。","分类可帮助预测可能反应，但同官能团受邻近基团、空间和条件影响，不能只凭标签断言所有反应产物和速率相同。多官能团分子还要分析哪个部位在给定试剂与条件下反应。","答题时先把缩写还原到关键连接，再分骨架和官能团作答。若只有分子式，可列合理候选并指出还需证据，不把“可能含双键”写成“必是烯烃”，更不能为符合通式擅自忽略环。"],"derive":["分类至少分两轴：碳骨架（链/环等）与官能团（醇/醚/醛/酮/酸/酯等）。","CnH₂n可对应单环饱和烃或单烯烃等相应模型，不能仅由通式唯一判类别。","画结构后核每个C常见四价、O常见二价、H一价；官能团按连接环境识别。"],"examples":[{"q":"CH₃CH₂OH和CH₃OCH₃分子式相同吗、类别相同吗？","given":"两式均为完整中性分子。","analysis":"统计原子与判断连接是两步。","method":"数原子再识别O的邻接。","principle":"同分子式可为不同官能团的异构体。","steps":["二者均C₂H₆O。","前者OH连饱和碳属醇，后者C—O—C属醚。"],"ans":"分子式同，类别不同。","verification":"前者O连C与H，后者O连两个C。","pitfall":"只看有氧就归同一官能团。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.3","related_sections":[]},{"q":"分子式C₃H₆能唯一断言是烯烃吗？","given":"没有其他结构或反应证据。","analysis":"环也可减少相对烷烃的氢数。","method":"给两种结构候选。","principle":"分子式不唯一确定骨架。","steps":["丙烯CH₂=CHCH₃符合。","环丙烷三个CH₂成环也符合。"],"ans":"不能；至少有烯烃和环烷烃候选。","verification":"两者均C3H6且价键可满足。","pitfall":"仅按CnH₂n就判唯一。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.3","related_sections":[]},{"q":"CH₃COOH和CH₃COOCH₃分别是什么类别？为什么不能把前者只叫醇？","given":"CO表示所示羰基缩写，需还原。","analysis":"OH属于羧基环境。","method":"辨C(=O)—OH与C(=O)—O—C。","principle":"官能团取决连接。","steps":["前者含羧基属羧酸。","后者含酯基属酯；羧酸OH不等同饱和碳上的醇羟基。"],"ans":"羧酸、酯。","verification":"各O均满足常见价键；羰基不可漏画。","pitfall":"只抓OH字符串而忽略连接的羰基碳。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.3","related_sections":[]}],"practice":[{"q":"CH₃CHO中关键官能团？","given":"末端羰基碳连H。","analysis":"还原CHO缩写。","method":"写CH₃—C(=O)—H。","principle":"醛的羰基碳有H连接。","steps":["中心C与O双键。","另连CH₃和H，故为醛基。"],"ans":"醛基，属醛。","verification":"碳键级总数4。","pitfall":"把CHO画成C—H—O直链。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.3","related_sections":[]},{"q":"CH₃COCH₃属于醛还是酮？","given":"羰基两侧为CH₃。","analysis":"羰基碳无H。","method":"辨邻接原子。","principle":"酮羰基连两个碳基团。","steps":["C=O两侧各连一个CH₃。","因此为酮。"],"ans":"酮。","verification":"分子式C₃H₆O，结构决定类别。","pitfall":"凡有C=O都叫醛。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.3","related_sections":[]},{"q":"一个分子同时含NH₂与COOH，能否只允许它有一个官能团？","given":"给定不同部位均存在。","analysis":"多官能团常见。","method":"分别标识。","principle":"分类维度可重叠。","steps":["氨基与羧基各自保留。","具体反应需按条件分析两处，不必删一个。"],"ans":"不能，应分别识别。","verification":"氨基酸类可体现这种组合。","pitfall":"为单一标签漏掉知识点。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.3","related_sections":[]},{"q":"C₂H₄O₂的两个候选CH₃COOH与HCOOCH₃，分别计原子、判类，能用分子式单独区分吗？","given":"两结构按常见缩写。","analysis":"需核组成相同连接不同。","method":"展开关键羰基和氧连接。","principle":"官能团异构。","steps":["前者C2H4O2、羧酸。","后者C2H4O2、酯，分子式不能单独区分。"],"ans":"二者同分子式而异类。","verification":"HCOOCH₃含醛式H连接羰基但整体为酯，不简单把所有H—C=O都孤立分类。","pitfall":"忽略羰基另一侧O连接环境。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.3","related_sections":[]}],"quiz":{"q":"结构图在醚的氧上画三条普通共价单键且不标电荷，作为普通中性醚是否正确？","given":"无特殊带电说明。","analysis":"常见中性氧价键数受约束。","method":"核每原子价与整体电荷。","principle":"中性醚O通常形成两条单键。","steps":["C—O—C给两连接。","第三单键需相应带电等特殊说明，不能画成普通中性醚。"],"ans":"不正确，应修为两键或明确特殊电荷结构。","verification":"逐原子价核查可发现漂亮图的科学错误。","pitfall":"只看整体像官能团而不查局部价。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.3","related_sections":[]},"exam":["分类题先还原连接，再说骨架与官能团","分子式题列候选和所缺证据，别由通式唯一判类别","绘图题逐原子核价、电荷和隐含H，尤其羰基与羧基"],"quick":["骨架分类","关键连接","官能团","多官能团","证据与价键"],"exam_evidence":[],"content_sources":[{"source_id":"directory_chem","url":"https://elearning.dongzong.my/pluginfile.php/77540/mod_resource/content/1/高中化学.pdf","page":13,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_chem_26.3","url":"https://openstax.org/books/chemistry-2e/pages/20-3-aldehydes-ketones-carboxylic-acids-and-esters","page_or_section":"20-3-aldehydes-ketones-carboxylic-acids-and-esters","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_chem","url":"https://elearning.dongzong.my/pluginfile.php/77540/mod_resource/content/1/高中化学.pdf","page":13,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_chem_26.3","url":"https://openstax.org/books/chemistry-2e/pages/20-3-aldehydes-ketones-carboxylic-acids-and-esters","page_or_section":"20-3-aldehydes-ketones-carboxylic-acids-and-esters","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"分类题先还原连接，再说骨架与官能团","method":"辨C(=O)—OH与C(=O)—O—C。","principle":"官能团取决连接。","worked_example_index":2,"verification":"各O均满足常见价键；羰基不可漏画。","pitfall":"只抓OH字符串而忽略连接的羰基碳。"},"diagnostics":[{"goal_index":0,"question_ref":"e2","review_module":4,"feedback":"目标“按骨架与官能团分别分类”的抽样复核：各O均满足常见价键；羰基不可漏画。；若出现“只抓OH字符串而忽略连接的羰基碳。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e0","review_module":5,"feedback":"目标“以连接关系解释同分子式不同类别”的抽样复核：前者O连C与H，后者O连两个C。；若出现“只看有氧就归同一官能团。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"只看整体像官能团而不查局部价。","correction":"不正确，应修为两键或明确特殊电荷结构。","verification":"逐原子价核查可发现漂亮图的科学错误。"}],"illustration_spec":{"title":"有机分类的连接判据","objects":["乙醇/二甲醚","羧酸/酯","醛/酮","丙烯/环丙烷"],"relations":["同式不一定同连接","羧酸OH不画成独立醇","每个C和O满足价键"],"labels":["醇","醚","羧酸","酯","醛","酮","分子式≠唯一结构"],"format":"SVG","priority":"P0","reuse":"现有化学结构图须核官能团后局部复用","english":"Compare ethanol with dimethyl ether, carboxylic acid with ester, aldehyde with ketone, and propene with cyclopropane. Render explicit correct connectivity and valence; do not classify a carboxylic OH as an alcohol or infer a unique structure from a molecular formula."}},"26.4":{"subject":"化学","subject_code":"chemistry","chapter_id":26,"section_id":"26.4","goals":["把分离纯化、组成与结构证据分层","由多项资料作有限且可检验的推断"],"prerequisites":["有机分类","计量与实验变量"],"flow":["分离纯化","组成分子式","结构证据","候选排除","产率与报告"],"concept_relation":"分离纯化；组成分子式；结构证据；候选排除；产率与报告","deep":["元素分析和相对分子质量帮助确定组成，化学反应、光谱等进一步约束连接。不同证据回答不同问题：分子式不能直接代替结构，单一颜色变化也往往不能唯一确定物种，需适当对照及综合判断。","结构表示法包括分子式、结构式、简式和模型，各有用途与省略规则。转换时应守住原子数和连接，骨架式省略的碳氢需按端点、转折与价键规则补齐，不能将视觉上短一笔误认为化学组成相同。","本节可用光谱信号或反应证据作逻辑练习，但具体仪器细节和峰位是否属于2027考试范围需另核，不把拓展方法冒充官方要求。题给信号只能按题设可靠规则使用，不能从一个未经说明的峰值虚构完整谱图。","实验报告把原始观察、推导、假设和结论分开，并报告产率、纯度及不确定性。粗产物质量超过理论值可能来自杂质或残留溶剂，不意味着反应违反守恒或创造物质；真实改进应找到损失和污染来源而非美化数据。"],"derive":["Rf=d斑点/d前沿，同一起点同一板且前沿距离非零；无量纲。","产率=实际目标产物量/理论目标产物量×100%；粗样质量不一定等于纯产物质量。","研究证据链：纯度与分离 → 元素组成 → 分子式 → 关键连接证据 → 排除候选 → 再验证。"],"examples":[{"q":"同一色谱板斑点距起点3.0 cm，前沿6.0 cm，Rf多少？单位是什么？","given":"两距离沿同方向、同一起点。","analysis":"比值相同长度单位相消。","method":"Rf=3/6。","principle":"迁移相对距离。","steps":["Rf=.50。","cm/cm相消，不带cm。"],"ans":"0.50，无单位。","verification":"斑点在前沿一半位置符合。","pitfall":"把3 cm当Rf或保留cm。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.4","related_sections":[]},{"q":"理论产物5.0 g，收得粗产物5.5 g，能宣布产率110%且合成创造物质吗？","given":"未测纯度与残留溶剂。","analysis":"粗质量不是纯目标量。","method":"先查杂质并求纯目标产率。","principle":"守恒与产物纯度。","steps":["5.5/5.0=110%是表观粗质量比。","可能含溶剂或副产物，需纯化/定量，不能称纯产率或物质创造。"],"ans":"不能，应调查纯度和干燥等。","verification":"加入非目标质量足以解释超理论。","pitfall":"把容器中所有质量都算目标产物。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.4","related_sections":[]},{"q":"候选为乙醇或二甲醚，分子式均C₂H₆O；题设可靠证据显示有与H相连的O，能排除哪一个？","given":"只使用题给连接证据。","analysis":"分子式不区分，OH连接可区分。","method":"比较候选结构。","principle":"乙醇有O—H，二甲醚O连两C。","steps":["乙醇CH₃CH₂OH符合。","二甲醚CH₃OCH₃不含O—H，因此排除。"],"ans":"排除二甲醚，支持乙醇候选。","verification":"结论限定这两个候选，不声称在全世界所有物质中唯一。","pitfall":"仅凭分子量46就直接确定乙醇。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.4","related_sections":[]}],"practice":[{"q":"Rf相同能无条件证明是同一物质吗？","given":"仅给一个色谱条件的相同迁移。","analysis":"不同物质可能共迁移。","method":"补多条件或独立鉴别。","principle":"单一特征不一定唯一。","steps":["相同Rf表示该条件下迁移相似。","需其他色谱条件或结构证据支持身份。"],"ans":"不能。","verification":"两个组分共迁移可呈一个斑点。","pitfall":"把单一比值当身份证。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.4","related_sections":[]},{"q":"两个完全互溶液体能靠形成上下两层进行普通分液萃取吗？","given":"相同条件下完全互溶。","analysis":"分液需相分离。","method":"检查溶剂体系。","principle":"液液萃取通常要求可分开的相。","steps":["完全互溶不形成所需稳定两层。","需改用合适体系或其他分离方法，并遵规范。"],"ans":"不能按该两层模型直接操作。","verification":"无界面就没有题设的上下层分液。","pitfall":"只记分液漏斗名而忽略相性质。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.4","related_sections":[]},{"q":"某目标物受热易分解，简单加热至沸点一定适合纯化吗？","given":"稳定性不足。","analysis":"分离条件可改变物质本身。","method":"评估温压和替代方案。","principle":"纯化需保留目标物化学身份。","steps":["加热可能先分解再挥发。","需可靠条件与合适方法，不能只用沸点差决定。"],"ans":"不一定。","verification":"若目标被破坏，收集到的不是原物。","pitfall":"只比较沸点不审热稳定性。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.4","related_sections":[]},{"q":"理论6.5 g，实收6.0 g粗样纯度86.7%，估纯产物产率。","given":"纯度指目标物质量分数，按题给数。","analysis":"先扣除杂质质量。","method":"m纯=m粗×纯度，再除理论。","principle":"产率应以目标物量比较。","steps":["m纯=6.0×.867=5.202 g。","产率5.202/6.5×100%≈80.0%。"],"ans":"约80%。","verification":"若错用粗量会得92.3%，明显忽略杂质。","pitfall":"把纯度86.7%直接当产率。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.4","related_sections":[]}],"quiz":{"q":"一条仪器信号支持某官能团，是否可以跳过全部其他证据宣布唯一分子结构？","given":"没有完整谱或候选约束。","analysis":"局部特征不唯一决定整体。","method":"列剩余骨架与连接不确定。","principle":"结构鉴定通常综合多证据。","steps":["同官能团可存在于多种分子。","需组成、分子量和其他连接信息排除候选。"],"ans":"不能无条件。","verification":"乙醇与其他醇均可有O—H。","pitfall":"把官能团信号当完整结构图。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.4","related_sections":[]},"exam":["研究题明确每项证据能回答哪层问题，结论不超范围","色谱题保持同相同条件，Rf无单位且不是唯一身份","产率题先辨粗样、纯度与目标量，再按配平理论量计算"],"quick":["分离纯化","组成分子式","结构证据","候选排除","产率与报告"],"exam_evidence":[],"content_sources":[{"source_id":"directory_chem","url":"https://elearning.dongzong.my/pluginfile.php/77540/mod_resource/content/1/高中化学.pdf","page":13,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_chem_26.4","url":"https://openstax.org/books/chemistry-2e/pages/4-4-reaction-yields","page_or_section":"4-4-reaction-yields","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"IUPAC_Rf","url":"https://goldbook.iupac.org/terms/view/R05353/html","page_or_section":"retardation factor in planar chromatography","version":"IUPAC术语定义；非2027范围","access_date":"2026-11-18","verification_status":"verified_definition"}],"authoring_sources":[{"source_id":"directory_chem","url":"https://elearning.dongzong.my/pluginfile.php/77540/mod_resource/content/1/高中化学.pdf","page":13,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_chem_26.4","url":"https://openstax.org/books/chemistry-2e/pages/4-4-reaction-yields","page_or_section":"4-4-reaction-yields","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"IUPAC_Rf","url":"https://goldbook.iupac.org/terms/view/R05353/html","page_or_section":"retardation factor in planar chromatography","version":"IUPAC术语定义；非2027范围","access_date":"2026-11-18","verification_status":"verified_definition"}],"verification_status":"partially_verified","strategy":{"trigger":"研究题明确每项证据能回答哪层问题，结论不超范围","method":"比较候选结构。","principle":"乙醇有O—H，二甲醚O连两C。","worked_example_index":2,"verification":"结论限定这两个候选，不声称在全世界所有物质中唯一。","pitfall":"仅凭分子量46就直接确定乙醇。"},"diagnostics":[{"goal_index":0,"question_ref":"e1","review_module":4,"feedback":"目标“把分离纯化、组成与结构证据分层”的抽样复核：加入非目标质量足以解释超理论。；若出现“把容器中所有质量都算目标产物。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“由多项资料作有限且可检验的推断”的抽样复核：结论限定这两个候选，不声称在全世界所有物质中唯一。；若出现“仅凭分子量46就直接确定乙醇。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"把官能团信号当完整结构图。","correction":"不能无条件。","verification":"乙醇与其他醇均可有O—H。"}],"illustration_spec":{"title":"有机鉴定的证据层级","objects":["混合样","分离","元素分析","相对分子质量","结构候选","色谱板"],"relations":["Rf为同起点距离比","一个斑点不必纯","分子式不直接唯一连接","产率先扣杂质"],"labels":["Rf=3/6=0.50","粗样","纯度","最简式","分子式","连接证据"],"format":"SVG","priority":"P1","reuse":"无整体对应图；色谱距离须精确","english":"Show an evidence hierarchy from separation and purity to elemental composition, molecular formula and connectivity tests. Draw a chromatogram with spot travel 3 cm and solvent front 6 cm from the same baseline, Rf=0.50; state that one spot or one matching Rf is not proof of purity or identity."}},"26.5":{"subject":"化学","subject_code":"chemistry","chapter_id":26,"section_id":"26.5","goals":["从结构性能用途解释技术价值","依据收支和证据评价所谓绿色创新"],"prerequisites":["有机结构与材料","产率与系统边界"],"flow":["合成与身份","结构设计","材料与药物","绿色工艺","生命周期证据"],"concept_relation":"合成与身份；结构设计；材料与药物；绿色工艺；生命周期证据","deep":["聚合物把小单元连接成长链，为纤维、塑料及其他材料提供广泛性质。相同重复单元的材料还可因链长、支化、结晶和加工而表现不同，后续聚合物章节会系统展开；本节先说明结构层次与宏观性能之间的联系。","药物研发不只是找到能在试管中反应的分子，还需评估选择性、体内过程、安全与临床效果。细胞实验中抑制某过程是证据链的一部分，不足以证明人体疗效；教学例子不提供个体医疗判断。","绿色化学关注从源头减少危害与资源负担，可涉及催化、减少副产物、较低能耗与更安全原料。高产率不等于所有原子都进入目标产物，天然原料也不保证生命周期负担低；评价需有明确功能单位和边界。","分析“新材料更环保”的宣传，要看原料、制造、使用、回收和最终处置，区分可生物降解、可堆肥及可回收的条件。标签若缺温度、环境、时间和处理设施，不能从一个词推断在海洋或家中任何条件都会迅速无害消失。"],"derive":["产率衡量目标产物实际量/理论量；原子利用等工艺指标衡量另一个维度，不能互代。","给定工艺物料收支：输入质量=目标产物+副产物+未反应/损失等相应项，边界要完整。","技术评价：结构与机制 → 可测性能 → 使用条件 → 安全与环境 → 生命周期与证据限制。"],"examples":[{"q":"实验室合成的纯乙醇与天然发酵分离的纯乙醇，若结构与同位素等相关条件按题忽略，是否仅因来源不同而是两种化学物质？","given":"比较同样纯度、相同组成连接的理想样品。","analysis":"化学身份不能只按来源。","method":"按组成结构比较。","principle":"同一物质的关键身份由化学结构等确定。","steps":["二者均CH₃CH₂OH。","实际杂质可不同，但题设纯样条件下不能因合成/天然就判不同物质。"],"ans":"不能仅因来源判为不同物质。","verification":"来源信息不改变题给连接。","pitfall":"天然与合成必有完全不同化学式。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.5","related_sections":[]},{"q":"两工艺各投入100 kg原料，甲目标产物60 kg、副产物40 kg；乙目标80 kg、副20 kg，能仅据此认定乙在所有环境指标更好？","given":"只给此物料边界，未给危害与能源。","analysis":"较高目标质量比例是一个指标。","method":"先算比例，再列其他维度。","principle":"环境评价涉及毒性、能耗与处置等。","steps":["目标比例甲60%、乙80%。","乙在该质量指标较好，但原料危害、能耗、溶剂及寿命未知。"],"ans":"不能全面断言。","verification":"乙可能用更危险原料或更高能耗，当前数据无法排除。","pitfall":"一个高百分比替代整体环境评价。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.5","related_sections":[]},{"q":"材料标注“可降解”，能保证在任何环境短时间完全无害消失吗？","given":"无测试条件、时间与产物资料。","analysis":"术语有条件且降解产物仍需评价。","method":"要求测试环境和证据。","principle":"降解取决温湿度、微生物与材料结构等。","steps":["明确工业堆肥、土壤或其他环境及时间。","检测降解程度与产物，不能把标签推广海洋等所有条件。"],"ans":"不能保证。","verification":"同材料在干冷或无适宜微生物处可表现不同。","pitfall":"把有条件声明转成绝对环保承诺。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.5","related_sections":[]}],"practice":[{"q":"天然提取物是否一定无毒？","given":"无剂量和成分分析。","analysis":"来源不决定全部风险。","method":"核具体物质、纯度与暴露。","principle":"风险与危害及暴露有关。","steps":["天然物也可有强生物活性或毒性。","需证据评价，不可由天然二字保证安全。"],"ans":"不一定。","verification":"同样的分子不因来源天然就失去毒性。","pitfall":"天然等于安全。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.5","related_sections":[]},{"q":"催化剂让反应更快，是否把平衡常数任意提高？","given":"同一反应温度，讨论通常催化。","analysis":"动力学与平衡不同。","method":"区分路径活化与终态。","principle":"催化改变速率途径，不改变相同温度的平衡常数。","steps":["可使更快接近平衡。","不能由此说平衡组成必向目标移动。"],"ans":"不会仅靠催化任意改K。","verification":"正逆过程均可加快。","pitfall":"把快与平衡产率混同。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.5","related_sections":[]},{"q":"某药物候选在细胞实验有效，是否已可直接宣称人体治疗有效？","given":"缺体内与临床证据。","analysis":"层次外推受限。","method":"列安全、到达浓度及临床验证。","principle":"体外作用不等于人体结局。","steps":["需看选择性、吸收代谢和毒性等。","经相应研究才能评价人体有效性。"],"ans":"不能直接宣称。","verification":"试管所需浓度可能人体不可安全达到。","pitfall":"用一个实验跳过完整证据链。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.5","related_sections":[]},{"q":"工艺投入50 kg，可回收未反应原料10 kg，目标产品30 kg、副产物10 kg，检查物料收支；能把10 kg回收量直接算成产品吗？","given":"边界包含回收原料。","analysis":"回收与目标产物不同类别。","method":"总量相加并分类。","principle":"质量守恒不抹平物质身份。","steps":["10+30+10=50 kg，收支相符。","产品为30 kg，回收原料仍非产品，后续循环须另核实际转化。"],"ans":"收支相符；不能算40 kg产品。","verification":"分类总和守恒而目标量独立。","pitfall":"把回收原料充当已转化产物。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.5","related_sections":[]}],"quiz":{"q":"一种新聚合物强度提高，就能断言可回收性、毒性和碳足迹同时改善吗？","given":"只知力学指标。","analysis":"不同指标可能有权衡。","method":"要求各自测量与生命周期边界。","principle":"结构性能关联不提供所有环境结果。","steps":["强度需相应力学测试。","回收、危害与排放要各自证据，不能从强度单指标推出。"],"ans":"不能。","verification":"更强交联可能反而更难某些回收处理。","pitfall":"一项创新等于全面无代价提升。","question_origin":"original","paper_no":null,"subject_code":"chemistry","chapter_id":26,"primary_section":"26.5","related_sections":[]},"exam":["进展题写结构、机制、价值和限制，不堆未核年代","绿色评价把产率、原料危害、能耗与处置分开","证据题限定体外/体内与使用条件，不能将标签当完整验证"],"quick":["合成与身份","结构设计","材料与药物","绿色工艺","生命周期证据"],"exam_evidence":[],"content_sources":[{"source_id":"directory_chem","url":"https://elearning.dongzong.my/pluginfile.php/77540/mod_resource/content/1/高中化学.pdf","page":13,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_chem_26.5","url":"https://www.acs.org/green-chemistry-sustainability/principles/12-principles-of-green-chemistry.html","page_or_section":"12-principles-of-green-chemistry.html","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_chem","url":"https://elearning.dongzong.my/pluginfile.php/77540/mod_resource/content/1/高中化学.pdf","page":13,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_chem_26.5","url":"https://www.acs.org/green-chemistry-sustainability/principles/12-principles-of-green-chemistry.html","page_or_section":"12-principles-of-green-chemistry.html","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"进展题写结构、机制、价值和限制，不堆未核年代","method":"要求测试环境和证据。","principle":"降解取决温湿度、微生物与材料结构等。","worked_example_index":2,"verification":"同材料在干冷或无适宜微生物处可表现不同。","pitfall":"把有条件声明转成绝对环保承诺。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“从结构性能用途解释技术价值”的抽样复核：来源信息不改变题给连接。；若出现“天然与合成必有完全不同化学式。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“依据收支和证据评价所谓绿色创新”的抽样复核：同材料在干冷或无适宜微生物处可表现不同。；若出现“把有条件声明转成绝对环保承诺。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"一项创新等于全面无代价提升。","correction":"不能。","verification":"更强交联可能反而更难某些回收处理。"}],"illustration_spec":{"title":"有机创新的多指标评价","objects":["分子结构","性能测试","物料收支","能源输入","使用与处置","证据阶梯"],"relations":["来源不决定安全","产率不等同完整环境表现","降解条件须标明"],"labels":["结构—性能","目标产物","副产物","能耗","条件与时间","证据范围"],"format":"SVG","priority":"P2","reuse":"不需辅助插画替代科学关系；可用清晰结构图","english":"Map organic innovation from molecular structure to measured performance, material balance, energy use and end-of-life conditions. Distinguish natural origin from safety, reaction yield from overall environmental performance, and conditional degradability from universal harmless disappearance."}}},"数学3":{"3.1":{"subject":"数学","subject_code":"math_shared","chapter_id":3,"section_id":"3.1","goals":["按指数与系数判断多项式及次数","以恒等式完成运算和参数分类"],"prerequisites":["整式运算","指数与分配律"],"flow":["定义与次数","系数比较","加减乘","除法商余","参数退化"],"concept_relation":"定义与次数；系数比较；加减乘；除法商余；参数退化","deep":["加减运算按同次幂合并，乘法逐项分配再合并。次数的常见规律有条件：两个非零多项式乘积次数相加，和的次数不超过较高者且可能因首项抵消下降。零项与参数退化须单独处理。","多项式除法把被除式表示为除式乘商加余式。非零除式D确定时，余式R的次数必须小于D，或R=0；这个次数限制使商余表达具有唯一性。若余式次数仍高，说明除法尚未完成。","实际运算可按降幂排列，并为缺次项补0占位，减少长除或综合除法错位。占位零不是新的非零项，不改变次数；结果应用D×Q+R回乘，而非只相信列式排得整齐。","学习多项式为余式、因式和高次方程提供语言基础。任何约分都须先因式分解并保留分母非零条件；多项式恒等式与分式等价的定义域不能混用。"],"derive":["P(x)=aₙxⁿ+…+a₁x+a₀，aₙ≠0时次数n；零多项式另论。","非零P,Q有deg(PQ)=degP+degQ；deg(P+Q)可能下降。","F=DQ+R，D≠0，R=0或degR<degD；验证用回乘与合并系数。"],"examples":[{"q":"判断x²+√2x−1、x^(−1)+2、√x+1是否是关于x的实系数多项式。","given":"变量为x，√2是常数。","analysis":"检查变量指数而非系数是否有根号。","method":"逐项核非负整数指数。","principle":"多项式定义。","steps":["第一式指数2、1、0，系数均实数，是。","第二有−1次幂，第三有1/2次幂，不是。"],"ans":"只有第一式是。","verification":"把√2当常系数不会使x的指数变成分数。","pitfall":"凡有根号就判非多项式。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.1","related_sections":[]},{"q":"展开(x+2)(x²−2x+3)，求次数并回查首末项。","given":"普通实系数。","analysis":"乘法分配可能有中间抵消。","method":"逐项乘并合并。","principle":"分配律。","steps":["x乘得x³−2x²+3x，2乘得2x²−4x+6。","合为x³−x+6，次数3。"],"ans":"x³−x+6，3次。","verification":"首项x·x²=x³，常项2·3=6；x=1两边6。","pitfall":"x²项抵消后仍保留错误系数。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.1","related_sections":[]},{"q":"P=(a−1)x³+(a+1)x²+2x+3，随实数a次数怎样变化？","given":"系数含参数。","analysis":"最高项可能消失。","method":"按a−1是否0分类。","principle":"次数看最高非零系数。","steps":["a≠1时x³系数非0，次数3。","a=1时x³项0、x²系数2非0，次数2。"],"ans":"a≠1为3次；a=1为2次。","verification":"a=1式为2x²+2x+3，确实二次。","pitfall":"不分参数一律说三次。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.1","related_sections":[]}],"practice":[{"q":"0x⁵+3x²−1的次数？","given":"先去零系数项。","analysis":"写出的最高指数不一定非零。","method":"找最高非零项。","principle":"次数定义。","steps":["0x⁵为零项。","3x²非零且最高，次数2。"],"ans":"2。","verification":"x很大时主导为3x²。","pitfall":"看到x⁵就答5。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.1","related_sections":[]},{"q":"若(x+1)²=x²+ax+b为恒等式，求a,b。","given":"对所有x成立。","analysis":"系数对应。","method":"展开左边。","principle":"多项式恒等需对应系数同。","steps":["左边x²+2x+1。","a=2，b=1。"],"ans":"a=2、b=1。","verification":"x=0给b1，x=1给1+a+b=4。","pitfall":"只代一个点就定两个未知量。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.1","related_sections":[]},{"q":"三次与二次非零多项式的乘积次数？和的次数必为3吗？","given":"首项系数均非零，两个次数不同。","analysis":"乘积相加；不同次数和不能抵消最高三次。","method":"检查首项。","principle":"最高项来源唯一。","steps":["乘积3+2=5次。","和最高三次项无同次项抵消，仍3次。"],"ans":"乘积5次，和3次。","verification":"若两者都三次，和才可能降次，条件不同。","pitfall":"把所有和都说次数相加。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.1","related_sections":[]},{"q":"F=x³+1，D=x+1，给Q=x²−x、R=x+1，是否为合格商余表达？怎样完成？","given":"回乘可得F，但R次数等于D。","analysis":"还需余式次数限制。","method":"把R再除D。","principle":"余式应低于除式次数。","steps":["DQ+R=(x+1)(x²−x)+(x+1)=x³+1，但R仍一次。","补商1，最终Q=x²−x+1，R=0。"],"ans":"原不是最终商余；最终商x²−x+1、余0。","verification":"(x+1)(x²−x+1)=x³+1。","pitfall":"只看回乘正确就忽略余式次数。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.1","related_sections":[]}],"quiz":{"q":"两个二次多项式相加，次数一定二次吗？给反例并说明条件。","given":"二者各自最高项非零。","analysis":"首项可能抵消。","method":"构造相反二次系数。","principle":"加法次数可下降。","steps":["(x²+x)+(−x²+2)=x+2。","和一次；若所有系数抵消则为零多项式需另论。"],"ans":"不一定，取决最高项相加是否0。","verification":"两原式都二次而和一次，已否定必然。","pitfall":"把乘积次数规则套加法。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.1","related_sections":[]},"exam":["次数题先化简并审参数首项，零多项式单独说明","恒等题按系数比较，方程某点成立不能冒充恒等","除法题检查回乘和余式次数，两项缺一不可"],"quick":["定义与次数","系数比较","加减乘","除法商余","参数退化"],"exam_evidence":[],"content_sources":[{"source_id":"directory_math","url":"https://www.scribd.com/document/1058092101/数学-高一上册","page":"目录：Math_S1_Up_Content.indd 5（2025版；用户确认相符）","version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_math_3.1","url":"https://openstax.org/books/algebra-and-trigonometry-2e/pages/5-2-power-functions-and-polynomial-functions","page_or_section":"5-2-power-functions-and-polynomial-functions","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_math","url":"https://www.scribd.com/document/1058092101/数学-高一上册","page":"目录：Math_S1_Up_Content.indd 5（2025版；用户确认相符）","version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_math_3.1","url":"https://openstax.org/books/algebra-and-trigonometry-2e/pages/5-2-power-functions-and-polynomial-functions","page_or_section":"5-2-power-functions-and-polynomial-functions","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"次数题先化简并审参数首项，零多项式单独说明","method":"按a−1是否0分类。","principle":"次数看最高非零系数。","worked_example_index":2,"verification":"a=1式为2x²+2x+3，确实二次。","pitfall":"不分参数一律说三次。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“按指数与系数判断多项式及次数”的抽样复核：把√2当常系数不会使x的指数变成分数。；若出现“凡有根号就判非多项式。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“以恒等式完成运算和参数分类”的抽样复核：a=1式为2x²+2x+3，确实二次。；若出现“不分参数一律说三次。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"把乘积次数规则套加法。","correction":"不一定，取决最高项相加是否0。","verification":"两原式都二次而和一次，已否定必然。"}],"illustration_spec":{"title":"多项式的次数与商余","objects":["合法/非合法指数","含参数首项","降幂系数表","F=DQ+R关系"],"relations":["系数可含常根号","a=1时三次退为二次","余式次数低于除式"],"labels":["非负整数指数","最高非零项","a−1","商Q","余R"],"format":"SVG","priority":"P1","reuse":"无对应旧图；代数关系用文字层","english":"Distinguish a radical constant coefficient from a fractional variable exponent. Show how the leading coefficient a-1 vanishes at a=1, reducing degree, and illustrate F=DQ+R with the explicit degree restriction on R."}},"3.2":{"subject":"数学","subject_code":"math_shared","chapter_id":3,"section_id":"3.2","goals":["由除法恒等式推导余式定理","用适当代入求参数或一次余式"],"prerequisites":["多项式除法","联立方程"],"flow":["除法恒等式","一次除式根","常数余数","二次余式","参数验证"],"concept_relation":"除法恒等式；一次除式根；常数余数；二次余式；参数验证","deep":["对二次除式，余式一般一次或更低。若除式(x−a)(x−b)且a≠b，可写R=ux+v并在a、b代入，由两条独立方程确定u,v。只代一个根不足以确定两个未知系数。","如果除式有重复根，代入同一点两次不会产生两个独立条件，不能把重复的同一方程当成两条信息。本阶段可用实际除法或其他额外条件处理，不能凭空凑系数。","给多个余数条件求F中的参数时，每条件都从对应除式根生成，再联立。最后回代原F验证每个余数，避免移项或正负号误差；多项式系数中缺次项不影响代入法，但综合除法须补0。","余式定理不用于含分母奇点的任意表达式而不检查对象。若所给不是多项式，必须先按题意判断除法与定义域；把任何函数在a的值都称为多项式余数是不受支持的推广。"],"derive":["F=(x−a)Q+r，代a得r=F(a)。","对bx−c（b≠0），r=F(c/b)；商的尺度与b有关，但余数代入点由除式零点决定。","对(x−a)(x−b)、a≠b，令R=ux+v：ua+v=F(a)，ub+v=F(b)。"],"examples":[{"q":"F=x³−2x+5除以x−2的余数？","given":"F为多项式，除式一次。","analysis":"不用长除求商。","method":"r=F(2)。","principle":"余式定理由除法恒等式。","steps":["F(2)=8−4+5。","r=9。"],"ans":"9。","verification":"长除可得商x²+2x+2，回乘加9恢复F。","pitfall":"把余数误设0。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.2","related_sections":[]},{"q":"F=2x²+3x−1除以2x−1，余数是多少？","given":"除式根x=1/2。","analysis":"前系数不能忽略。","method":"r=F(1/2)。","principle":"一次除式为零时商项消失。","steps":["2×1/4+3×1/2−1=.5+1.5−1=1。","余数常数1。"],"ans":"1。","verification":"可写F=(2x−1)(x+2)+1，回乘正确。","pitfall":"代x=1或−1。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.2","related_sections":[]},{"q":"F=x³+2x²−x+4除以x²−1，求余式。","given":"除式根为±1且不同。","analysis":"余式至多一次，需两条件。","method":"设R=ux+v，代±1。","principle":"除法恒等式在除式根处使F=R。","steps":["F(1)=6，F(−1)=6。","u+v=6，−u+v=6，得u=0、v=6。"],"ans":"余式6。","verification":"F=(x²−1)(x+2)+6，展开得原式。","pitfall":"以为二次除式余式必为一次且u不能0。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.2","related_sections":[]}],"practice":[{"q":"F=x²+4x+1除以x+3的余数？","given":"除式根−3。","analysis":"正负号由x+3=0确定。","method":"r=F(−3)。","principle":"余式定理。","steps":["9−12+1=−2。","余数可为负。"],"ans":"−2。","verification":"F=(x+3)(x+1)−2。","pitfall":"代+3得到22。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.2","related_sections":[]},{"q":"F=x²+ax+2除以x−1余4，求a。","given":"r=4而非整除。","analysis":"生成参数方程。","method":"F(1)=4。","principle":"余式定理。","steps":["1+a+2=4。","a=1。"],"ans":"a=1。","verification":"F(1)=1+1+2=4。","pitfall":"把余数4忘掉写F1=0。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.2","related_sections":[]},{"q":"多项式除以(x−2)²，能代x=2两次唯一求一次余式ux+v吗？","given":"只有一个点的函数值。","analysis":"同一条件重复不独立。","method":"统计未知与独立方程。","principle":"代入只给2u+v=F(2)。","steps":["两个未知只有一条独立方程。","需额外信息或实际除法，重复代2不新增约束。"],"ans":"不能。","verification":"不同u配相应v可满足同一值。","pitfall":"把重复根当两个不同代入点。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.2","related_sections":[]},{"q":"F=x³除以(x−1)(x−2)，余式？","given":"根1、2不同。","analysis":"设一次余式并联立。","method":"R=ux+v。","principle":"F(1)=R1，F(2)=R2。","steps":["u+v=1，2u+v=8。","u=7，v=−6，R=7x−6。"],"ans":"7x−6。","verification":"(x²−3x+2)(x+3)+(7x−6)=x³。","pitfall":"只给F1=1当完整余式。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.2","related_sections":[]}],"quiz":{"q":"若F(3)=5，能说x−3是F的因式吗？","given":"余数已知非零。","analysis":"余式与整除判据不同。","method":"按余式定理解释。","principle":"因式需余数0。","steps":["除以x−3的余数是5。","因此不是整除，不是因式。"],"ans":"不能，且x−3不是因式。","verification":"F=(x−3)Q+5在3处仍为5非0。","pitfall":"看见代入点就误认根。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.2","related_sections":[]},"exam":["余式题先把除式设0找代入点，不记孤立符号口诀","二次除式先写一次余式，两个不同根给独立方程","有参数题把给定余数写右边，最后逐条件回代"],"quick":["除法恒等式","一次除式根","常数余数","二次余式","参数验证"],"exam_evidence":[],"content_sources":[{"source_id":"directory_math","url":"https://www.scribd.com/document/1058092101/数学-高一上册","page":"目录：Math_S1_Up_Content.indd 5（2025版；用户确认相符）","version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_math_3.2","url":"https://openstax.org/books/algebra-and-trigonometry-2e/pages/5-4-dividing-polynomials","page_or_section":"5-4-dividing-polynomials","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_math","url":"https://www.scribd.com/document/1058092101/数学-高一上册","page":"目录：Math_S1_Up_Content.indd 5（2025版；用户确认相符）","version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_math_3.2","url":"https://openstax.org/books/algebra-and-trigonometry-2e/pages/5-4-dividing-polynomials","page_or_section":"5-4-dividing-polynomials","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"余式题先把除式设0找代入点，不记孤立符号口诀","method":"设R=ux+v，代±1。","principle":"除法恒等式在除式根处使F=R。","worked_example_index":2,"verification":"F=(x²−1)(x+2)+6，展开得原式。","pitfall":"以为二次除式余式必为一次且u不能0。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“由除法恒等式推导余式定理”的抽样复核：长除可得商x²+2x+2，回乘加9恢复F。；若出现“把余数误设0。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“用适当代入求参数或一次余式”的抽样复核：F=(x²−1)(x+2)+6，展开得原式。；若出现“以为二次除式余式必为一次且u不能0。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"看见代入点就误认根。","correction":"不能，且x−3不是因式。","verification":"F=(x−3)Q+5在3处仍为5非0。"}],"illustration_spec":{"title":"余式定理的消元关系","objects":["F=(x−a)Q+r","代入x=a","2x−1根1/2","二次余式ux+v"],"relations":["一次除式余式常数","二次两不同根可定u,v","重复根只给一个值条件"],"labels":["r=F(a)","F(c/b)","a≠b","独立条件"],"format":"SVG","priority":"P1","reuse":"无合格对应图；公式流程需准确","english":"Derive the remainder theorem from F=(x-a)Q+r by substituting x=a. For divisor 2x-1 use a=1/2. For two distinct linear factors, show how R=ux+v is determined by two independent values; do not count a repeated root twice as independent data."}},"3.3":{"subject":"数学","subject_code":"math_shared","chapter_id":3,"section_id":"3.3","goals":["以余式定理证明根与一次因式的等价","求参数并核因式重数"],"prerequisites":["余式定理","乘法恒等式"],"flow":["余数为零","根与因式","求商","参数联立","重数与次数"],"concept_relation":"余数为零；根与因式；求商；参数联立；重数与次数","deep":["F(a)=0只说明至少含一次x−a，不能仅据一次代入判断重数。将因式除去后若商在a处仍为零，可以继续除；重数会影响图象和根的计数，但本章可用反复因式法认识，不需偷用尚未建立的微分公式。","给定两个不同根可生成两个独立参数条件，但要留意首项是否因参数而退化，以及给定条件是否重复。参数解后还应验证多项式是否确有相应因式，不以代数移项中的一个结果直接结束。","对于非零n次多项式，互不相同的根不超过n个，可用不断抽取不同一次因式说明；重根按重数计与不同根数是不同说法。零多项式在任何x都为零，不能套这个结论而称它有某个有限次数。","因式定理用于多项式，若表达式有分母或根式，应先检查定义域与是否满足多项式条件。把分式分子为零当整个分式为零还需要分母非零，这个限制不能因因式分解而消失。"],"derive":["F(a)=0 ⇔ F=(x−a)Q，证明来自F=(x−a)Q+r且r=F(a)。","若Q(a)=0，还可再抽取x−a；重复次数决定该根重数。","非零n次多项式最多n个不同实根；是否存在全部n个实根不能由次数单独保证。"],"examples":[{"q":"F=x³−4x，证明x−2为因式，并求完整实因式分解。","given":"F为实系数多项式。","analysis":"先零值证明，再求商/共同因子。","method":"计算F2并分解。","principle":"因式定理与平方差。","steps":["F(2)=8−8=0，所以x−2是因式。","F=x(x²−4)=x(x−2)(x+2)。"],"ans":"x(x−2)(x+2)。","verification":"乘回x³−4x，根0、±2均使F为0。","pitfall":"只写F2=0就声称已给完整分解。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.3","related_sections":[]},{"q":"F=x³+ax²+bx−2，x−1与x+2均为因式，求a,b。","given":"两个不同一次因式。","analysis":"代入点1、−2。","method":"F1=0、F(−2)=0联立。","principle":"因式定理。","steps":["1+a+b−2=0，a+b=1。","−8+4a−2b−2=0，2a−b=5。","解a=2、b=−1。"],"ans":"a=2、b=−1。","verification":"F=(x+2)(x−1)(x+1)，常项−2且x²系数2。","pitfall":"x+2代+2。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.3","related_sections":[]},{"q":"F=(x−1)²(x+3)，只算F1=0能证明1是二重根吗？如何验证？","given":"已给分解但要求说明判据。","analysis":"一次取零只保证至少一重。","method":"除一次后再检查商。","principle":"重数是同一因式出现次数。","steps":["除x−1得Q=(x−1)(x+3)，Q1=0可再除。","再得x+3，在1处4非0，故恰二重。"],"ans":"单次取零不足；反复除得恰二重。","verification":"展开(x²−2x+1)(x+3)后仍可回乘验证。","pitfall":"由F1=0直接猜任何重数。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.3","related_sections":[]}],"practice":[{"q":"F(−3)=0，对应一次因式是什么？","given":"根为−3。","analysis":"因式x−a。","method":"代a=−3。","principle":"因式定理。","steps":["x−(−3)=x+3。","故F可被x+3整除。"],"ans":"x+3。","verification":"该因式在−3处为0。","pitfall":"写x−3。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.3","related_sections":[]},{"q":"F=x²+1在实数范围有一次实因式吗？","given":"实系数一次因式。","analysis":"实根存在与一次实因式等价。","method":"看x²+1是否可0。","principle":"实数平方非负。","steps":["x²+1≥1>0。","没有实根，因此无一次实因式。"],"ans":"没有。","verification":"若改复数范围结论会不同，但本题实数。","pitfall":"认为二次必有两个实根。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.3","related_sections":[]},{"q":"已知x−2为三次F的因式，能推出除去后商一定一次吗？","given":"F确为非零三次。","analysis":"次数相减。","method":"degQ=3−1。","principle":"非零乘积次数相加。","steps":["F=(x−2)Q。","Q应为二次，不是一次。"],"ans":"不能，商二次。","verification":"一次乘二次才三次。","pitfall":"把因式个数与次数混淆。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.3","related_sections":[]},{"q":"F=x³−3x²+3x−1，求1的重数及不同实根数。","given":"非零三次。","analysis":"利用完全立方。","method":"F=(x−1)³。","principle":"重复因式决定重数。","steps":["展开(x−1)³正好原式。","只有x=1使乘积为0，重数3，不同实根1个。"],"ans":"三重根1；不同实根1个。","verification":"次数3按重数吻合，而非三种不同值。","pitfall":"三次就列三个不同根。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.3","related_sections":[]}],"quiz":{"q":"一个非零二次多项式在三个不同实数处都为0，可能吗？若系数全0又怎样？","given":"明确非零或零两种。","analysis":"不同根数受次数限制。","method":"用因式定理逐根抽因式。","principle":"三个不同根意味着至少三个一次因式。","steps":["非零二次无法含三次因子，故不可能。","若全系数0是零多项式，不是非零二次，每个实数都满足。"],"ans":"非零二次不可能；零多项式例外。","verification":"避免把“0x²+0x+0”称二次。","pitfall":"忘非零条件和退化情况。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.3","related_sections":[]},"exam":["因式题写根—因式对应，正负号由x−a来核","参数题每个不同根给一条件，算后回乘验证","重根题反复除因式，区分重数与不同根数"],"quick":["余数为零","根与因式","求商","参数联立","重数与次数"],"exam_evidence":[],"content_sources":[{"source_id":"directory_math","url":"https://www.scribd.com/document/1058092101/数学-高一上册","page":"目录：Math_S1_Up_Content.indd 5（2025版；用户确认相符）","version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_math_3.3","url":"https://openstax.org/books/algebra-and-trigonometry-2e/pages/5-5-zeros-of-polynomial-functions","page_or_section":"5-5-zeros-of-polynomial-functions","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_math","url":"https://www.scribd.com/document/1058092101/数学-高一上册","page":"目录：Math_S1_Up_Content.indd 5（2025版；用户确认相符）","version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_math_3.3","url":"https://openstax.org/books/algebra-and-trigonometry-2e/pages/5-5-zeros-of-polynomial-functions","page_or_section":"5-5-zeros-of-polynomial-functions","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"因式题写根—因式对应，正负号由x−a来核","method":"除一次后再检查商。","principle":"重数是同一因式出现次数。","worked_example_index":2,"verification":"展开(x²−2x+1)(x+3)后仍可回乘验证。","pitfall":"由F1=0直接猜任何重数。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“以余式定理证明根与一次因式的等价”的抽样复核：乘回x³−4x，根0、±2均使F为0。；若出现“只写F2=0就声称已给完整分解。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“求参数并核因式重数”的抽样复核：展开(x²−2x+1)(x+3)后仍可回乘验证。；若出现“由F1=0直接猜任何重数。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"忘非零条件和退化情况。","correction":"非零二次不可能；零多项式例外。","verification":"避免把“0x²+0x+0”称二次。"}],"illustration_spec":{"title":"根、一次因式与重数","objects":["F(a)=0到x−a因式","根−3与x+3","重复因式链","次数计数"],"relations":["两个方向等价","重数需反复除","非零n次不同根不超过n"],"labels":["F(a)=0","x−a","重数","不同实根","非零多项式"],"format":"SVG","priority":"P1","reuse":"无对应旧图；关系图与可选函数图应准确","english":"Connect a numerical root a with the linear factor x-a in both directions, including a=-3 and factor x+3. Show repeated division for a double root and distinguish multiplicity from the number of distinct real roots of a nonzero polynomial."}},"3.4":{"subject":"数学","subject_code":"math_shared","chapter_id":3,"section_id":"3.4","goals":["依结构选择提因式、分组或求根方法","在指定数域内完成分解并回乘"],"prerequisites":["多项式运算","因式定理"],"flow":["公因式","恒等式","分组","求根降次","数域与回乘"],"concept_relation":"公因式；恒等式；分组；求根降次；数域与回乘","deep":["若直接看不出结构，可用因式定理尝试合适根，再除去对应一次因式。对于整数系数，若既约有理根p/q存在，可用常数项与首项系数的整除关系缩小候选；这是候选筛选，不保证一定有有理根。","偶次幂结构可用y=x²代换成较低次多项式，再把y换回。因式分解只做代数等价时仍要回原变量；解方程时则还要注意y≥0的实数限制，两类任务不可混淆。","分解到什么程度与数域有关。x²−2在有理数系数内不能拆成两个一次因式，在实数内可写(x−√2)(x+√2)；x²+1在实数内不可同样拆成实一次式。题目未指明时应清楚说明所用范围。","完成后逐项回乘核首项、常项和中间项，并检查是否漏了公因子。抽出负号时每项符号都要反转；只查若干代入值可辅助发现错误，但展开恒等验证更完整。"],"derive":["a²−b²=(a−b)(a+b)；a³−b³=(a−b)(a²+ab+b²)。","整数系数多项式若有既约有理根p/q，则p整除常数项、q整除首项系数（首常项非零等条件下）。","分解流程：公因式 → 恒等结构/分组/代换 → 因式定理找根 → 指定数域继续 → 回乘。"],"examples":[{"q":"分解3x³−12x。","given":"实系数，多项式。","analysis":"先公因式再平方差。","method":"提3x。","principle":"分配律和a²−b²。","steps":["3x³−12x=3x(x²−4)。","再得3x(x−2)(x+2)。"],"ans":"3x(x−2)(x+2)。","verification":"回乘3x(x²−4)=3x³−12x。","pitfall":"只提3x后不继续，或把x²−4写(x−2)²。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.4","related_sections":[]},{"q":"分解x³−3x²−4x+12。","given":"四项可分组。","analysis":"前两与后两共享x−3。","method":"分为x²(x−3)−4(x−3)。","principle":"分配律反向。","steps":["提共同(x−3)得(x−3)(x²−4)。","平方差得(x−3)(x−2)(x+2)。"],"ans":"(x−3)(x−2)(x+2)。","verification":"展开x³−3x²−4x+12。","pitfall":"后组提−4时把括号写x+3。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.4","related_sections":[]},{"q":"在实数内分解x⁴−5x²+4，并说明代换步骤。","given":"只含偶次幂。","analysis":"可把x²视为一变量。","method":"y=x²。","principle":"代换后保持恒等。","steps":["y²−5y+4=(y−1)(y−4)。","换回(x²−1)(x²−4)。","实数下进一步为(x−1)(x+1)(x−2)(x+2)。"],"ans":"四个一次因式的乘积。","verification":"(x²−1)(x²−4)=x⁴−5x²+4。","pitfall":"解出y=1、4就把它们当x值。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.4","related_sections":[]}],"practice":[{"q":"x²+6x+9怎样分解？","given":"完整二次式。","analysis":"识别完全平方。","method":"比较x²+2·3x+3²。","principle":"(a+b)²。","steps":["中项6x吻合。","得(x+3)²。"],"ans":"(x+3)²。","verification":"展开还原，常项9。","pitfall":"把+9只写(x+9)²。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.4","related_sections":[]},{"q":"x²−2在有理数内与实数内的分解有何不同？","given":"指定数域两种。","analysis":"是否允许√2作系数。","method":"找根并核系数范围。","principle":"实根±√2不是有理数。","steps":["有理数系数内不可拆一次。","实数内可写(x−√2)(x+√2)。"],"ans":"数域不同导致可分解程度不同。","verification":"乘回x²−2。","pitfall":"无条件说不能分或必能有理分。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.4","related_sections":[]},{"q":"2x³−3x²−8x+12以分组分解。","given":"前后可提共同2x−3。","analysis":"识别配对。","method":"x²(2x−3)−4(2x−3)。","principle":"共同因式与平方差。","steps":["得(2x−3)(x²−4)。","再得(2x−3)(x−2)(x+2)。"],"ans":"(2x−3)(x−2)(x+2)。","verification":"首项2x³、常项(−3)(−2)(2)=12，中间项吻合。","pitfall":"以非首一因式为由漏系数2。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.4","related_sections":[]},{"q":"分解x³+1，并用x=1核查错误答案(x+1)³。","given":"立方和。","analysis":"立方和不同于和的立方。","method":"用a³+b³。","principle":"a³+b³=(a+b)(a²−ab+b²)。","steps":["x³+1=(x+1)(x²−x+1)。","x=1原2，错误答案8，不能相等。"],"ans":"(x+1)(x²−x+1)。","verification":"完整展开中间项抵消。","pitfall":"见立方就对和整体立方。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.4","related_sections":[]}],"quiz":{"q":"因式分解得到(2x−3)(x−2)(x+2)，只检查首项和常项相同就足够证明吗？","given":"中间项尚未核对。","analysis":"两个指标不足唯一确定三次多项式。","method":"展开全部系数。","principle":"恒等式需对应各项相同。","steps":["首常项可快速筛错。","仍需核x²、x等中间系数或其他充分证明。"],"ans":"不足，应完整回乘或用充分代数证明。","verification":"可给相同首常项而中间系数任意不同的反例。","pitfall":"把快速检查当充分恒等证明。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.4","related_sections":[]},"exam":["分解题先提公因式、识别结构，不盲猜根","偶次式代换后换回x，方程求根另核变量限制","写清数域，最终回乘所有系数，首常项只作快查"],"quick":["公因式","恒等式","分组","求根降次","数域与回乘"],"exam_evidence":[],"content_sources":[{"source_id":"directory_math","url":"https://www.scribd.com/document/1058092101/数学-高一上册","page":"目录：Math_S1_Up_Content.indd 5（2025版；用户确认相符）","version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_math_3.4","url":"https://openstax.org/books/algebra-and-trigonometry-2e/pages/1-5-factoring-polynomials","page_or_section":"1-5-factoring-polynomials","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_math","url":"https://www.scribd.com/document/1058092101/数学-高一上册","page":"目录：Math_S1_Up_Content.indd 5（2025版；用户确认相符）","version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_math_3.4","url":"https://openstax.org/books/algebra-and-trigonometry-2e/pages/1-5-factoring-polynomials","page_or_section":"1-5-factoring-polynomials","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"分解题先提公因式、识别结构，不盲猜根","method":"y=x²。","principle":"代换后保持恒等。","worked_example_index":2,"verification":"(x²−1)(x²−4)=x⁴−5x²+4。","pitfall":"解出y=1、4就把它们当x值。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“依结构选择提因式、分组或求根方法”的抽样复核：回乘3x(x²−4)=3x³−12x。；若出现“只提3x后不继续，或把x²−4写(x−2)²。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“在指定数域内完成分解并回乘”的抽样复核：(x²−1)(x²−4)=x⁴−5x²+4。；若出现“解出y=1、4就把它们当x值。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"把快速检查当充分恒等证明。","correction":"不足，应完整回乘或用充分代数证明。","verification":"可给相同首常项而中间系数任意不同的反例。"}],"illustration_spec":{"title":"因式分解的方法选择","objects":["共同因式示例","四项分组","y=x²代换","数域分支","回乘检查"],"relations":["x⁴−5x²+4分为四实一次因式","平方和不误用平方差","候选根不等于必存在根"],"labels":["公因式","分组","代换后换回","有理数/实数","完整回乘"],"format":"SVG","priority":"P1","reuse":"无对应图；代数结构关系可用页面图与SVG","english":"Create a method-selection diagram for common factors, identities, grouping, substitution and root-based division. Work x^4-5x^2+4 through y=x^2 to four real linear factors, distinguish rational and real factorization, and require full coefficient verification."}},"3.5":{"subject":"数学","subject_code":"math_shared","chapter_id":3,"section_id":"3.5","goals":["用因式分解与代换求全部实根","处理重根、参数退化和非等价除法"],"prerequisites":["因式分解","二次方程与定义域"],"flow":["移项归零","找因式降次","零乘积","代换范围","参数与回代"],"concept_relation":"移项归零；找因式降次；零乘积；代换范围；参数与回代","deep":["用y=x²代换时，实数解要求y≥0。二次方程给负的y候选，不能当作实数x的平方；正y给x=±√y，零y只给x=0。换回步骤和双符号是常见漏解处。","找一个有理根后把对应一次因式除去，继续解二次商；判别式负时该商没有实根，并不否定已经找到的实根。若题目要求复根，则需相应复数知识，本节不把超出实数的结果强填为实根。","参数题须关注最高系数、因式退化和根相等的临界值，按参数范围列解集。方程次数变化与根的重合是不同事情，不能把每个参数区间的解数机械按最高写出的幂确定。","最终把每个候选代回原方程并回顾变形是否等价。原式若含分母、根式等，化成多项式后的根仍需原域筛选；回代只验证已有候选不自动证明无漏根，无漏依据来自等价分解与完整分类。"],"derive":["F=AB=0 ⇔ A=0或B=0（实数代数）；重复因式保留重数但解集去重。","y=x²时y≥0，y>0回得±√y，y=0回得0，y<0无实x。","含变量因子除法：先分该因子为0与非0，或避免除法而用零乘积。"],"examples":[{"q":"解实数方程x³=x，说明直接除x会漏什么。","given":"原式为多项式方程。","analysis":"x可能为0。","method":"移项分解。","principle":"零乘积原理。","steps":["x³−x=x(x²−1)=x(x−1)(x+1)=0。","逐因式得x=0、1、−1。"],"ans":"{−1,0,1}。","verification":"三值代原式均成立；直接除x会漏0。","pitfall":"未分类就除含未知因子。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.5","related_sections":[]},{"q":"解x⁴−3x²−4=0的全部实根。","given":"只含偶次幂。","analysis":"先解y=x²且筛负y。","method":"y²−3y−4=0。","principle":"代换与非负平方。","steps":["(y−4)(y+1)=0，y=4或−1。","y=−1无实x；y=4给x=±2。"],"ans":"x=−2或2。","verification":"16−12−4=0，负y候选不可回实数。","pitfall":"把x答成4与−1，或漏−2。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.5","related_sections":[]},{"q":"讨论实数参数a下x³−ax=0的不同实根。","given":"关于x，首项恒1。","analysis":"分解后根随a符号变化。","method":"x(x²−a)=0分类。","principle":"实平方非负及根重合。","steps":["a>0时x=0、±√a，共3个不同根。","a=0时x³=0，仅0（重数3）。","a<0时x²=a无实解，仅0。"],"ans":"按a正、零、负分别为3、1、1个不同根。","verification":"每段均由完整因式分支，a=0时三表达式合成一个值。","pitfall":"a<0仍写±√a为实数，或a=0重复算3个不同根。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.5","related_sections":[]}],"practice":[{"q":"解(x−2)²(x+1)=0，写不同解和重数。","given":"实数范围。","analysis":"重复因式不增加不同值。","method":"逐因式。","principle":"零乘积。","steps":["x=2或−1。","2重数2，−1重数1。"],"ans":"解集{−1,2}。","verification":"重数总3与次数3吻合。","pitfall":"把2重复列成两个不同解。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.5","related_sections":[]},{"q":"解x³+1=0的实根。","given":"实数范围。","analysis":"立方和分解后判二次商。","method":"(x+1)(x²−x+1)=0。","principle":"因式与判别式。","steps":["一次得x=−1。","二次判别式1−4=−3<0，无实根。"],"ans":"仅x=−1。","verification":"(−1)³+1=0；二次式=(x−1/2)²+3/4>0。","pitfall":"认为三次必须给三个实根。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.5","related_sections":[]},{"q":"解x⁴−5x²+4=0。","given":"实数范围。","analysis":"分解或代换。","method":"(x²−1)(x²−4)=0。","principle":"零乘积及平方方程。","steps":["x²=1或4。","x=±1、±2。"],"ans":"{−2,−1,1,2}。","verification":"各平方1或4，均使原式0。","pitfall":"只列正平方根。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.5","related_sections":[]},{"q":"解(x²−1)/(x−1)=0并保留原域，和解x²−1=0有什么区别？","given":"原分母x≠1。","analysis":"分子为0还需分母非0。","method":"先分子根±1再筛。","principle":"分式零值条件。","steps":["分子根1、−1。","x=1原无定义排除，x=−1分母−2可取。"],"ans":"原分式解仅−1；多项式解±1。","verification":"−1代入分子0分母非0。","pitfall":"约分后或解分子时忘原排除点。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.5","related_sections":[]}],"quiz":{"q":"给多项式找到一个根并回代成功，是否已证明解集完整？","given":"次数可能大于1。","analysis":"验证存在与排除其他根是不同任务。","method":"继续降次并逐因式解。","principle":"完整分解或其他充分方法才控制无漏。","steps":["已找到根说明一个解成立。","除相应因式后继续分析全部商根，并审数域及条件。"],"ans":"没有，还需无漏解的推理。","verification":"x³−x中找到1仍有0、−1。","pitfall":"把一例成功当全部。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":3,"primary_section":"3.5","related_sections":[]},"exam":["高次题先移零、分解、逐因式求解，变形链说明无漏","代换题把新变量范围写在旁边，换回保留双符号","参数题按平方可行性、退化与根重合分类，最后解集去重"],"quick":["移项归零","找因式降次","零乘积","代换范围","参数与回代"],"exam_evidence":[],"content_sources":[{"source_id":"directory_math","url":"https://www.scribd.com/document/1058092101/数学-高一上册","page":"目录：Math_S1_Up_Content.indd 5（2025版；用户确认相符）","version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_math_3.5","url":"https://openstax.org/books/algebra-and-trigonometry-2e/pages/5-5-zeros-of-polynomial-functions","page_or_section":"5-5-zeros-of-polynomial-functions","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_math","url":"https://www.scribd.com/document/1058092101/数学-高一上册","page":"目录：Math_S1_Up_Content.indd 5（2025版；用户确认相符）","version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_math_3.5","url":"https://openstax.org/books/algebra-and-trigonometry-2e/pages/5-5-zeros-of-polynomial-functions","page_or_section":"5-5-zeros-of-polynomial-functions","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"高次题先移零、分解、逐因式求解，变形链说明无漏","method":"x(x²−a)=0分类。","principle":"实平方非负及根重合。","worked_example_index":2,"verification":"每段均由完整因式分支，a=0时三表达式合成一个值。","pitfall":"a<0仍写±√a为实数，或a=0重复算3个不同根。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“用因式分解与代换求全部实根”的抽样复核：三值代原式均成立；直接除x会漏0。；若出现“未分类就除含未知因子。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“处理重根、参数退化和非等价除法”的抽样复核：每段均由完整因式分支，a=0时三表达式合成一个值。；若出现“a<0仍写±√a为实数，或a=0重复算3个不同根。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"把一例成功当全部。","correction":"没有，还需无漏解的推理。","verification":"x³−x中找到1仍有0、−1。"}],"illustration_spec":{"title":"高次方程的完整解集","objects":["x³=x因式树","x²代换","正零负参数分支","实根集合与重数"],"relations":["保留x=0分支","负y不回实根","正y给±根","a=0时根合并"],"labels":["全部实根","y≥0","±√y","原域","不同根/重数"],"format":"SVG","priority":"P0","reuse":"无对应旧图；函数曲线如新增须确定性绘制","english":"Show a complete solution tree for x^3=x retaining x=0, and for an even-power equation using y=x^2 with y>=0 and both square-root signs. Include parameter branches for x(x^2-a)=0, distinguishing root multiplicity from distinct real solutions."}}},"数学4":{"4.1":{"subject":"数学","subject_code":"math_shared","chapter_id":4,"section_id":"4.1","goals":["以实数范围定义根式与定义域","解释主平方根和绝对值的关系"],"prerequisites":["实数与平方","绝对值与不等式"],"flow":["根的次数","主根非负","定义域","绝对值","等价条件"],"concept_relation":"根的次数；主根非负；定义域；绝对值；等价条件","deep":["由非负主根定义，√(x²)=|x|，而不是对所有实数x都等于x。若x≥0可写x，若x<0应写−x。绝对值是在保证结果非负，不是多余装饰符号；这也是许多根式化简漏符号的来源。","确定定义域是化简与方程的前提。等式变形可能把原限制隐藏，例如√(x²)在所有实数有定义，而把它错写x会在负区改变值；约去分母因子也不能把原来分母为零的点重新加回。","含多个根式或分母时，把每一条件分别列出再取交集。对于√((x−1)/(x+2))，需要分式非负且x≠−2，不能把分子分母都强制非负，因为同为负也能使商非负。","图象或数值验证可发现错误，但不能代替全域证明。试x=−2能否定√(x²)=x，却不能用几个正数样本证明等式总成立；证明应回到非负主根和分段定义。"],"derive":["实数范围：偶次根要求被开方数≥0，奇次根可为任意实数；分母另需非零。","√(x²)=|x|={x（x≥0），−x（x<0）}。","若√g(x)在分母，需g(x)>0；若分母还含其他项，需直接检查整个分母，而非一律令每项正。"],"examples":[{"q":"求√49，并解方程x²=49，二者答案为什么不同形式？","given":"实数范围，√为主平方根。","analysis":"一个是定义的单值函数，一个是方程全部解。","method":"用非负根和平方对称性。","principle":"√a≥0，但x²相同可来自±x。","steps":["√49=7。","方程有x=7或x=−7，两者平方均49。"],"ans":"主根7；方程解±7。","verification":"−7不是√49的值，却是方程的解。","pitfall":"把根号值写±7。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":4,"primary_section":"4.1","related_sections":[]},{"q":"化简√((x−3)²)，并求x=1时的值。","given":"x任意实数。","analysis":"主根需非负。","method":"先写绝对值再分段或代入。","principle":"√y²=|y|。","steps":["原式=|x−3|。","x=1得|−2|=2；分段为x≥3时x−3，x<3时3−x。"],"ans":"|x−3|，x=1时2。","verification":"直接√((1−3)²)=√4=2。","pitfall":"去根号后直接写x−3导致−2。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":4,"primary_section":"4.1","related_sections":[]},{"q":"求√((x−1)/(x+2))的实数定义域。","given":"分母x+2不能为0。","analysis":"商非负有两个符号区间。","method":"列临界点−2、1并作号表。","principle":"偶次根要求商≥0，分母非零。","steps":["x<−2时分子分母均负，商正。","−2<x<1时商负；x≥1时商非负。","−2排除，1可取。"],"ans":"(−∞,−2)∪[1,+∞)。","verification":"x=−3时商4、根为2；x=0时商−1/2不可；x=1时根0可。","pitfall":"只取分子分母各自非负而漏x<−2。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":4,"primary_section":"4.1","related_sections":[]}],"practice":[{"q":"√0、∛(−27)、√(−4)在实数内各怎样？","given":"偶根与奇根规则。","analysis":"先判定义再求值。","method":"按根的次数。","principle":"偶次平方非负，奇次立方可负。","steps":["√0=0，∛(−27)=−3。","√(−4)在实数内无定义。"],"ans":"0、−3、无实数定义。","verification":"0²=0、(−3)³=−27。","pitfall":"把所有负被开方数都视为无定义。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":4,"primary_section":"4.1","related_sections":[]},{"q":"1/√(2x−6)定义域？","given":"根式位于整个分母。","analysis":"被开方为零仍使分母零。","method":"2x−6>0。","principle":"实根与非零分母同时。","steps":["2x>6。","x>3，3不取。"],"ans":"(3,+∞)。","verification":"x=3给零分母，x=4可。","pitfall":"只写x≥3。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":4,"primary_section":"4.1","related_sections":[]},{"q":"x<0时√(9x²)怎样化简？","given":"已知x负。","analysis":"根式提出系数但保留绝对值。","method":"3|x|再用符号。","principle":"主根非负。","steps":["√(9x²)=3|x|。","x<0时|x|=−x，故−3x。"],"ans":"−3x。","verification":"x=−2时结果6，与√36相同。","pitfall":"写3x为负。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":4,"primary_section":"4.1","related_sections":[]},{"q":"求√(x+1)+1/(x−2)定义域，并判断化简后能否补入x=2。","given":"两个限制同时存在。","analysis":"根式与分母分别列。","method":"x+1≥0且x−2≠0。","principle":"定义域为条件交集。","steps":["x≥−1。","排除2，得[−1,2)∪(2,+∞)；任何等价化简仍保留原排除。"],"ans":"[−1,2)∪(2,+∞)，不能补2。","verification":"−1可取根号0，2不可因分母0。","pitfall":"只查根号忘分母。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":4,"primary_section":"4.1","related_sections":[]}],"quiz":{"q":"有人用x=1、2、3证明√(x²)=x对所有实数成立，怎样完整纠正？","given":"只验证正数。","analysis":"样本不足且负数反例。","method":"反例后给一般恒等式。","principle":"主平方根非负。","steps":["x=−1时左1右−1，原命题假。","正确为√x²=|x|，用x符号分段说明。"],"ans":"应改为|x|并分正负。","verification":"绝对值总非负且平方为x²，满足主根定义。","pitfall":"用有限正样本代替全域证明。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":4,"primary_section":"4.1","related_sections":[]},"exam":["根式题先写实数范围和定义域，偶根与奇根分开","去平方根必须保留非负性，用绝对值或符号条件","分式根号题作号表取交集，分母零点明确排除"],"quick":["根的次数","主根非负","定义域","绝对值","等价条件"],"exam_evidence":[],"content_sources":[{"source_id":"directory_math","url":"https://www.scribd.com/document/1058092101/数学-高一上册","page":"目录：Math_S1_Up_Content.indd 6（2025版；用户确认相符）","version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_math_4.1","url":"https://openstax.org/books/algebra-and-trigonometry-2e/pages/1-3-radicals-and-rational-exponents","page_or_section":"1-3-radicals-and-rational-exponents","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_math","url":"https://www.scribd.com/document/1058092101/数学-高一上册","page":"目录：Math_S1_Up_Content.indd 6（2025版；用户确认相符）","version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_math_4.1","url":"https://openstax.org/books/algebra-and-trigonometry-2e/pages/1-3-radicals-and-rational-exponents","page_or_section":"1-3-radicals-and-rational-exponents","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"根式题先写实数范围和定义域，偶根与奇根分开","method":"列临界点−2、1并作号表。","principle":"偶次根要求商≥0，分母非零。","worked_example_index":2,"verification":"x=−3时商4、根为2；x=0时商−1/2不可；x=1时根0可。","pitfall":"只取分子分母各自非负而漏x<−2。"},"diagnostics":[{"goal_index":0,"question_ref":"e2","review_module":4,"feedback":"目标“以实数范围定义根式与定义域”的抽样复核：x=−3时商4、根为2；x=0时商−1/2不可；x=1时根0可。；若出现“只取分子分母各自非负而漏x<−2。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e1","review_module":5,"feedback":"目标“解释主平方根和绝对值的关系”的抽样复核：直接√((1−3)²)=√4=2。；若出现“去根号后直接写x−3导致−2。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"用有限正样本代替全域证明。","correction":"应改为|x|并分正负。","verification":"绝对值总非负且平方为x²，满足主根定义。"}],"illustration_spec":{"title":"主平方根与定义域","objects":["y=√(x²)=|x|图","x²=a的两根","分式号表","排除点"],"relations":["根号输出非负","偶次根需非负","分母不能零","号表保留x<−2"],"labels":["√x²=|x|","x=±7为方程解","−2","1","定义域"],"format":"SVG","priority":"P0","reuse":"数学暂无合格对应图；必须确定性绘制","english":"Draw the exact V-shaped graph y=sqrt(x^2)=abs(x), distinguish the principal root sqrt(49)=7 from equation solutions ±7, and show a sign chart for (x-1)/(x+2) with -2 excluded and 1 included."}},"4.2":{"subject":"数学","subject_code":"math_shared","chapter_id":4,"section_id":"4.2","goals":["用根式定义有理指数并注明底数条件","正确处理负指数与指数运算的边界"],"prerequisites":["根式定义","整数指数"],"flow":["有理指数定义","正底数","负指数倒数","指数律","负底数边界"],"concept_relation":"有理指数定义；正底数；负指数倒数；指数律；负底数边界","deep":["正底数下可使用a^r a^s=a^(r+s)、a^r/a^s=a^(r−s)、(a^r)^s=a^(rs)。这些规则的实数扩展对负底数需要额外审查，不能把含偶根的运算当所有形式都等价。","负底数的某些有理幂可以用约分后的奇次根定义，例如(−8)^(1/3)=−2；若指数分母偶数则通常无实数值。写同一有理数为不同未约分形式后套用偶根，可能改变定义步骤，故必须先约分并明确约定，或将题目限定正底数。","解指数与根式混合题先确认定义域，再选择指数法或根式法。消去负指数可使分母限制更清楚，但形式上的约分不允许把原来无定义的底数0放回。","验算应选满足条件的值并回到定义，不能让计算器的复数结果或程序使用的幂函数约定悄悄替换实数问题。对负底数有疑问时，写成明确的奇次根往往更稳妥。"],"derive":["a>0时，a^(m/n)=ⁿ√(a^m)，指数先视为约分的有理数，n>0。","a≠0时a^(−r)=1/a^r；a>0时常用指数律在本节有理指数范围成立。","负底数只在相应实根有意义并明确约定时处理；(−8)^(1/3)=−2，而(−8)^(1/2)无实数值。"],"examples":[{"q":"求27^(2/3)，解释分子分母的作用。","given":"底数正。","analysis":"先立方根再平方。","method":"(∛27)²。","principle":"分母为根次数，分子为幂次数。","steps":["∛27=3。","3²=9。"],"ans":"9。","verification":"9³=729=27²。","pitfall":"算成27²/3。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":4,"primary_section":"4.2","related_sections":[]},{"q":"求16^(−3/4)。","given":"底数正非零。","analysis":"负号表示倒数，不是结果负。","method":"先四次根与立方，再取倒数。","principle":"a^(−r)=1/a^r。","steps":["16^(1/4)=2，16^(3/4)=8。","原式=1/8。"],"ans":"1/8。","verification":"乘16^(3/4)=8得1。","pitfall":"答−8或−1/8。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":4,"primary_section":"4.2","related_sections":[]},{"q":"有人由((−1)²)^(1/2)=(−1)^(2×1/2)推出1=−1，哪一步越过条件？","given":"底数为负，外层平方根取非负主根。","analysis":"幂的幂法则不能无条件用于该负底数扩展。","method":"分别按定义计算并查条件。","principle":"实数主根使√x²=|x|。","steps":["左边√1=1。","右边(−1)^1=−1；把幂律从正底数推广到此例不合法。"],"ans":"错误在无条件合并指数。","verification":"正确左式等于|−1|=1，不造成矛盾。","pitfall":"只背指数律不检查底数与根定义。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":4,"primary_section":"4.2","related_sections":[]}],"practice":[{"q":"81^(3/4)是多少？","given":"正底数。","analysis":"四次根后立方。","method":"(⁴√81)³。","principle":"有理指数定义。","steps":["⁴√81=3。","3³=27。"],"ans":"27。","verification":"27⁴=81³。","pitfall":"把分母当除数。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":4,"primary_section":"4.2","related_sections":[]},{"q":"a>0，a^(1/2)×a^(3/2)化简。","given":"底数同且为正。","analysis":"同底数乘法加指数。","method":"1/2+3/2=2。","principle":"指数律适用。","steps":["指数和2。","结果a²。"],"ans":"a²。","verification":"a=4时2×8=16。","pitfall":"指数相乘而非相加。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":4,"primary_section":"4.2","related_sections":[]},{"q":"0^(−1/2)在实数内是否有定义？","given":"负指数要求倒数。","analysis":"根可0但倒数不可。","method":"写1/√0。","principle":"分母不得为0。","steps":["√0=0。","1/0无定义。"],"ans":"无定义。","verification":"0的正1/2次幂有定义，不可混淆。","pitfall":"见根号0就说全部可算。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":4,"primary_section":"4.2","related_sections":[]},{"q":"a>0，(a^(3/2)/a^(1/2))^(−2)化简并说明条件。","given":"同一正底数。","analysis":"先同底数相除再幂。","method":"指数差1后取负二次幂。","principle":"正底数指数律及倒数。","steps":["里面a^(3/2−1/2)=a。","a^(−2)=1/a²，a>0保留。"],"ans":"1/a²，a>0。","verification":"a=2时(√8/√2)⁻²=2⁻²=1/4。","pitfall":"化简后擅自加回a=0或负底数。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":4,"primary_section":"4.2","related_sections":[]}],"quiz":{"q":"对正底数a，有a^(1/2)+a^(1/2)=a¹吗？","given":"是加法而非同底数乘法。","analysis":"指数律适用运算类型不同。","method":"合并同类根式。","principle":"a^r×a^s才加指数。","steps":["和为2a^(1/2)。","取a=9，左6而a¹=9，否定原式。"],"ans":"不对，应为2√a。","verification":"与两个相同项相加的代数规则一致。","pitfall":"把乘法指数律套进加法。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":4,"primary_section":"4.2","related_sections":[]},"exam":["指数题先圈底数和完整指数，负指数先辨倒数","合并前写条件，正底数规则不能无条件推负底数","加减只合并同类项，不把乘除指数律跨运算使用"],"quick":["有理指数定义","正底数","负指数倒数","指数律","负底数边界"],"exam_evidence":[],"content_sources":[{"source_id":"directory_math","url":"https://www.scribd.com/document/1058092101/数学-高一上册","page":"目录：Math_S1_Up_Content.indd 6（2025版；用户确认相符）","version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_math_4.2","url":"https://openstax.org/books/algebra-and-trigonometry-2e/pages/1-3-radicals-and-rational-exponents","page_or_section":"1-3-radicals-and-rational-exponents","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_math","url":"https://www.scribd.com/document/1058092101/数学-高一上册","page":"目录：Math_S1_Up_Content.indd 6（2025版；用户确认相符）","version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_math_4.2","url":"https://openstax.org/books/algebra-and-trigonometry-2e/pages/1-3-radicals-and-rational-exponents","page_or_section":"1-3-radicals-and-rational-exponents","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"指数题先圈底数和完整指数，负指数先辨倒数","method":"分别按定义计算并查条件。","principle":"实数主根使√x²=|x|。","worked_example_index":2,"verification":"正确左式等于|−1|=1，不造成矛盾。","pitfall":"只背指数律不检查底数与根定义。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“用根式定义有理指数并注明底数条件”的抽样复核：9³=729=27²。；若出现“算成27²/3。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e1","review_module":5,"feedback":"目标“正确处理负指数与指数运算的边界”的抽样复核：乘16^(3/4)=8得1。；若出现“答−8或−1/8。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"把乘法指数律套进加法。","correction":"不对，应为2√a。","verification":"与两个相同项相加的代数规则一致。"}],"illustration_spec":{"title":"有理指数与条件","objects":["a^(m/n)与根式对应","27^(2/3)","16^(−3/4)","正负底数边界"],"relations":["分母开根分子幂","负指数取倒数","正底数指数律有条件"],"labels":["a>0","n为正整数","1/a^r","27^(2/3)=9","实数范围"],"format":"SVG","priority":"P0","reuse":"暂无对应旧图；公式需文字层和准确上下标","english":"Explain rational exponents for positive bases: denominator as root index and numerator as power. Show 27^(2/3)=9 and 16^(-3/4)=1/8. State nonzero conditions for negative exponents and warn that power-of-a-power rules cannot be extended blindly to negative bases and principal even roots."}},"4.3":{"subject":"数学","subject_code":"math_shared","chapter_id":4,"section_id":"4.3","goals":["在定义域内化简与合并根式","保留绝对值并解释平方变形风险"],"prerequisites":["根式与有理指数","分配律"],"flow":["定义域","提出平方因子","同类项","交叉项","平方与增根"],"concept_relation":"定义域；提出平方因子；同类项；交叉项；平方与增根","deep":["根式乘法遵守分配律，并需处理交叉项。平方(a+b)²=a²+2ab+b²，根式里的平方也不能漏2ab。比如(√3+√2)²=5+2√6，不是5。","涉及变量符号时可分区间化简绝对值。若同时有|x−1|和|x+1|，以−1、1分段，每段才有确定去符号形式。多个根号的定义域与分段条件应同时保留，不可只给一个看似短的式子。","方程中两边平方通常只保证原解满足平方后的式子，反向可能引入额外解。需先检查根号一侧非负等条件，得到候选后代回原式；简化恒等式与解方程中的变形逻辑应分开。","检验可用近似估值、代入边界和反例辅助，最终仍应给代数依据。把√2+√3估成约3.146，而√5约2.236，可以快速发现误合并；但数值接近不能作为恒等证明。"],"derive":["a,b≥0时√a√b=√(ab)；a≥0、b>0时√a/√b=√(a/b)。","√(x²)=|x|；(√a+√b)²=a+b+2√(ab)，a,b≥0。","解含根式方程：定义域与符号 → 隔离根式 → 平方求候选 → 代回原式排除增根。"],"examples":[{"q":"化简√72−√32+√8。","given":"均为非负常数根式。","analysis":"先提出平方因子。","method":"分别化为√2的倍数再合并。","principle":"乘法根式法则及同类项。","steps":["√72=6√2，√32=4√2，√8=2√2。","合为(6−4+2)√2=4√2。"],"ans":"4√2。","verification":"近似8.485−5.657+2.828≈5.656=4√2。","pitfall":"直接根号内72−32+8。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":4,"primary_section":"4.3","related_sections":[]},{"q":"展开(2√3−√2)²并验算。","given":"实数根式。","analysis":"交叉项有负号。","method":"a²−2ab+b²。","principle":"完全平方展开。","steps":["(2√3)²=12，(√2)²=2。","交叉项−4√6，合14−4√6。"],"ans":"14−4√6。","verification":"原括号约2.050，平方约4.202；结果14−9.798≈4.202。","pitfall":"漏交叉项或把−√2平方成−2。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":4,"primary_section":"4.3","related_sections":[]},{"q":"解√(x+2)=x，说明平方后的两个候选如何筛选。","given":"实数范围。","analysis":"右侧也必须非负。","method":"先x≥0，再平方并代回。","principle":"主根非负；平方可能引增根。","steps":["平方得x+2=x²，(x−2)(x+1)=0，候选2、−1。","x=2满足√4=2；x=−1时√1=1≠−1，排除。"],"ans":"x=2。","verification":"定义域x≥−2不够，等式还要求x≥0。","pitfall":"只检查被开方非负就保留−1。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":4,"primary_section":"4.3","related_sections":[]}],"practice":[{"q":"√50+2√8化简。","given":"常数非负。","analysis":"先化简再合并。","method":"√50=5√2，√8=2√2。","principle":"同类根式系数相加。","steps":["原式=5√2+4√2。","合9√2。"],"ans":"9√2。","verification":"平方或近似可核约12.728。","pitfall":"把2√8当√16。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":4,"primary_section":"4.3","related_sections":[]},{"q":"x<0、y≥0，化简√(4x²y)。","given":"给定符号范围。","analysis":"提出|x|再用x<0。","method":"2|x|√y。","principle":"主根非负。","steps":["√(4x²y)=2|x|√y。","x<0得−2x√y。"],"ans":"−2x√y。","verification":"x=−1、y=9时原6，结果6。","pitfall":"写2x√y为负。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":4,"primary_section":"4.3","related_sections":[]},{"q":"√(−2)√(−8)=√16=4在实数题中合法吗？","given":"两个单独根式负被开方数。","analysis":"左式无实数定义。","method":"核法则前提。","principle":"平方根乘法法则要求各被开方非负。","steps":["√(−2)、√(−8)在实数内无定义。","故不能用乘积为正挽救原式。"],"ans":"不合法。","verification":"若改讨论复数，运算约定也不能沿用该实数乘法结论。","pitfall":"只检查ab≥0而不查a,b本身。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":4,"primary_section":"4.3","related_sections":[]},{"q":"化简√((x−1)²)+√((x+1)²)的全实数分段式。","given":"原式所有实数有定义。","analysis":"绝对值符号在±1处改变。","method":"转为|x−1|+|x+1|分段。","principle":"主根和绝对值定义。","steps":["x<−1：1−x−x−1=−2x。","−1≤x≤1：1−x+x+1=2。","x>1：x−1+x+1=2x。"],"ans":"x<−1为−2x，中间为2，x>1为2x。","verification":"边界±1两侧都给2，连续且非负。","pitfall":"两个根号直接去掉得2x全域。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":4,"primary_section":"4.3","related_sections":[]}],"quiz":{"q":"“√(a+b)=√a+√b对a,b≥0都成立”，怎样用代数指出遗漏条件？","given":"两边有实数意义。","analysis":"平方右边出现交叉项。","method":"比较平方。","principle":"非负数相等可由平方等比较。","steps":["右边平方=a+b+2√ab。","要与左平方a+b相等，需ab=0；一般a,b都正时不成立。"],"ans":"一般错误；在a,b≥0且至少一个为0时才成立。","verification":"a=b=1给√2≠2。","pitfall":"根号对加法当作可分配。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":4,"primary_section":"4.3","related_sections":[]},"exam":["运算题先化简根式再合并同类，变量提出平方保留绝对值","含根式方程平方后一定回原式，符号约束比根号域更强时要列出","证明题用展开交叉项或反例，别用几个近似值替代"],"quick":["定义域","提出平方因子","同类项","交叉项","平方与增根"],"exam_evidence":[],"content_sources":[{"source_id":"directory_math","url":"https://www.scribd.com/document/1058092101/数学-高一上册","page":"目录：Math_S1_Up_Content.indd 6（2025版；用户确认相符）","version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_math_4.3","url":"https://openstax.org/books/algebra-and-trigonometry-2e/pages/1-3-radicals-and-rational-exponents","page_or_section":"1-3-radicals-and-rational-exponents","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_math","url":"https://www.scribd.com/document/1058092101/数学-高一上册","page":"目录：Math_S1_Up_Content.indd 6（2025版；用户确认相符）","version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_math_4.3","url":"https://openstax.org/books/algebra-and-trigonometry-2e/pages/1-3-radicals-and-rational-exponents","page_or_section":"1-3-radicals-and-rational-exponents","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"运算题先化简根式再合并同类，变量提出平方保留绝对值","method":"先x≥0，再平方并代回。","principle":"主根非负；平方可能引增根。","worked_example_index":2,"verification":"定义域x≥−2不够，等式还要求x≥0。","pitfall":"只检查被开方非负就保留−1。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“在定义域内化简与合并根式”的抽样复核：近似8.485−5.657+2.828≈5.656=4√2。；若出现“直接根号内72−32+8。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“保留绝对值并解释平方变形风险”的抽样复核：定义域x≥−2不够，等式还要求x≥0。；若出现“只检查被开方非负就保留−1。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"根号对加法当作可分配。","correction":"一般错误；在a,b≥0且至少一个为0时才成立。","verification":"a=b=1给√2≠2。"}],"illustration_spec":{"title":"根式运算的条件与交叉项","objects":["平方因子分解","√2同类项","完全平方交叉矩形","绝对值分段图","方程候选筛选"],"relations":["保留2ab交叉项","提出x²为绝对值","平方候选−1需排除"],"labels":["a,b≥0","√x²=|x|","2√ab","候选≠原解"],"format":"SVG","priority":"P0","reuse":"无对应旧图；坐标和面积关系应确定性构图","english":"Illustrate extraction of square factors and like radicals, retain the 2ab cross term in a square-area model, and graph abs(x-1)+abs(x+1) with breakpoints -1 and 1. Show why squaring sqrt(x+2)=x gives an extraneous candidate -1 that must be rejected."}},"4.4":{"subject":"数学","subject_code":"math_shared","chapter_id":4,"section_id":"4.4","goals":["用共轭及乘法恒等式有理化","在等价变形中保留原定义域"],"prerequisites":["根式运算","平方差与分式"],"flow":["同乘非零因子","共轭平方差","单项根式","高次恒等式","原域保留"],"concept_relation":"同乘非零因子；共轭平方差；单项根式；高次恒等式；原域保留","deep":["有理化因式不止限平方根共轭，某些高次根可用相应乘法恒等式，例如立方根项用a³−b³关系。是否在具体课程与题目中要求哪种形式需按教材与题设，本节基础以平方根及清楚给定的立方差示例为主。","含变量的分母要把根式定义域和整个分母非零条件先写出。化简后的式子可能在原排除点有值，这不代表原式已定义；等价是在共同的原定义域内，不能擅自扩域。","有理化还可帮助比较接近数、计算差值或把嵌套根式化为较简表达，但不能为了形式短而引入数值不稳定或漏掉符号。是否最终必须有理化取决题目要求，数学上原式有意义即为一个合法表达。","检查结果用分母乘回、代值和极限辅助。若分母由正数构成而结果明显为负，要回查共轭符号；若化简得0/0，在原式定义与所乘因子条件之间寻找问题，而非立即把值设0。"],"derive":["a>0：1/√a=√a/a。","m,n≥0且m≠n时，1/(√m+√n)=(√m−√n)/(m−n)；m=n>0时应直接处理2√m。","(a−b)(a²+ab+b²)=a³−b³，可为特定立方根分母构造有理化因式。"],"examples":[{"q":"有理化3/√5。","given":"分母√5非零。","analysis":"同乘√5。","method":"分子分母乘同一非零量。","principle":"√5×√5=5。","steps":["3/√5=(3√5)/(√5√5)。","得到3√5/5。"],"ans":"3√5/5。","verification":"结果乘原分母√5得3。","pitfall":"只把分母改5而分子不变。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":4,"primary_section":"4.4","related_sections":[]},{"q":"有理化1/(√3+√2)并验符号。","given":"分母正且共轭非零。","analysis":"用平方差。","method":"同乘√3−√2。","principle":"(a+b)(a−b)=a²−b²。","steps":["分母变3−2=1。","结果√3−√2。"],"ans":"√3−√2。","verification":"约0.318，原1/(1.732+1.414)约0.318且为正。","pitfall":"把共轭差平方当3+2。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":4,"primary_section":"4.4","related_sections":[]},{"q":"化简(√x−1)/(x−1)，写定义域并解释为何不能补x=1。","given":"实数平方根。","analysis":"分母可因式分解，取消需非零。","method":"x−1=(√x−1)(√x+1)。","principle":"等价约分保留原排除点。","steps":["原域x≥0且x≠1。","约去非零√x−1得1/(√x+1)。","新式在1处可算1/2，但原式仍0/0无定义。"],"ans":"1/(√x+1)，x≥0且x≠1。","verification":"x=4时原(2−1)/3=1/3，新式同；x=1仍排除。","pitfall":"约分后把可去间断点当原函数值。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":4,"primary_section":"4.4","related_sections":[]}],"practice":[{"q":"有理化2/(3√2)。","given":"常数分母非零。","analysis":"系数与根式分别处理。","method":"同乘√2再约分。","principle":"分式等价。","steps":["2√2/(3×2)=2√2/6。","约为√2/3。"],"ans":"√2/3。","verification":"乘3√2得2。","pitfall":"把3也平方成9。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":4,"primary_section":"4.4","related_sections":[]},{"q":"有理化1/(2−√3)。","given":"2−√3>0。","analysis":"同乘共轭2+√3。","method":"平方差。","principle":"4−3=1。","steps":["分子2+√3。","分母1，结果2+√3。"],"ans":"2+√3。","verification":"(2−√3)(2+√3)=1。","pitfall":"只改根号号不同时改完整因子。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":4,"primary_section":"4.4","related_sections":[]},{"q":"a>0，能对1/(√a+√a)同乘√a−√a吗？应怎样做？","given":"原分母2√a非零，共轭却0。","analysis":"所乘因子必须非零。","method":"先合并再单项有理化。","principle":"不能同乘0/0。","steps":["原式1/(2√a)。","乘√a/√a得√a/(2a)。"],"ans":"不能乘零共轭；结果√a/(2a)。","verification":"a=1时为1/2，与原相符。","pitfall":"把共轭法无条件用于相同根式。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":4,"primary_section":"4.4","related_sections":[]},{"q":"有理化1/(∛2−1)，给出乘因子并回乘。","given":"实数立方根，分母非零。","analysis":"使用立方差恒等式。","method":"设a=∛2，乘a²+a+1。","principle":"(a−1)(a²+a+1)=a³−1。","steps":["分母变2−1=1。","结果∛4+∛2+1。"],"ans":"∛4+∛2+1。","verification":"乘回∛2−1后中间项抵消得1。","pitfall":"仍用平方共轭却误认为分母已无根。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":4,"primary_section":"4.4","related_sections":[]}],"quiz":{"q":"为何把1/(√x−1)有理化成(√x+1)/(x−1)后，定义域仍需x≥0且x≠1？","given":"两式都应在原域比较。","analysis":"平方根与分母限制不因变形消失。","method":"逐条保留条件。","principle":"同乘非零因子的等价变形。","steps":["x≥0使根式有意义。","x=1使原分母0；有理化式分母也0，不能以形式变化改变域。"],"ans":"因原定义条件必须保留。","verification":"x=0时原−1，新式1/(−1)=−1，边界0可取。","pitfall":"把分母含x−1就只写x≠1，漏根域。","question_origin":"original","paper_no":null,"subject_code":"math_shared","chapter_id":4,"primary_section":"4.4","related_sections":[]},"exam":["有理化题说明同乘因子并查非零，平方差符号写完整","变量题先写定义域，约分后保留原排除点","共轭为零的退化情况直接合并，不能机械除零"],"quick":["同乘非零因子","共轭平方差","单项根式","高次恒等式","原域保留"],"exam_evidence":[],"content_sources":[{"source_id":"directory_math","url":"https://www.scribd.com/document/1058092101/数学-高一上册","page":"目录：Math_S1_Up_Content.indd 6（2025版；用户确认相符）","version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_math_4.4","url":"https://openstax.org/books/algebra-and-trigonometry-2e/pages/1-3-radicals-and-rational-exponents","page_or_section":"1-3-radicals-and-rational-exponents","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_math","url":"https://www.scribd.com/document/1058092101/数学-高一上册","page":"目录：Math_S1_Up_Content.indd 6（2025版；用户确认相符）","version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_math_4.4","url":"https://openstax.org/books/algebra-and-trigonometry-2e/pages/1-3-radicals-and-rational-exponents","page_or_section":"1-3-radicals-and-rational-exponents","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"有理化题说明同乘因子并查非零，平方差符号写完整","method":"x−1=(√x−1)(√x+1)。","principle":"等价约分保留原排除点。","worked_example_index":2,"verification":"x=4时原(2−1)/3=1/3，新式同；x=1仍排除。","pitfall":"约分后把可去间断点当原函数值。"},"diagnostics":[{"goal_index":0,"question_ref":"e1","review_module":4,"feedback":"目标“用共轭及乘法恒等式有理化”的抽样复核：约0.318，原1/(1.732+1.414)约0.318且为正。；若出现“把共轭差平方当3+2。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“在等价变形中保留原定义域”的抽样复核：x=4时原(2−1)/3=1/3，新式同；x=1仍排除。；若出现“约分后把可去间断点当原函数值。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"把分母含x−1就只写x≠1，漏根域。","correction":"因原定义条件必须保留。","verification":"x=0时原−1，新式1/(−1)=−1，边界0可取。"}],"illustration_spec":{"title":"有理化与原定义域","objects":["共轭乘法矩形","√3±√2","变量约分","x=1空点","立方差因式"],"relations":["分子分母同乘非零","平方差3−2=1","取消因子仍保留排除点"],"labels":["共轭","非零因子","x≥0且x≠1","1/(√x+1)","空点不是原函数值"],"format":"SVG","priority":"P0","reuse":"暂无对应旧图；代数和函数空点需确定性SVG","english":"Show rationalization of 1/(sqrt(3)+sqrt(2)) by its nonzero conjugate. For (sqrt(x)-1)/(x-1), retain x>=0 and x!=1 after simplification to 1/(sqrt(x)+1), drawing an open point at x=1 rather than filling in the original undefined value."}}},"物理1":{"1.1":{"subject":"物理","subject_code":"physics","chapter_id":1,"section_id":"1.1","goals":["用物理量与条件描述现象","区分模型预测、测量与结论"],"prerequisites":["基本算术","观察与推断"],"flow":["观察问题","物理量","理想模型","预测测量","条件与修正"],"concept_relation":"观察问题；物理量；理想模型；预测测量；条件与修正","deep":["规律包含适用范围。匀速模型要求相应参考系和时间段内速度不变；近地面重力加速度近似常量并不表示从地面到无限远都适用。模型预测与观测不符时，应检查测量、条件与模型，而不是先把数据改到公式上。","实验值通常有不确定性，精确的理论关系在测量中不必表现为所有点完全共线。用趋势、误差范围和重复性比较模型，比只挑一组吻合数字更可靠。但“不确定”也不意味任何结论同样正确，证据仍能排除明显不符的解释。","物理学与技术相互促进，技术应用还受到材料、成本、环境与安全等限制。一项理论能够说明某过程，不表示任何规模的技术装置都已可行；现实工程需要检验边界条件与能量、材料等约束。","做定量题应先把语言转为对象、状态、过程与条件，再选公式。单位检查和极限情况可快速排除错误，例如平均速度结果若没有长度/时间单位就应回查；单位正确只是一项必要检查，不能证明所用物理模型一定正确。"],"derive":["物理量Q=数值×单位；换单位时量保持不变，数值按换算改变。","平均速度定义为位移/对应时间间隔；路程/时间是平均速率，不能仅凭单位相同便当作同量。","模型有效性检验：明确条件 → 给可测预测 → 与含不确定性的结果比较 → 保留或修正。"],"examples":[{"q":"学生写一段长度为2，另一人写200，能直接判断谁测得更长吗？","given":"未给单位。","analysis":"数值依赖单位。","method":"补单位并统一。","principle":"物理量需数值与单位。","steps":["若分别为2 m与200 cm，二者相等。","若同为m，则200 m更长，现信息不足。"],"ans":"不能，先明确单位。","verification":"1 m=100 cm，故2 m=200 cm。","pitfall":"不看单位直接比较数值。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":1,"primary_section":"1.1","related_sections":[]},{"q":"公交车从家到学校研究行程时间时可否看作质点？研究它能否通过窄门又怎样？","given":"比较两个不同问题。","analysis":"同一物体能否作质点依任务。","method":"检查尺寸是否影响答案。","principle":"模型忽略因素必须对当前问题可忽略。","steps":["路程远大于车尺寸且不研究转动时可近似质点。","过门时车宽高直接决定通过，不能忽略。"],"ans":"前者在条件满足时可以，后者不可。","verification":"门宽若小于车宽，质点模型会给错误通过结论。","pitfall":"把质点当物体固定属性。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":1,"primary_section":"1.1","related_sections":[]},{"q":"公式算得1.5 m/s，实测1.6±0.2 m/s，可否只因数值不同就否定模型？","given":"不确定性范围给定为比较用。","analysis":"要比较预测与测量范围及其他条件。","method":"检查是否相容，再看测量与模型假设。","principle":"测量有不确定性；相容不等于最终证明。","steps":["范围为1.4至1.8 m/s。","1.5在其中，因此这次差异本身不足否定，但还应多条件重复检验。"],"ans":"不能仅据此否定；此次结果相容。","verification":"1.5在给定范围内且单位相同。","pitfall":"要求实验值与理论小数完全一致。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":1,"primary_section":"1.1","related_sections":[]}],"practice":[{"q":"速度与速率单位相同，是否概念必相同？","given":"两者都可用m/s。","analysis":"单位不能编码方向及全部定义。","method":"比较位移与路程。","principle":"速度含方向，速率为标量。","steps":["往返原点位移为0。","路程可大于0，平均速度与平均速率可不同。"],"ans":"不同。","verification":"往返例子可同单位而数值不同。","pitfall":"只按单位判断物理概念。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":1,"primary_section":"1.1","related_sections":[]},{"q":"球大小很小，所以研究它滚动时必能完全忽略转动吗？","given":"研究滚动能量。","analysis":"绝对尺寸小不等于转动效应小。","method":"检查所求是否依赖转动。","principle":"模型要保留影响目标的自由度。","steps":["滚动可有平动与转动能。","若要求总能量，不能无条件忽略转动。"],"ans":"不能。","verification":"即使球小，转动能所占比例未必趋零。","pitfall":"用小这一形容代替尺度与影响比较。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":1,"primary_section":"1.1","related_sections":[]},{"q":"单位检查通过能证明方程一定正确吗？","given":"只知两边量纲相同。","analysis":"相容是必要检查而非充分验证。","method":"给同量纲错式反例。","principle":"无量纲系数及物理条件仍可能错误。","steps":["v=s/t与v=2s/t量纲相同。","只有正确的定义或模型才能决定系数。"],"ans":"不能。","verification":"两式在同一s,t下不同，不可都由量纲证明。","pitfall":"把量纲相同当完整证明。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":1,"primary_section":"1.1","related_sections":[]},{"q":"测量范围3.0±0.1 N，模型预测3.4 N，怎样提出下一步而非直接改数据？","given":"按题给范围比较。","analysis":"明显不相容应追查。","method":"检查仪器、重复与模型条件。","principle":"科学推理要求保留原记录。","steps":["范围2.9至3.1 N，不含3.4。","复核校准、控制变量及模型适用性，再新测，不篡改原值。"],"ans":"存在不相容，需调查来源。","verification":"偏差0.4 N大于给定0.1 N范围。","pitfall":"为吻合模型修改观察。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":1,"primary_section":"1.1","related_sections":[]}],"quiz":{"q":"一条关系在实验室低速情境吻合，能否无条件宣布适用于任何速度与尺度？","given":"证据仅在有限条件内。","analysis":"验证范围有限。","method":"限定条件并提出外推检验。","principle":"规律模型的适用性需证据支持。","steps":["明确已测速度与尺度。","到新范围需重新核理论假设和观测，不能由有限证据推出无限适用。"],"ans":"不能无条件外推。","verification":"未测范围仍可存在需要修正的效应。","pitfall":"把若干吻合当作无限证明。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":1,"primary_section":"1.1","related_sections":[]},"exam":["概念题用定义、对象和条件作答，不仅写一句生活描述","模型题说明略去因素为什么不影响当前目标","证据题同时写相容性与检验范围，不将一次吻合称为证明"],"quick":["观察问题","物理量","理想模型","预测测量","条件与修正"],"exam_evidence":[],"content_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":2,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_1.1","url":"https://openstax.org/books/college-physics-2e/pages/1-1-physics-an-introduction","page_or_section":"1-1-physics-an-introduction","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":2,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_1.1","url":"https://openstax.org/books/college-physics-2e/pages/1-1-physics-an-introduction","page_or_section":"1-1-physics-an-introduction","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"概念题用定义、对象和条件作答，不仅写一句生活描述","method":"检查是否相容，再看测量与模型假设。","principle":"测量有不确定性；相容不等于最终证明。","worked_example_index":2,"verification":"1.5在给定范围内且单位相同。","pitfall":"要求实验值与理论小数完全一致。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“用物理量与条件描述现象”的抽样复核：1 m=100 cm，故2 m=200 cm。；若出现“不看单位直接比较数值。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“区分模型预测、测量与结论”的抽样复核：1.5在给定范围内且单位相同。；若出现“要求实验值与理论小数完全一致。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"把若干吻合当作无限证明。","correction":"不能无条件外推。","verification":"未测范围仍可存在需要修正的效应。"}],"illustration_spec":{"title":"从现象到可检验模型","objects":["实际物体","质点近似","可测量量","含误差数据","模型预测"],"relations":["近似由问题决定","证据比较有条件","不画成一次吻合终结验证"],"labels":["数值×单位","对象与条件","预测","测量与不确定性"],"format":"SVG","priority":"P2","reuse":"可用文字关系图，非必须新增插画","english":"Show observation, physical quantities, a question-specific model, measurable predictions and uncertainty-aware comparison. Contrast treating a bus as a particle for a long journey with retaining its size at a narrow doorway."}},"1.2":{"subject":"物理","subject_code":"physics","chapter_id":1,"section_id":"1.2","goals":["设计可检验的单因素实验","区分归纳、演绎与因果证据"],"prerequisites":["变量与比例","测量记录"],"flow":["提出可测假设","控制变量","重复记录","图象与推断","修正模型"],"concept_relation":"提出可测假设；控制变量；重复记录；图象与推断；修正模型","deep":["理想化与等效方法降低问题复杂度，例如用一个合力描述多个力对质点运动的共同效果。等效须说明等效于哪种作用；相同合力未必对刚体产生相同力矩，不能在所有任务中把力的作用点删去。","实验结果需要原始记录、单位、仪器分辨与处理说明。发现异常点应先核记录或操作原因；没有依据不能只为直线好看就删点。拟合或平均值是对数据的处理，不能伪装成每一次实际读数。","相关性可提示机制，却不自动表明因果。同步变化可能来自共同因素或选择偏差；设置对照、改变自变量及检查时间先后等能增强因果判断，但还应明确实验条件和不确定性。","报告研究时，应把观察事实、数据处理、模型解释及限制分别说清。若只在小伸长范围验证弹簧关系，就写该范围内近似成立，不将其推广至塑性变形或断裂。可复核的过程比一个没有记录的漂亮结论更重要。"],"derive":["检验正比y=kx：比较y/x是否近似恒定，并检查图线是否与原点相容；非零截距需解释或改模型。","重复n次取平均x̄=Σxᵢ/n可减小部分随机波动影响，但共同偏移b仍留在x̄中。","设计结构：问题 → 自变量与水平 → 因变量测法 → 控制与对照 → 重复记录 → 处理 → 条件内结论。"],"examples":[{"q":"研究单摆长度对周期的影响，应改变什么、测什么，并控制什么？","given":"以小摆角近似实验，不讨论详细公式。","analysis":"区分变量角色。","method":"设计单因素系列比较。","principle":"控制变量隔离长度影响。","steps":["改变摆长并测每次多周期总时再平均。","保持摆角小且可比，摆球与计时方式一致，重复各长度测量。"],"ans":"改摆长、测周期，控制摆角等并重复。","verification":"若同时改摆角和长度，就无法独立归因。","pitfall":"控制全部量导致根本没有自变量。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":1,"primary_section":"1.2","related_sections":[]},{"q":"测得x=1,2,3时y=3,5,7，可称y与x成正比吗？","given":"数据精确作数学示例。","analysis":"直线可有非零截距。","method":"求比值及截距。","principle":"正比需y=kx。","steps":["y/x分别3、2.5、7/3，不恒定。","数据满足y=2x+1，截距1。"],"ans":"是线性关系，但不是正比。","verification":"x=0时延长模型给y=1而非0。","pitfall":"见直线就写正比。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":1,"primary_section":"1.2","related_sections":[]},{"q":"所有长度读数都因零点偏移多0.2 cm，取100次平均能自动消除吗？","given":"每次同方向同量偏移。","analysis":"系统偏移不会因次数互相抵消。","method":"写读数=真值+共同偏移+随机项。","principle":"平均只可能减小独立随机波动部分。","steps":["平均后共同0.2 cm仍存在。","需校准零点或在有依据时修正，并记录方法。"],"ans":"不能自动消除。","verification":"相同常数的平均仍是该常数。","pitfall":"将重复视为一切误差的解药。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":1,"primary_section":"1.2","related_sections":[]}],"practice":[{"q":"一异常点偏离趋势，是否可以直接删除？","given":"未找到操作或记录错误。","analysis":"删点需依据。","method":"保留原值并调查重复。","principle":"数据处理须可复核。","steps":["检查读数、仪器与条件。","重测并报告处理理由，不能仅为拟合好看删点。"],"ans":"不可无依据删除。","verification":"异常也可能揭示模型范围失效。","pitfall":"用预期规律筛掉不喜欢的结果。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":1,"primary_section":"1.2","related_sections":[]},{"q":"合力相同能否保证对刚体转动作用相同？","given":"不同力作用点。","analysis":"平动与转动的等效条件不同。","method":"比较力矩。","principle":"力矩还依力臂。","steps":["相同大小方向的力可在不同位置作用。","力臂不同使转动效果不同。"],"ans":"不能。","verification":"门把手和铰链附近推门提供反例。","pitfall":"把质点等效推广所有刚体作用。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":1,"primary_section":"1.2","related_sections":[]},{"q":"三次周期1.9、2.0、2.1 s，平均多少？能否说误差已完全没有？","given":"三次同条件测量。","analysis":"平均是估计不是绝对真值。","method":"求和除次数再讨论。","principle":"算术平均可减小随机波动影响。","steps":["(1.9+2.0+2.1)/3=2.0 s。","仍可能有分辨限制和共同偏移。"],"ans":"2.0 s；不代表零误差。","verification":"结果处在读数范围内。","pitfall":"平均后报告无限精确。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":1,"primary_section":"1.2","related_sections":[]},{"q":"测y随x变化为2,4,6对应1,2,3，能证明任何x下y=2x吗？","given":"只测三个范围内点。","analysis":"归纳范围有限。","method":"写局部模型并安排新范围检验。","principle":"有限观测不能自动证明无穷范围。","steps":["这些点与y=2x相容。","在未测范围需继续检验并考虑条件是否改变。"],"ans":"不能证明所有x，只支持已测条件中的模型。","verification":"其他函数也可通过这三个点。","pitfall":"把数据相容写成全域恒等证明。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":1,"primary_section":"1.2","related_sections":[]}],"quiz":{"q":"夏季冰品销量和溺水数同增，能证明吃冰品导致溺水吗？","given":"只有相关趋势。","analysis":"可能有气温等共同因素。","method":"列替代解释与可比数据。","principle":"相关不自动构成因果。","steps":["高温可同时增加冰品购买及游泳活动。","需控制暴露人数等并有机制证据，不能直接归因冰品。"],"ans":"不能。","verification":"共同因素能解释相关而无需直接因果。","pitfall":"把同时变化当作作用机制。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":1,"primary_section":"1.2","related_sections":[]},"exam":["探究题逐项给变量、测量、控制、重复及处理方法","图象题分线性与正比，截距和单位都要解释","结论题写在何范围支持何关系，不虚构完全证明或官方步骤分"],"quick":["提出可测假设","控制变量","重复记录","图象与推断","修正模型"],"exam_evidence":[],"content_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":11,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_1.2","url":"https://openstax.org/books/college-physics-2e/pages/1-1-physics-an-introduction","page_or_section":"1-1-physics-an-introduction","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":11,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_1.2","url":"https://openstax.org/books/college-physics-2e/pages/1-1-physics-an-introduction","page_or_section":"1-1-physics-an-introduction","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"探究题逐项给变量、测量、控制、重复及处理方法","method":"写读数=真值+共同偏移+随机项。","principle":"平均只可能减小独立随机波动部分。","worked_example_index":2,"verification":"相同常数的平均仍是该常数。","pitfall":"将重复视为一切误差的解药。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“设计可检验的单因素实验”的抽样复核：若同时改摆角和长度，就无法独立归因。；若出现“控制全部量导致根本没有自变量。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"q","review_module":5,"feedback":"目标“区分归纳、演绎与因果证据”的抽样复核：共同因素能解释相关而无需直接因果。；若出现“把同时变化当作作用机制。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"把同时变化当作作用机制。","correction":"不能。","verification":"共同因素能解释相关而无需直接因果。"}],"illustration_spec":{"title":"正比、线性与实验偏移","objects":["两坐标图","y=2x","y=2x+1","重复读数","零点偏移"],"relations":["正比图过原点","线性可非零截距","共同偏移平均后仍存在"],"labels":["x单位","y单位","截距","随机波动","共同偏移"],"format":"SVG","priority":"P1","reuse":"未有匹配图，宜确定性坐标绘图","english":"Draw accurately scaled plots of y=2x and y=2x+1 with labelled axes and intercepts. Separately show random scatter around a shifted mean to explain why averaging does not remove a common zero offset."}},"1.3":{"subject":"物理","subject_code":"physics","chapter_id":1,"section_id":"1.3","goals":["把题干转成对象过程与条件","用多种复核定位解题错误"],"prerequisites":["基本代数","单位换算"],"flow":["读题建图","审查条件","符号关系","单位计算","复核与迁移"],"concept_relation":"读题建图；审查条件；符号关系；单位计算；复核与迁移","deep":["建立关系后先作符号推导，再在单位一致时代值，能更容易看出结构和适用范围。负号不应在最后随意删去：它可能表示所选正方向相反，也可能来自错误符号或物理条件，必须回到定义解释。","复核可分单位、数量级、极限情况、独立方法与回代。每种检查都只能发现一类问题，不能单独代替完整推理。例如速度结果超过常见尺度应回查换算，但陌生情境不一定必须符合日常经验，应结合题设模型。","错题记录要保存触发条件、错法原因和改正后的判断步骤，不只抄正确答案。若把摩擦力恒写成μmg，应记录法向力为何未必为mg；下一次用斜面、竖直运动或外力改变压力的变式检验是否真正理解。","间隔回忆先合书解释概念与条件，再独立做新题，最后对照解析定位薄弱环节。能复述刚看过的解答不等于迁移掌握；自评应对应具体能力，例如能否正确建模、说明守恒条件和发现一个错误结果。"],"derive":["解题链：题意与对象 → 已知未知 → 方法条件 → 原理关系 → 符号推导 → 统一单位计算 → 答案解释 → 多项复核。","若同一过程匀加速，v=v₀+at；使用前必须把速度、时间与加速度对应到同一段。","量纲复核以速度为例：[at]=(m/s²)×s=m/s；即使通过仍需核初值、符号和条件。"],"examples":[{"q":"汽车以36 km/h行驶3 s，题目说明期间速度恒定，求位移。应先做什么？","given":"直线同方向匀速，36 km/h、3 s。","analysis":"速度单位与时间单位须统一。","method":"换算再用位移定义。","principle":"匀速同方向Δx=vΔt。","steps":["36 km/h=36/3.6=10 m/s。","Δx=10×3=30 m，方向为行驶方向。"],"ans":"30 m，沿行驶方向。","verification":"每秒10 m，3 s三份；单位m。","pitfall":"直接36×3得到108 m。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":1,"primary_section":"1.3","related_sections":[]},{"q":"直线运动取向右为正，v₀=5 m/s，恒定a=−2 m/s²，3 s末速度为负，能把负号去掉吗？","given":"同一参考系、同一匀加速阶段。","analysis":"负号表达方向，不是算错的充分证据。","method":"计算并回到方向定义。","principle":"v=v₀+at。","steps":["v=5−2×3=−1 m/s。","在2.5 s速度到0，此后向左，故3 s负速度合理。"],"ans":"不能；速度−1 m/s，速率1 m/s。","verification":"0点时刻5/2=2.5 s，3 s已转向。","pitfall":"把速度与速率混写。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":1,"primary_section":"1.3","related_sections":[]},{"q":"学生把一切摩擦题都写f=μmg，应怎样用错题记录改进？","given":"只知接触摩擦情境，未给平面等条件。","analysis":"μN中的N须由受力求得，且静摩擦不一定达到最大。","method":"分类摩擦类型再求法向力。","principle":"滑动摩擦近似f=μₖN，N不普遍为mg。","steps":["先画接触双方受力，判断滑动或静止。","再用垂直接触面方向的动力学求N；静摩擦按平衡需要及上限检查。"],"ans":"记录“先判类型、再求N、最后用适用关系”，不能固定μmg。","verification":"斜面N可能为mg cosθ，已构成反例。","pitfall":"只抄正确公式而不改选式条件。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":1,"primary_section":"1.3","related_sections":[]}],"practice":[{"q":"公式中t用min、速度用m/s，可以直接相乘得m吗？","given":"未转换单位。","analysis":"时间基准不一致。","method":"把min转为s。","principle":"量纲与单位换算需一致。","steps":["1 min=60 s。","先乘60再代入，或把速度改成m/min。"],"ans":"不可直接忽略单位差。","verification":"m/s×min尚有60倍转换。","pitfall":"把符号相同t看成单位已自动统一。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":1,"primary_section":"1.3","related_sections":[]},{"q":"题目发生碰撞，就一定能用两物体动量守恒吗？","given":"未给系统外冲量。","analysis":"关键词不足决定守恒。","method":"先选系统审查外冲量。","principle":"系统动量变化由外冲量决定。","steps":["看碰撞时段和外力冲量是否可忽略。","若不能忽略，须计外冲量而非直接设前后相等。"],"ans":"不一定。","verification":"内力大不自动保证外冲量严格零。","pitfall":"见碰撞便无条件套守恒。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":1,"primary_section":"1.3","related_sections":[]},{"q":"算得质量−3 kg应怎样处理？","given":"普通经典力学物体质量。","analysis":"负结果可能意味着方程、方向或条件有问题。","method":"回代和检查建模。","principle":"质量在本情境为非负量。","steps":["复核已知、方程移项和单位。","若假设无物理解，说明条件或模型不成立，不能仅去掉负号。"],"ans":"回查模型计算，不能机械取绝对值。","verification":"把3代原式若不满足就暴露修改不合法。","pitfall":"所有负号都删掉求漂亮答案。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":1,"primary_section":"1.3","related_sections":[]},{"q":"v₀=0、a=3 m/s²、t=4 s的匀加速运动，求末速度并给两项复核。","given":"同方向恒加速度。","analysis":"明确原理、计算与检查。","method":"v=v₀+at。","principle":"速度每秒增加3 m/s。","steps":["v=0+3×4=12 m/s。","单位(m/s²)s=m/s；逐秒3、6、9、12与结果一致。"],"ans":"12 m/s。","verification":"单位和逐步累积两项检查通过，但仍依恒a条件。","pitfall":"只写12而漏单位和条件。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":1,"primary_section":"1.3","related_sections":[]}],"quiz":{"q":"看解析时每一步都懂，是否已证明能独立解同类题？","given":"尚未合书独立作答。","analysis":"识别理解与主动生成不同。","method":"设计迁移自测。","principle":"掌握需能独立识别条件和选择方法。","steps":["合书重做并解释为何选式。","再做改变一个条件的变式，按错误定位概念、模型或运算。"],"ans":"尚不能证明；需独立和迁移检验。","verification":"换条件后仍能解释适用性才有更强证据。","pitfall":"把刚读过的熟悉感当作掌握。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":1,"primary_section":"1.3","related_sections":[]},"exam":["答题前把对象、方向和阶段写清，公式必须解释条件","负数结果分辨方向量与本应非负量，不统一取绝对值","复盘题记录选法错误并做条件变式，不能只抄答案"],"quick":["读题建图","审查条件","符号关系","单位计算","复核与迁移"],"exam_evidence":[],"content_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":17,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_1.3","url":"https://openstax.org/books/college-physics-2e/pages/1-2-physical-quantities-and-units","page_or_section":"1-2-physical-quantities-and-units","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":17,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_1.3","url":"https://openstax.org/books/college-physics-2e/pages/1-2-physical-quantities-and-units","page_or_section":"1-2-physical-quantities-and-units","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"答题前把对象、方向和阶段写清，公式必须解释条件","method":"分类摩擦类型再求法向力。","principle":"滑动摩擦近似f=μₖN，N不普遍为mg。","worked_example_index":2,"verification":"斜面N可能为mg cosθ，已构成反例。","pitfall":"只抄正确公式而不改选式条件。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“把题干转成对象过程与条件”的抽样复核：每秒10 m，3 s三份；单位m。；若出现“直接36×3得到108 m。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“用多种复核定位解题错误”的抽样复核：斜面N可能为mg cosθ，已构成反例。；若出现“只抄正确公式而不改选式条件。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"把刚读过的熟悉感当作掌握。","correction":"尚不能证明；需独立和迁移检验。","verification":"换条件后仍能解释适用性才有更强证据。"}],"illustration_spec":{"title":"条件驱动的物理解题流程","objects":["对象与阶段","受力/状态示意","方法选择节点","单位与回代检查","变式自测"],"relations":["选法由条件决定而非关键词","负号先解释物理意义","复核有多种互补方法"],"labels":["对象","条件","原理","单位","方向","验算"],"format":"SVG","priority":"P2","reuse":"可使用页面文字关系图","english":"Create a decision-oriented physics-solving flow from object and process to model conditions, symbolic equations, unit conversion and independent checks. Show that a negative velocity means direction whereas a negative ordinary mass requires model review."}}},"物理2":{"2.1":{"subject":"物理","subject_code":"physics","chapter_id":2,"section_id":"2.1","goals":["以SI单位和操作定义表达测量","由仪器结构选择读数与校正方法"],"prerequisites":["十进制换算","长度与时间"],"flow":["SI与派生单位","仪器选择","读数","零点校正","间接测量"],"concept_relation":"SI与派生单位；仪器选择；读数；零点校正；间接测量","deep":["用直尺测两刻度之间长度应作末读数减初读数，避免把尺的端部磨损或非零起点当作零。视线尽量垂直刻度以减视差；弯曲物或很小厚度可采用适合的间接方法，但要说明额外假设和可能偏差。","游标卡尺的读数由主尺读数加游标重合分度对应的增量，具体分度值依仪器设计；螺旋测微器由固定刻度与可动刻度合成，读前须识别螺距与分格，不可把某型号的公式数值套到所有仪器。下题均给定分度值，非用文字代替实际仪器图。","零点误差可带符号记录：若真零时读数为e，校正值=读数−e。正偏移要减，负偏移要加；不是看到“误差”就统一加上。修正也不表示其余不确定性全部消失。","重复测量、累计测量和测差等方法解决不同问题。测100张同类纸总厚度再除100可以降低单张太薄的读数困难，但纸受压、厚度差异和计数错误仍存在；方法应根据对象性质评估而不只追求多次。"],"derive":["1 cm=10⁻² m；1 cm²=10⁻⁴ m²；1 cm³=10⁻⁶ m³。","游标读数=主尺值+重合格数×给定分度值；零点校正x=x读−e。","ρ=m/V，若m用kg且V用m³，则ρ单位kg/m³；单位换算先于数值运算。"],"examples":[{"q":"250 cm³是多少m³？","given":"1 cm=10⁻² m。","analysis":"体积换算要把长度因子立方。","method":"250×(10⁻²)³。","principle":"体积由三维长度相乘。","steps":["1 cm³=10⁻⁶ m³。","250 cm³=250×10⁻⁶=2.50×10⁻⁴ m³。"],"ans":"2.50×10⁻⁴ m³。","verification":"1 m³=10⁶ cm³，反向换回250 cm³。","pitfall":"只乘10⁻²。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":2,"primary_section":"2.1","related_sections":[]},{"q":"卡尺主尺12 mm，游标第7格重合，分度值0.02 mm，正零误差0.04 mm，求校正结果。","given":"仪器型号与分度值由题给。","analysis":"先合成读数，再减有符号零偏。","method":"x=12+7×0.02−0.04。","principle":"零点偏移加在全部读数上。","steps":["读数12.14 mm。","校正值12.14−0.04=12.10 mm。"],"ans":"12.10 mm。","verification":"真值加偏移为12.14，与原读数相合。","pitfall":"正零偏反而加上。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":2,"primary_section":"2.1","related_sections":[]},{"q":"100张纸总厚度10.0 mm，忽略压缩且厚度相同，估单张厚度。为何方法并非绝对准确？","given":"张数可靠，总厚度为测量值。","analysis":"累计解决分辨问题但有模型假设。","method":"总量除张数并说明限制。","principle":"总厚度近似各张厚度之和。","steps":["10.0/100=0.100 mm。","压缩、间隙和纸张差异会使估计偏离单张实际。"],"ans":"0.100 mm，在题设模型下。","verification":"100×0.100=10.0 mm。","pitfall":"认为累计后所有系统偏差都消失。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":2,"primary_section":"2.1","related_sections":[]}],"practice":[{"q":"0.75 m²等于多少cm²？","given":"1 m=100 cm。","analysis":"面积换算因子平方。","method":"0.75×100²。","principle":"面积单位为长度单位平方。","steps":["1 m²=10000 cm²。","0.75×10000=7500 cm²。"],"ans":"7500 cm²。","verification":"7500×10⁻⁴=0.75 m²。","pitfall":"只乘100。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":2,"primary_section":"2.1","related_sections":[]},{"q":"尺上物体两端对应2.3与8.7 cm，长度多少？","given":"两刻度在同一尺上。","analysis":"长度是差不是末刻度。","method":"末减初。","principle":"坐标差表示间隔。","steps":["8.7−2.3=6.4。","两读数同单位，差为cm。"],"ans":"6.4 cm。","verification":"2.3+6.4=8.7 cm。","pitfall":"直接答8.7 cm。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":2,"primary_section":"2.1","related_sections":[]},{"q":"测微器读数5.18 mm，真零时显示−0.02 mm，校正多少？","given":"零偏e=−0.02 mm。","analysis":"负偏移意味着读数偏小。","method":"x=x读−e。","principle":"校正减去有符号偏移。","steps":["5.18−(−0.02)=5.20。","校正后仍有仪器分辨等限制。"],"ans":"5.20 mm。","verification":"5.20−0.02=5.18。","pitfall":"把负零偏也统一减绝对值。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":2,"primary_section":"2.1","related_sections":[]},{"q":"质量0.540 kg、体积200 cm³，求密度的SI值。","given":"体积须转m³。","analysis":"质量与体积必须一致单位体系。","method":"先换算再ρ=m/V。","principle":"密度是单位体积质量。","steps":["V=200×10⁻⁶=2.00×10⁻⁴ m³。","ρ=0.540/(2.00×10⁻⁴)=2700 kg/m³。"],"ans":"2.70×10³ kg/m³。","verification":"2700×2.00×10⁻⁴=0.540 kg。","pitfall":"把cm³数值直接与kg配算成SI。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":2,"primary_section":"2.1","related_sections":[]}],"quiz":{"q":"两仪器分辨值0.1 mm与0.01 mm，能否仅凭这点认定后者所有测量更准确？","given":"未知校准、操作与对象适配。","analysis":"分辨与准确程度不同。","method":"核零偏、量程与方法。","principle":"更细刻度不自动减少系统偏差。","steps":["后者可读更小增量。","若零偏大或方法不合适，其结果可能更偏离真值。"],"ans":"不能仅凭分辨值保证。","verification":"细刻度但偏移1 mm就可比粗尺更差。","pitfall":"将小分度与无误差等同。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":2,"primary_section":"2.1","related_sections":[]},"exam":["仪器题先识别量程分度与零点，再读主尺/副尺","单位题把面积体积因子展开后再算","间接测量题写假设及误差来源，不能把累计当无误差"],"quick":["SI与派生单位","仪器选择","读数","零点校正","间接测量"],"exam_evidence":[],"content_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":24,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_2.1","url":"https://openstax.org/books/college-physics-2e/pages/1-2-physical-quantities-and-units","page_or_section":"1-2-physical-quantities-and-units","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":24,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_2.1","url":"https://openstax.org/books/college-physics-2e/pages/1-2-physical-quantities-and-units","page_or_section":"1-2-physical-quantities-and-units","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"仪器题先识别量程分度与零点，再读主尺/副尺","method":"总量除张数并说明限制。","principle":"总厚度近似各张厚度之和。","worked_example_index":2,"verification":"100×0.100=10.0 mm。","pitfall":"认为累计后所有系统偏差都消失。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“以SI单位和操作定义表达测量”的抽样复核：1 m³=10⁶ cm³，反向换回250 cm³。；若出现“只乘10⁻²。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e1","review_module":5,"feedback":"目标“由仪器结构选择读数与校正方法”的抽样复核：真值加偏移为12.14，与原读数相合。；若出现“正零偏反而加上。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"将小分度与无误差等同。","correction":"不能仅凭分辨值保证。","verification":"细刻度但偏移1 mm就可比粗尺更差。"}],"illustration_spec":{"title":"卡尺读数与有符号零点校正","objects":["主尺","游标","零点对照","面积体积单位框"],"relations":["指定0.02 mm分度","第7格确实重合","正零偏减去"],"labels":["12 mm","第7格","0.02 mm","读数12.14 mm","校正12.10 mm"],"format":"SVG","priority":"P0","reuse":"无完整匹配；精确刻度必须确定性绘图","english":"Construct a mathematically consistent vernier with 0.02 mm least count, main-scale reading 12 mm and seventh matching division. Show a positive 0.04 mm zero offset and corrected result 12.10 mm. Do not improvise incompatible scale spacing."}},"2.2":{"subject":"物理","subject_code":"physics","chapter_id":2,"section_id":"2.2","goals":["区分偏差来源与不确定性表达","按运算与测量限制报告有效数字"],"prerequisites":["四则运算","测量与分辨率"],"flow":["系统与随机","绝对与相对","有效数字","运算舍入","传播假设"],"concept_relation":"系统与随机；绝对与相对；有效数字；运算舍入；传播假设","deep":["有效数字用于避免报告超出测量或输入支持的精度。非零数字通常有效，夹在有效数字之间的零有效，小数前只定位的零不有效；末尾零在没有明确记法时可能有歧义，科学记数法可以把保留位数说清。","加减运算通常按最粗小数位限制结果，乘除通常按输入中最少有效数字位数限制；这些是常用报告约定，不替代更完整的不确定性分析。准确的计数和定义换算因子不应不必要限制有效数字。","中间步骤保留保护位，最后一次舍入可减少累积舍入偏差。计算器显示很多位不表示测量已具有同样精度；报告到多少位应根据输入和测量方法，而不是按屏幕长度。","若题目要求估计合成不确定性，要使用题目指定规则。简单最大界限近似下，加减的绝对界限相加，乘除的相对界限近似相加；独立随机量的统计合成规则不同，不能在未说明假设时把所有规则混为一谈。"],"derive":["相对不确定性r=Δx/|x|；百分比为100r%。","例：x=(20.0±0.2) cm，r=0.2/20.0=1%。","小误差最大界限近似：z=xy或x/y时Δz/|z|≈Δx/|x|+Δy/|y|；这不是无条件适用的统计标准差公式。"],"examples":[{"q":"长度(50.0±0.5) cm的相对不确定性是多少？","given":"按题给绝对范围。","analysis":"比值单位相消。","method":"Δx/|x|。","principle":"相对指标比较误差占量值比例。","steps":["0.5/50.0=0.01。","化成百分比为1%。"],"ans":"1%。","verification":"50.0的1%为0.5 cm。","pitfall":"把0.5 cm直接写0.5%。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":2,"primary_section":"2.2","related_sections":[]},{"q":"计算12.35 cm+0.8 cm，应怎样报告？","given":"分别精确到0.01 cm与0.1 cm。","analysis":"加法限制看小数位。","method":"先求和再留最粗位。","principle":"小数位反映可支持的绝对位精度。","steps":["原和13.15 cm。","按0.1 cm报告为13.2 cm。"],"ans":"13.2 cm。","verification":"0.8本身未给百分位，不能宣称和到百分位。","pitfall":"按有效数字位数最少只保留一位成10 cm。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":2,"primary_section":"2.2","related_sections":[]},{"q":"边长a=(10.0±0.1) cm、b=(20.0±0.2) cm，用最大界限小误差近似求面积与绝对不确定性。","given":"正值，按题指定相对界限相加。","analysis":"先算面积，再算相对界限。","method":"A=ab，ΔA/A≈Δa/a+Δb/b。","principle":"一阶传播忽略小量乘积。","steps":["A=200 cm²，相对界限约1%+1%=2%。","ΔA≈200×0.02=4 cm²。"],"ans":"约(200±4) cm²。","verification":"精确端点9.9×19.8=196.02、10.1×20.2=204.02，与±4近似相合。","pitfall":"直接把0.1+0.2作为面积单位误差。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":2,"primary_section":"2.2","related_sections":[]}],"practice":[{"q":"0.00450有几位有效数字？","given":"小数记法明确。","analysis":"前导零与末尾零角色不同。","method":"从首个非零位数到末位。","principle":"定位零不计，保留的小数末零计。","steps":["首个非零为4。","4、5、0共3位。"],"ans":"3位。","verification":"可写4.50×10⁻³。","pitfall":"把所有零都忽略或都计入。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":2,"primary_section":"2.2","related_sections":[]},{"q":"2.4 m×3.12 m按常用规则报告面积。","given":"测量输入2位与3位有效数字。","analysis":"乘法按最少有效数字。","method":"先保留中间值再舍入。","principle":"乘积不应超过输入支持精度。","steps":["2.4×3.12=7.488 m²。","保留2位为7.5 m²。"],"ans":"7.5 m²。","verification":"处于7.488附近，单位面积。","pitfall":"按小数位规则保留到百分位。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":2,"primary_section":"2.2","related_sections":[]},{"q":"一把尺所有读数都多1 mm，多测几次能消掉吗？","given":"共同零偏。","analysis":"系统与随机影响需不同处理。","method":"校准零点并修正记录。","principle":"常量偏移的平均仍同偏移。","steps":["重复读数平均仍多1 mm。","需识别校准，且修正后仍有其他不确定性。"],"ans":"不能靠平均消除。","verification":"xᵢ=x真+1 mm时平均仍x真+1 mm。","pitfall":"只要次数多就准确。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":2,"primary_section":"2.2","related_sections":[]},{"q":"两次独立长度量按题给最大界限：A=20.0±0.2 cm，B=5.0±0.1 cm，求A−B的界限估计与相对值。","given":"使用界限相加规则，不用统计平方和。","analysis":"减法数值相减，不确定性界限仍相加。","method":"z=A−B，Δz=ΔA+ΔB。","principle":"最不利方向误差可相反。","steps":["z=15.0 cm；Δz=0.3 cm。","相对0.3/15.0=2%。"],"ans":"(15.0±0.3) cm，约2%。","verification":"最大差20.2−4.9=15.3，最小19.8−5.1=14.7。","pitfall":"把不确定性也作0.2−0.1。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":2,"primary_section":"2.2","related_sections":[]}],"quiz":{"q":"计算器给ρ=2.7182818 g/cm³，输入只到3位有效数字，能照抄全部位吗？","given":"未给更高精度测量。","analysis":"显示位不等于有效位。","method":"按输入与题设精度舍入。","principle":"结果精度受数据约束。","steps":["保留3位得2.72 g/cm³。","中间可留保护位，但报告不能把额外位冒充测量能力。"],"ans":"应约2.72 g/cm³。","verification":"第4位为8使第三位进1。","pitfall":"以计算器显示决定精度。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":2,"primary_section":"2.2","related_sections":[]},"exam":["误差题先辨单位、相对指标与给定传播规则","有效数字题加减看位、乘除看位数，中间不反复舍入","“更准确”比较需核校准与不确定性，不能只比小数多"],"quick":["系统与随机","绝对与相对","有效数字","运算舍入","传播假设"],"exam_evidence":[],"content_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":31,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_2.2","url":"https://openstax.org/books/college-physics-2e/pages/1-3-accuracy-precision-and-significant-figures","page_or_section":"1-3-accuracy-precision-and-significant-figures","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":31,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_2.2","url":"https://openstax.org/books/college-physics-2e/pages/1-3-accuracy-precision-and-significant-figures","page_or_section":"1-3-accuracy-precision-and-significant-figures","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"误差题先辨单位、相对指标与给定传播规则","method":"A=ab，ΔA/A≈Δa/a+Δb/b。","principle":"一阶传播忽略小量乘积。","worked_example_index":2,"verification":"精确端点9.9×19.8=196.02、10.1×20.2=204.02，与±4近似相合。","pitfall":"直接把0.1+0.2作为面积单位误差。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“区分偏差来源与不确定性表达”的抽样复核：50.0的1%为0.5 cm。；若出现“把0.5 cm直接写0.5%。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e1","review_module":5,"feedback":"目标“按运算与测量限制报告有效数字”的抽样复核：0.8本身未给百分位，不能宣称和到百分位。；若出现“按有效数字位数最少只保留一位成10 cm。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"以计算器显示决定精度。","correction":"应约2.72 g/cm³。","verification":"第4位为8使第三位进1。"}],"illustration_spec":{"title":"测量离散、偏移与有效位","objects":["真值参考","两组读数分布","偏移","绝对范围","科学记数法"],"relations":["集中不等于无偏","随机散布与系统偏移可并存","前导零不计有效位"],"labels":["准确性","重复性","Δx","Δx/|x|","4.50×10⁻³"],"format":"SVG","priority":"P1","reuse":"无完全对应图","english":"Show two measurement distributions with independent spread and bias relative to a stated reference. Distinguish absolute uncertainty from relative uncertainty and annotate the three significant figures in 0.00450 without implying an exact universal probability for ± notation."}},"2.3":{"subject":"物理","subject_code":"physics","chapter_id":2,"section_id":"2.3","goals":["规范表示极大极小量并估算","用数量级检查模型结果"],"prerequisites":["十的幂","有效数字"],"flow":["标准记数","幂运算","前缀换算","尺度比较","因素估算"],"concept_relation":"标准记数；幂运算；前缀换算；尺度比较；因素估算","deep":["数量级用于比较数量的尺度，但“以首个十次幂为数量级”与“取最接近的十次幂”是不同约定。题目未说明时应写出所用约定，避免把两种答案差一档当成纯计算错。本节若说“最近十次幂”，按对数距离比较，分界为系数√10。","费米估算把复杂数量拆为可说明的因素，用合理范围先得到尺度。估算不是随意猜数，应写假设、单位和主导不确定因素，例如每户每日用水乘户数可估总需求，入住率和季节变化会改变结果。","数量级检查能识别错用毫秒、千米或平方单位引入的巨大偏差。它不保证精确答案，但可对结果施加约束：若步行速度算得10⁶ m/s，优先回查单位和题意；对非常规情境仍需依据模型而非日常印象否定。","估算报告应与信息质量匹配，不把粗略假设算出的许多位写成真实测量。范围估算常比单一数字更诚实；列出哪项改进最能减少不确定性，能把估算转为可进一步研究的问题。"],"derive":["(a×10ᵐ)(b×10ⁿ)=ab×10ᵐ⁺ⁿ；相除则系数相除、指数相减。","加减必须先同幂：3×10³+2×10²=(3+0.2)×10³=3.2×10³。","最近十次幂的对数分界：a×10ⁿ到10ⁿ和10ⁿ⁺¹等距时log₁₀a=1/2，即a=√10；若用另一约定须注明。"],"examples":[{"q":"把0.000560 m写成科学记数法并保持有效数字。","given":"原值末尾小数零有效。","analysis":"系数需在1到10之间。","method":"移动小数点并补幂。","principle":"量值不变且保留有效位。","steps":["0.000560=5.60×10⁻⁴。","5、6、0为三位有效数字。"],"ans":"5.60×10⁻⁴ m，三位。","verification":"5.60/10000=0.000560。","pitfall":"丢掉末零或把指数写正。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":2,"primary_section":"2.3","related_sections":[]},{"q":"算(6.0×10⁵)/(2.0×10⁻³)，按有效数字报告。","given":"系数均2位。","analysis":"负指数相减应注意括号。","method":"系数相除、指数相减。","principle":"10ᵐ/10ⁿ=10ᵐ⁻ⁿ。","steps":["6.0/2.0=3.0。","5−(−3)=8，得3.0×10⁸。"],"ans":"3.0×10⁸。","verification":"3.0×10⁸乘2.0×10⁻³=6.0×10⁵。","pitfall":"将5−(−3)算成2。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":2,"primary_section":"2.3","related_sections":[]},{"q":"估学校1000人，每人每天饮水约1到2 L，五天需多少饮水？结果应报几位？","given":"只估饮用，不含清洁和烹饪。","analysis":"明确活动与范围边界。","method":"人数×每人量×天数。","principle":"总需求为可加的个体需求近似。","steps":["低端1000×1×5=5000 L。","高端1000×2×5=10000 L。","入住、出勤与天气等会改变假设。"],"ans":"约5×10³至1×10⁴ L，不应报大量精确小数。","verification":"单位人×L/(人·日)×日=L。","pitfall":"把饮用估算当所有生活用水精确值。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":2,"primary_section":"2.3","related_sections":[]}],"practice":[{"q":"3×10⁴+2×10³等于5×10⁷吗？","given":"加法而非乘法。","analysis":"幂规则不可混用。","method":"统一指数。","principle":"同类项相加。","steps":["2×10³=0.2×10⁴。","和为3.2×10⁴。"],"ans":"不是，3.2×10⁴。","verification":"30000+2000=32000。","pitfall":"加法也把指数相加。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":2,"primary_section":"2.3","related_sections":[]},{"q":"2.5 ms是多少s？","given":"milli为10⁻³。","analysis":"单位前缀对应幂次。","method":"2.5×10⁻³。","principle":"换算不改变物理时长。","steps":["1 ms=10⁻³ s。","2.5 ms=0.0025 s。"],"ans":"2.5×10⁻³ s。","verification":"乘1000转回2.5 ms。","pitfall":"把milli与micro混用。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":2,"primary_section":"2.3","related_sections":[]},{"q":"按最近十次幂的对数距离约定，8×10⁴更近10⁴还是10⁵？","given":"明确使用最近十次幂约定。","analysis":"系数与√10比较。","method":"8>√10，取上一级。","principle":"对数中点系数约3.162。","steps":["8大于3.162。","因此离10⁵的对数距离较小。"],"ans":"10⁵。","verification":"80000比100000只差1.25倍，比10000差8倍。","pitfall":"不声明约定导致把首指数4当唯一答案。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":2,"primary_section":"2.3","related_sections":[]},{"q":"一页约500字，约200页，估总字数并说明不宜报100000.00字的理由。","given":"每页字数和页数均粗估。","analysis":"乘法不产生额外测量精度。","method":"分因素估算尺度。","principle":"估计结果精度受假设限制。","steps":["500×200≈1×10⁵字。","插图、空白与排版使实际量偏离，末两位小数无依据。"],"ans":"约10⁵字。","verification":"5×10²乘2×10²=10×10⁴=10⁵。","pitfall":"把计算器整数或小数当真实精度。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":2,"primary_section":"2.3","related_sections":[]}],"quiz":{"q":"算得步行100 m耗时20 s的速度为5×10⁵ m/s，怎样不用重做全题先检查？","given":"常规地面步行与题设距离时间。","analysis":"尺度严重不合理且可直接估比。","method":"100/20近5，再核幂和单位。","principle":"速度=距离/时间，此处同单位。","steps":["10²/(2×10¹)=5×10⁰ m/s。","原结果多10⁵倍，应查指数或单位误用。"],"ans":"应为5 m/s，原结果数量级错误。","verification":"5×20=100 m。","pitfall":"发现离谱只说不合理却不定位幂次。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":2,"primary_section":"2.3","related_sections":[]},"exam":["科学记数先标准化系数，运算后再标准化","数量级题注明约定，用倍数或对数比较而非随意取整","估算题列边界、因素、单位与范围，避免虚假精度"],"quick":["标准记数","幂运算","前缀换算","尺度比较","因素估算"],"exam_evidence":[],"content_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":34,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_2.3","url":"https://openstax.org/books/college-physics-2e/pages/1-4-approximation","page_or_section":"1-4-approximation","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":34,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_2.3","url":"https://openstax.org/books/college-physics-2e/pages/1-4-approximation","page_or_section":"1-4-approximation","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"科学记数先标准化系数，运算后再标准化","method":"人数×每人量×天数。","principle":"总需求为可加的个体需求近似。","worked_example_index":2,"verification":"单位人×L/(人·日)×日=L。","pitfall":"把饮用估算当所有生活用水精确值。"},"diagnostics":[{"goal_index":0,"question_ref":"e2","review_module":4,"feedback":"目标“规范表示极大极小量并估算”的抽样复核：单位人×L/(人·日)×日=L。；若出现“把饮用估算当所有生活用水精确值。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"q","review_module":5,"feedback":"目标“用数量级检查模型结果”的抽样复核：5×20=100 m。；若出现“发现离谱只说不合理却不定位幂次。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"发现离谱只说不合理却不定位幂次。","correction":"应为5 m/s，原结果数量级错误。","verification":"5×20=100 m。"}],"illustration_spec":{"title":"科学记数与对数尺度","objects":["十进制小数","标准系数","十次幂数轴","√10分界"],"relations":["系数1至10","对数轴等距表示相同倍数","数量级约定显式标注"],"labels":["10⁻⁴","10⁰","10⁴","5.60×10⁻⁴","最近十次幂"],"format":"SVG","priority":"P1","reuse":"需确定性数轴，无需AI辅助画","english":"Create a labelled logarithmic powers-of-ten scale and illustrate 0.000560=5.60×10^-4. If showing nearest power of ten, explicitly mark the multiplicative midpoint sqrt(10), not an arithmetic midpoint."}},"2.4":{"subject":"物理","subject_code":"physics","chapter_id":2,"section_id":"2.4","goals":["由图象解释斜率截距及面积","辨认变量关系和适用区间"],"prerequisites":["坐标系与斜率","单位与比例"],"flow":["轴与刻度","斜率","截距","有向面积","变量变换"],"concept_relation":"轴与刻度；斜率；截距；有向面积；变量变换","deep":["曲线在某点的切线斜率表示局部变化率，割线表示区间平均变化率。两者可不同，不能从一段平均值推出每时刻恒定。折线拐点处是否有唯一切线还需按模型处理。","图线下有向面积的单位为两轴单位的乘积；面积代表什么须从所画量关系推导。速度—时间图面积给位移，速率—时间图面积给路程，力—位移图面积在相关力分量与运动关系满足条件时给功；不能说任何图面积都是能量。","线性化把非线性关系转为适当变量间的直线，例如y=kx²可画y对x²，而非强行把y对x画直。新横轴单位也须平方。变量变换可以便于求参数，但不会自动证明原模型在所有范围成立。","数据处理应同时展示适当点、趋势与不确定性；读图精度受刻度和图线宽度限制。图看起来没有明显弯曲不能单独保证严格线性，报告应与测量范围和分辨能力相称。"],"derive":["斜率m=Δy/Δx，单位[y]/[x]；截距b在y=mx+b中与y同单位。","v-t图：Δx=图线与时间轴之间的有向面积；负速度部分给负位移。","若y=kx²，令X=x²，则y=kX；X单位为[x]²，斜率k单位[y]/[x]²。"],"examples":[{"q":"x-t直线过(1 s,3 m)和(5 s,11 m)，斜率与截距分别是什么？","given":"横轴t、纵轴x，直线模型。","analysis":"斜率给速度，截距给t=0的位置外推。","method":"两点求m再代回。","principle":"x=vt+x₀。","steps":["v=(11−3)/(5−1)=2 m/s。","3=2×1+x₀，得x₀=1 m。"],"ans":"斜率2 m/s，截距1 m。","verification":"t=5时x=2×5+1=11 m。","pitfall":"直接11/5忽略非零初位置。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":2,"primary_section":"2.4","related_sections":[]},{"q":"v-t图0至2 s为+3 m/s，2至4 s为−1 m/s，求位移和路程。","given":"分段恒速，转向时刻的理想突变按题处理。","analysis":"有向面积与绝对面积不同。","method":"分别加vΔt和|v|Δt。","principle":"位移有方向，路程不抵消。","steps":["位移=3×2−1×2=4 m。","路程=3×2+1×2=8 m。"],"ans":"位移+4 m，路程8 m。","verification":"从0到6 m再回到4 m，总走8 m。","pitfall":"将负区域删去或把路程也相消。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":2,"primary_section":"2.4","related_sections":[]},{"q":"关系y=kx²，x单位m、y单位N，作y对x²图得到斜率5，应给k什么单位？","given":"横轴已换为x²。","analysis":"新横轴单位平方。","method":"斜率单位N/m²。","principle":"斜率=纵量/横量。","steps":["x²单位m²。","k=5 N/m²，且y随x²正比而非随x正比。"],"ans":"5 N/m²。","verification":"k x²单位(N/m²)m²=N。","pitfall":"沿用原x单位把k写N/m。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":2,"primary_section":"2.4","related_sections":[]}],"practice":[{"q":"同一x-t图拉宽纸张，直线视觉角度减小，速度会变吗？","given":"坐标刻度数值及物理数据不变。","analysis":"斜率应由数值比求而非视觉角。","method":"比较Δx/Δt。","principle":"绘图长宽不改变物理数据。","steps":["同两点坐标差不变。","速度比值保持，只有画面倾角改变。"],"ans":"不会。","verification":"单位比例尺变化使角度不能直接当m/s。","pitfall":"以角度大小无条件比较不同刻度图。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":2,"primary_section":"2.4","related_sections":[]},{"q":"F-x图恒定沿位移方向力4 N，位移3 m，面积及含义？","given":"力为位移方向分量。","analysis":"轴乘积为功单位。","method":"矩形面积FΔx。","principle":"恒力功=FΔx。","steps":["4×3=12 N·m。","1 N·m=1 J，此处表示功12 J。"],"ans":"12 J功。","verification":"与恒力公式相同。","pitfall":"不看轴变量就把所有面积说成速度。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":2,"primary_section":"2.4","related_sections":[]},{"q":"y=3x+2图象是直线，y与x成正比吗？","given":"范围中模型给定。","analysis":"非零截距破坏固定比值。","method":"求y/x或看原点。","principle":"正比需y=kx。","steps":["x=1时y/x=5，x=2时为4。","图线截距2，不通过原点。"],"ans":"不成正比。","verification":"不同x比值不恒定。","pitfall":"线性与正比混用。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":2,"primary_section":"2.4","related_sections":[]},{"q":"速度从0到4 s线性由2升到6 m/s，求加速度与位移并用另一方法核查。","given":"恒加速度阶段。","analysis":"斜率和面积对应不同物理量。","method":"斜率求a，梯形面积求Δx。","principle":"a=Δv/Δt，位移为v-t面积。","steps":["a=(6−2)/4=1 m/s²。","Δx=(2+6)×4/2=16 m。"],"ans":"1 m/s²与16 m。","verification":"v₀t+at²/2=8+8=16 m。","pitfall":"用斜率作位移或漏初速度面积。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":2,"primary_section":"2.4","related_sections":[]}],"quiz":{"q":"某曲线两点割线斜率为2，能否说两点间每处切线斜率都为2？","given":"只给区间平均变化率。","analysis":"平均与局部不同。","method":"考虑非直线反例。","principle":"切线描述局部，割线描述两点差。","steps":["曲线可在不同位置更陡或更平。","只有额外证据表明该段直线等条件，才能说局部斜率恒定。"],"ans":"不能。","verification":"总平均相同可对应多种局部变化。","pitfall":"把区间平均当处处瞬时值。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":2,"primary_section":"2.4","related_sections":[]},"exam":["读图题先圈轴量、单位、刻度和原点，再解释斜率或面积","拟合题从拟合线取合适远点，非任意散点","线性化题重写变量及其单位，物理解释随轴改变"],"quick":["轴与刻度","斜率","截距","有向面积","变量变换"],"exam_evidence":[],"content_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":37,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_2.4","url":"https://openstax.org/books/college-physics-2e/pages/2-8-graphical-analysis-of-one-dimensional-motion","page_or_section":"2-8-graphical-analysis-of-one-dimensional-motion","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":37,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_2.4","url":"https://openstax.org/books/college-physics-2e/pages/2-8-graphical-analysis-of-one-dimensional-motion","page_or_section":"2-8-graphical-analysis-of-one-dimensional-motion","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"读图题先圈轴量、单位、刻度和原点，再解释斜率或面积","method":"斜率单位N/m²。","principle":"斜率=纵量/横量。","worked_example_index":2,"verification":"k x²单位(N/m²)m²=N。","pitfall":"沿用原x单位把k写N/m。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“由图象解释斜率截距及面积”的抽样复核：t=5时x=2×5+1=11 m。；若出现“直接11/5忽略非零初位置。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“辨认变量关系和适用区间”的抽样复核：k x²单位(N/m²)m²=N。；若出现“沿用原x单位把k写N/m。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"把区间平均当处处瞬时值。","correction":"不能。","verification":"总平均相同可对应多种局部变化。"}],"illustration_spec":{"title":"图象的斜率、截距与有向面积","objects":["x-t直线","v-t正负矩形","y对x²直线"],"relations":["x-t过(1,3)(5,11)","v-t面积+6和−2给+4","路程取绝对面积8"],"labels":["t/s","x/m","v/(m/s)","斜率2 m/s","截距1 m","Δx=4 m"],"format":"SVG","priority":"P0","reuse":"V22运动图可作补充，需避免重复并保持数值一致","english":"Draw three exact coordinate panels: x=2t+1 through (1,3) and (5,11); v=3 for 0–2 s and v=-1 for 2–4 s with signed areas +6 and -2 m; a separate y versus x-squared linearization with squared horizontal units."}}},"物理5":{"5.1":{"subject":"物理","subject_code":"physics","chapter_id":5,"section_id":"5.1","goals":["由平衡条件建立分量方程","用受力图检查约束与解的可行性"],"prerequisites":["向量分解","牛顿定律"],"flow":["选对象","画外力","分量平衡","约束上限","可行性核查"],"concept_relation":"选对象；画外力；分量平衡；约束上限；可行性核查","deep":["只有三力且平衡时，矢量首尾相接可形成闭合三角形。用几何求张力需确认角是力方向之间还是图中补角；两根对称绳的夹角越大，竖直分量比例越小，所需张力可能增大，而不是总是各承受一半重量。","静摩擦是在接触条件允许范围内按维持相对静止的需要取值，0≤|fₛ|≤μₛN；仅在临界滑动时才达到最大值。法向力取决垂直于接触面的动力学及其他外力，不应一律等于mg。","绳通常只能拉，接触面通常只能推。求得负张力或负法向力，可能意味着所假设约束状态不成立，须回到物理情境判断松绳或失去接触。代数方程有解不保证模型可实现。","做平衡题应先计算所需摩擦或拉力，再检查上限和约束。当外力改变到临界值，平衡可能失效；要清楚区分“求维持平衡所需力”与“给定条件是否足以维持平衡”这两类问题。"],"derive":["平面共点力平衡：ΣFₓ=0，ΣFᵧ=0。","两对称绳各与竖直夹角θ，2T cosθ=mg，故T=mg/(2 cosθ)，需cosθ>0且绳能承受。","静摩擦先求所需f，再检验|f|≤μₛN；等号只描述临界情况。"],"examples":[{"q":"质量4 kg物体在水平面受水平拉力8 N静止，g=10 m/s²，求摩擦和支持力。","given":"无其他竖直力，静止。","analysis":"平衡分量分别求。","method":"水平与竖直列ΣF=0。","principle":"加速度零，接触力满足约束。","steps":["水平方向摩擦8 N，反向于拉力。","竖直N=mg=40 N。"],"ans":"f=8 N、N=40 N。","verification":"两方向合力分别0；是否可维持还需摩擦上限≥8 N。","pitfall":"未给μ就说无法求实际静摩擦。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":5,"primary_section":"5.1","related_sections":[]},{"q":"重100 N物体由两根对称绳吊住，各与竖直60°，各张力多少？","given":"绳轻，结点平衡。","analysis":"每根竖直分量只占T的一半。","method":"水平抵消、竖直相加。","principle":"2T cos60°=100。","steps":["cos60°=0.5。","T=100/(2×0.5)=100 N。"],"ans":"各100 N。","verification":"两根各向上分量50 N，总100 N。","pitfall":"直接各50 N忽略方向。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":5,"primary_section":"5.1","related_sections":[]},{"q":"质量5 kg物体在水平面，μₛ=0.4，受水平力25 N，g=10，能否平衡？","given":"无其他竖直力，讨论静摩擦上限。","analysis":"先求所需再比最大。","method":"f需=25，f最大=μₛmg。","principle":"静摩擦只能在允许范围内调节。","steps":["N=50 N，最大20 N。","所需25>20，静止平衡无法维持。"],"ans":"不能按静止模型平衡。","verification":"即使取最大摩擦仍有至少5 N合力；运动后摩擦须另用条件。","pitfall":"把静摩擦无条件设为25 N。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":5,"primary_section":"5.1","related_sections":[]}],"practice":[{"q":"物体瞬时速度为零就必平衡吗？","given":"仅知某一时刻v=0。","analysis":"速度与加速度不同。","method":"找反例并看合力。","principle":"平衡需加速度零。","steps":["竖直上抛最高点v=0。","重力仍向下，加速度不为零。"],"ans":"不必。","verification":"其下一时刻向下运动说明速度在变。","pitfall":"把静止瞬间等同持续静止。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":5,"primary_section":"5.1","related_sections":[]},{"q":"两个力大小都10 N，夹角120°，合力大小？能仅凭大小相等说平衡吗？","given":"只受这两个力。","analysis":"方向决定是否抵消。","method":"用余弦关系或分解。","principle":"R²=F²+F²+2F²cos120°。","steps":["R²=100+100−100=100。","R=10 N，不为0。"],"ans":"10 N，不平衡。","verification":"只有相反方向180°才可两力抵消。","pitfall":"相等就当作用反作用。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":5,"primary_section":"5.1","related_sections":[]},{"q":"重量60 N由对称绳吊住，各与竖直30°，各T？","given":"结点平衡，理想绳。","analysis":"用竖直分量。","method":"T=60/(2cos30°)。","principle":"水平分量相消。","steps":["cos30°=√3/2。","T=60/√3=20√3≈34.6 N。"],"ans":"约34.6 N。","verification":"2×34.6×0.866≈60 N。","pitfall":"用sin30°代替与竖直夹角的cos。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":5,"primary_section":"5.1","related_sections":[]},{"q":"4 kg物体受水平拉力10 N、向上拉力6 N，g=10，μₛ=0.3，能静止吗？","given":"物体保持接触，竖直平衡假设。","analysis":"上拉减小N也减小摩擦上限。","method":"先竖直求N，再查水平。","principle":"N+6=mg，|f|≤μₛN。","steps":["N=40−6=34 N，f最大10.2 N。","所需f=10 N≤10.2 N，可静止，实际f=10 N。"],"ans":"可以，N=34 N、静摩擦10 N。","verification":"竖直34+6−40=0，水平10−10=0。","pitfall":"仍把N写40或把摩擦强设10.2。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":5,"primary_section":"5.1","related_sections":[]}],"quiz":{"q":"受力图把物体对桌面的压力与桌面对物体支持力都画在物体上并抵消，错在哪里？","given":"研究对象为物体。","analysis":"作用反作用所属对象不同。","method":"逐力问施力与受力物体。","principle":"受力图只包括作用于该对象的力。","steps":["桌面对物体支持力应保留。","物体对桌面压力属于桌面的受力图，不可拿来抵消。"],"ans":"混入了研究对象对外施加的力。","verification":"若抵消支持力，重力将无法与实际静止相符。","pitfall":"把相互作用一对当同体平衡力。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":5,"primary_section":"5.1","related_sections":[]},"exam":["先选对象画外力，再分解列平衡，不能先猜μmg","绳角题写清角从竖直或水平量起，验每根竖直分量","求解后检查N≥0、T≥0和摩擦上限，说明是否可实现"],"quick":["选对象","画外力","分量平衡","约束上限","可行性核查"],"exam_evidence":[],"content_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":146,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_5.1","url":"https://openstax.org/books/college-physics-2e/pages/9-1-the-first-condition-for-equilibrium","page_or_section":"9-1-the-first-condition-for-equilibrium","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":146,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_5.1","url":"https://openstax.org/books/college-physics-2e/pages/9-1-the-first-condition-for-equilibrium","page_or_section":"9-1-the-first-condition-for-equilibrium","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"先选对象画外力，再分解列平衡，不能先猜μmg","method":"f需=25，f最大=μₛmg。","principle":"静摩擦只能在允许范围内调节。","worked_example_index":2,"verification":"即使取最大摩擦仍有至少5 N合力；运动后摩擦须另用条件。","pitfall":"把静摩擦无条件设为25 N。"},"diagnostics":[{"goal_index":0,"question_ref":"e1","review_module":4,"feedback":"目标“由平衡条件建立分量方程”的抽样复核：两根各向上分量50 N，总100 N。；若出现“直接各50 N忽略方向。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“用受力图检查约束与解的可行性”的抽样复核：即使取最大摩擦仍有至少5 N合力；运动后摩擦须另用条件。；若出现“把静摩擦无条件设为25 N。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"把相互作用一对当同体平衡力。","correction":"混入了研究对象对外施加的力。","verification":"若抵消支持力，重力将无法与实际静止相符。"}],"illustration_spec":{"title":"对称悬吊与静摩擦约束","objects":["结点","两根对称绳","重量","张力分量","水平接触物体"],"relations":["θ从竖直量","2Tcosθ=mg","静摩擦小于等于上限而非恒取上限"],"labels":["θ","T","Tcosθ","mg","|fₛ|≤μₛN"],"format":"SVG","priority":"P0","reuse":"V22向量图可局部参考，不替代本题受力几何","english":"Draw a symmetric suspension with each rope angle measured from the vertical, showing 2T cos(theta)=mg. In a separate horizontal-contact free-body diagram, distinguish required static friction from its maximum and do not include reaction forces acting on other bodies."}},"5.2":{"subject":"物理","subject_code":"physics","chapter_id":5,"section_id":"5.2","goals":["用垂直力臂计算力矩","联合平动转动条件求平面刚体平衡"],"prerequisites":["共点力平衡","三角函数"],"flow":["选矩心","画作用线","定垂距和符号","联合平衡","查支承约束"],"concept_relation":"选矩心；画作用线；定垂距和符号；联合平衡；查支承约束","deep":["选支点是求解策略，不改变物理事实。取未知支承力作用点为矩心，可使该力矩为零并减少未知量；不是忽略该力，它仍必须进入合力方程。若合力已为零，平衡时绕任一点的合力矩也为零。","平面刚体静力平衡常用ΣFₓ=0、ΣFᵧ=0、Στ=0三个独立条件。未知力多于可提供的独立方程时，可能需要材料变形等额外信息，不能任意再选几个矩心假装得到更多独立约束。","重力在均匀杆上可视为作用于中点，但“均匀”是质量分布条件。非均匀物体的重心不能无依据取几何中心；复杂负载可把各重力按力矩等效求重心位置。支持点是否能拉、支承是否会脱离也需检查。","平衡问题的答案要同时满足力与矩，并符合支承方向。只用矩方程求一个力后，应代回竖直和水平方程；若某支点反力为负而该支承不能拉，说明所假设双支承接触状态失效。"],"derive":["τ=Fℓ=Fr sinθ，其中ℓ为支点到作用线的垂直距离。","平面静力平衡：ΣFₓ=0，ΣFᵧ=0，Στ_O=0。","力偶大小相等反向平行，间距d时合力0而合力矩Fd；关于不同点力偶矩相同。"],"examples":[{"q":"水平杆绕左端，右端距支点0.5 m，施向下10 N，力矩多大、什么方向？","given":"力与杆垂直。","analysis":"力臂正好为0.5 m。","method":"τ=Fℓ并判转向。","principle":"绕支点转动趋势。","steps":["τ=10×0.5=5 N·m。","右端向下使杆顺时针转动。"],"ans":"5 N·m，顺时针。","verification":"若力作用线通过支点则应零，此处垂距非零。","pitfall":"只写5 J或把方向漏掉。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":5,"primary_section":"5.2","related_sections":[]},{"q":"长2 m均匀杆重40 N，两端支承，中点另挂20 N，支反力各多少？","given":"载荷均在中点，无其他竖直力。","analysis":"对称可猜但需力矩验证。","method":"绕左端取矩再列竖直力。","principle":"平衡要求合力与合矩都零。","steps":["右支力R_B满足2R_B=40×1+20×1，得30 N。","R_A+R_B=60，故R_A=30 N。"],"ans":"两端各30 N向上。","verification":"绕中点两支力矩抵消，总向上60 N等于重力60 N。","pitfall":"只令合力零便认为任何分配都行。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":5,"primary_section":"5.2","related_sections":[]},{"q":"杆长0.8 m，末端受50 N，与杆夹角30°，求绕另一端力矩，比较误用全长力臂。","given":"力方向与位矢夹角30°。","analysis":"有效垂距为r sinθ。","method":"τ=Fr sinθ。","principle":"力矩取垂直分量。","steps":["ℓ=0.8 sin30°=0.4 m。","τ=50×0.4=20 N·m，方向须由图给；题只求大小。"],"ans":"20 N·m。","verification":"等价垂直分力25 N乘0.8 m也得20。","pitfall":"用50×0.8=40而漏sin。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":5,"primary_section":"5.2","related_sections":[]}],"practice":[{"q":"力的作用线通过支点，作用点离支点1 m，F=100 N，力矩？","given":"作用线穿过支点。","analysis":"力臂是到作用线垂距。","method":"ℓ=0。","principle":"τ=Fℓ。","steps":["穿过意味着垂距0。","100×0=0。"],"ans":"0。","verification":"沿杆推不能产生该轴转动趋势。","pitfall":"直接把支点到作用点1 m当力臂。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":5,"primary_section":"5.2","related_sections":[]},{"q":"两反向平行力各8 N，作用线距0.3 m，合力与力偶矩？","given":"同一平面。","analysis":"合力抵消但转动不抵消。","method":"分别求矢量和与Fd。","principle":"力偶矩依两作用线间距。","steps":["合力0。","矩大小8×0.3=2.4 N·m。"],"ans":"0与2.4 N·m。","verification":"两力关于任一合适点矩相加为同值。","pitfall":"合力零就宣称完全平衡。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":5,"primary_section":"5.2","related_sections":[]},{"q":"一根2 m均匀杆重20 N，左端支点，右端竖直绳拉住，杆水平，绳张力？","given":"杆重在中点，静止。","analysis":"取支点矩消去支点反力。","method":"2T=20×1。","principle":"合矩零。","steps":["T=10 N。","竖直支反力R=20−10=10 N。"],"ans":"T=10 N。","verification":"右端向上矩20与重力向下矩20抵消。","pitfall":"把张力直接设等于杆重。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":5,"primary_section":"5.2","related_sections":[]},{"q":"3 m杆重忽略，左端支承A、距A 2 m处支承B，距A 3 m处挂60 N，按静力方程求反力并判断可行性。","given":"两支承只能向上推。","analysis":"悬出负载可能使A需要向下拉。","method":"绕A取矩，后验支承约束。","principle":"合矩与合力条件及单向接触。","steps":["2R_B=60×3，R_B=90 N。","R_A=60−90=−30 N，要求A向下拉，与仅向上支承不符。"],"ans":"该双接触平衡不可实现，需额外固定或会失去A接触。","verification":"若代入力方程可平衡，但违反物理支承方向。","pitfall":"负反力取绝对值30后继续说平衡。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":5,"primary_section":"5.2","related_sections":[]}],"quiz":{"q":"为何绕某未知支反力作用点取矩后，该力仍要出现在竖直合力方程？","given":"该力关于所选点力臂零。","analysis":"零力矩不等于力不存在。","method":"区分平动作用与绕点转动作用。","principle":"合力与合矩是不同条件。","steps":["取矩时该项因ℓ=0消去。","它仍参与总向上向下力平衡，须用合力方程求或检查。"],"ans":"因为它只是关于该点矩为零。","verification":"单支点仍能提供承重反力，即使对该点无矩。","pitfall":"把数学消元当作物理删除。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":5,"primary_section":"5.2","related_sections":[]},"exam":["矩题先画作用线和垂距，不能只找杆长","选未知力作用点取矩减少未知，之后代回合力","刚体题求完检查支承可推可拉及临界脱离，不只看方程数"],"quick":["选矩心","画作用线","定垂距和符号","联合平衡","查支承约束"],"exam_evidence":[],"content_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":150,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_5.2","url":"https://openstax.org/books/college-physics-2e/pages/9-2-the-second-condition-for-equilibrium","page_or_section":"9-2-the-second-condition-for-equilibrium","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":150,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_5.2","url":"https://openstax.org/books/college-physics-2e/pages/9-2-the-second-condition-for-equilibrium","page_or_section":"9-2-the-second-condition-for-equilibrium","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"矩题先画作用线和垂距，不能只找杆长","method":"τ=Fr sinθ。","principle":"力矩取垂直分量。","worked_example_index":2,"verification":"等价垂直分力25 N乘0.8 m也得20。","pitfall":"用50×0.8=40而漏sin。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“用垂直力臂计算力矩”的抽样复核：若力作用线通过支点则应零，此处垂距非零。；若出现“只写5 J或把方向漏掉。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e1","review_module":5,"feedback":"目标“联合平动转动条件求平面刚体平衡”的抽样复核：绕中点两支力矩抵消，总向上60 N等于重力60 N。；若出现“只令合力零便认为任何分配都行。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"把数学消元当作物理删除。","correction":"因为它只是关于该点矩为零。","verification":"单支点仍能提供承重反力，即使对该点无矩。"}],"illustration_spec":{"title":"力臂与平面杆的平衡","objects":["支点O","r=0.8 m杆","50 N斜力","垂直力臂0.4 m","双支承杆"],"relations":["夹角30°","ℓ=r sinθ","力臂画到延长作用线的垂线","反力方向符合约束"],"labels":["O","r","θ=30°","ℓ=0.4 m","τ=20 N·m"],"format":"SVG","priority":"P0","reuse":"现有力图不能代替准确垂距图","english":"Draw a 0.8 m position vector and a 50 N force at 30 degrees to it. Construct the perpendicular distance from pivot O to the force line as 0.4 m, giving torque 20 N m. Distinguish the full rod length from the moment arm."}},"5.3":{"subject":"物理","subject_code":"physics","chapter_id":5,"section_id":"5.3","goals":["求平行力的合力与作用线","用力矩确定重心并判断稳定性"],"prerequisites":["力矩平衡","加权平均"],"flow":["代数合力","矩等效","作用线","质量重心","支承与稳定"],"concept_relation":"代数合力；矩等效；作用线；质量重心；支承与稳定","deep":["在近似均匀重力场内，物体各部分的重力形成平行力系，可用总重力作用于重心来等效其转动作用。由x_G=Σmᵢxᵢ/Σmᵢ可求离散质量的重心坐标；负坐标表示相对原点位置，不是负质量。","均匀规则物体重心常在对称中心，条件是质量分布也对称。挖孔、附加负载或材料密度改变会移动重心；几何中心不能无条件当作重心，重心也可以在物体材料之外，如环的中心。","稳定性取决于小扰动后重力矩的趋势或势能变化。支撑面上的物体在相应条件下，重力作用线落在支撑范围内才可由非负支承力维持；重心低、底面宽往往提高抗倾倒能力，但还需考虑外力、摩擦与动态效应。","求解后要检查合力的矩与原力系一致，坐标和距离的单位一致。对零合力情况先辨是否仍有力偶，不把ΣF=0自动解释成任何点都可任意安放一个“零合力”而忽略转动。"],"derive":["平行力沿共同方向取正：R=ΣFᵢ；当R≠0时，x_R=ΣFᵢxᵢ/R，由力矩等效确定。","均匀重力场：x_G=Σmᵢxᵢ/Σmᵢ；g相同可在分子分母相消。","R=0而ΣFᵢxᵢ≠0时为非零力偶，不能用一个单力等效。"],"examples":[{"q":"两同向向下力10 N与30 N，位于x=0和x=2 m，求合力及位置。","given":"平行力，原点在小力线上。","analysis":"合力与矩都需等效。","method":"R求和，x_R求加权。","principle":"R x_R=ΣFᵢxᵢ。","steps":["R=40 N向下。","x_R=(10×0+30×2)/40=1.5 m。"],"ans":"40 N向下，x=1.5 m。","verification":"合力矩40×1.5=60 N·m，原矩30×2=60；位置靠30 N。","pitfall":"总力对了却把位置取1 m。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":5,"primary_section":"5.3","related_sections":[]},{"q":"x=0处向下30 N，x=2 m处向上10 N，取向下为正，求等效合力位置。","given":"反向平行力，R不为零。","analysis":"位置可能在线外。","method":"带符号求R和矩。","principle":"同一符号约定下R x_R=ΣFᵢxᵢ。","steps":["R=30−10=20 N向下。","x_R=(30×0−10×2)/20=−1 m。"],"ans":"20 N向下，作用线x=−1 m。","verification":"等效矩20×(−1)=−20与原−10×2一致。","pitfall":"认为位置必须在0至2 m内。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":5,"primary_section":"5.3","related_sections":[]},{"q":"2 kg位于x=0，3 kg位于x=4 m，支点放何处可使无质量杆平衡？","given":"g均匀，忽略杆重。","analysis":"重心按质量加权。","method":"x_G=Σmx/Σm。","principle":"各重力矩等效于总重力在重心。","steps":["x_G=(2×0+3×4)/(2+3)=12/5=2.4 m。","支点设在2.4 m，左右力矩2g×2.4与3g×1.6相等。"],"ans":"距2 kg端2.4 m。","verification":"4.8g=4.8g。","pitfall":"用中点2 m而不考虑质量差。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":5,"primary_section":"5.3","related_sections":[]}],"practice":[{"q":"两个相反平行力各5 N，相距1 m，可以用一个零合力完全替代吗？","given":"作用线不同。","analysis":"合力零但矩不零。","method":"算力偶。","principle":"M=Fd。","steps":["R=0。","M=5×1=5 N·m，单个零力不能提供此矩。"],"ans":"不能。","verification":"选择一个力作用线作矩心，另力仍给5 N·m。","pitfall":"零合力就无任何作用。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":5,"primary_section":"5.3","related_sections":[]},{"q":"质量1 kg在x=−2 m，质量3 kg在x=2 m，重心？","given":"同一坐标系与均匀g。","analysis":"负坐标不是负质量。","method":"带坐标符号加权。","principle":"x_G=Σmx/Σm。","steps":["分子1×(−2)+3×2=4 kg·m。","除总质量4 kg得1 m。"],"ans":"x_G=1 m。","verification":"重心在两物体间且靠3 kg侧。","pitfall":"先把所有坐标取绝对值。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":5,"primary_section":"5.3","related_sections":[]},{"q":"均匀圆环重心可位于没有材料的圆心吗？","given":"质量分布对称、g近似均匀。","analysis":"重心是等效位置不是必须有物质的点。","method":"按对称质量配对。","principle":"相反位置等质量矩抵消。","steps":["各对质量关于圆心对称。","加权坐标和为0，故圆心是重心。"],"ans":"可以。","verification":"转动等效作用线并不要求该点有材料。","pitfall":"认为重心必须落在实体材料内。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":5,"primary_section":"5.3","related_sections":[]},{"q":"底面左右边界x=0与1 m，总重100 N，重力线x=0.8 m，求两端支持力；若重力线到1.2 m怎样？","given":"简化两支点，仅竖直力且支点只能推。","analysis":"支反力非负决定静态可行性。","method":"绕左端取矩，再求合力。","principle":"R_B×1=100x_G，R_A+R_B=100。","steps":["x=0.8时R_B=80、R_A=20 N，均可行。","x=1.2时R_B=120、R_A=−20 N，不能由仅向上接触维持。"],"ans":"前者可静止；后者需其他约束否则倾倒趋势。","verification":"负支反力揭示超出支撑范围。","pitfall":"把−20取正后说仍平衡。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":5,"primary_section":"5.3","related_sections":[]}],"quiz":{"q":"用x_R=ΣFᵢxᵢ/ΣFᵢ时分母为零，能直接答x_R=0吗？","given":"零合力，矩尚未判断。","analysis":"除零公式不适用。","method":"另查合矩。","principle":"零合力可伴非零力偶。","steps":["若合矩非零，为力偶，不能单力等效。","若合矩也零，整体系对平面刚体可为零作用，但不能由除零求位置0。"],"ans":"不能；必须分类审查合矩。","verification":"同量反向平行力分离就是反例。","pitfall":"把无定义商直接替成零。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":5,"primary_section":"5.3","related_sections":[]},"exam":["平行力题先定共同正方向，再带符号算总力和矩","重心题检查均匀g和质量分布，不先猜几何中心","稳定性题用支反力非负或重力矩解释，明确静态假设"],"quick":["代数合力","矩等效","作用线","质量重心","支承与稳定"],"exam_evidence":[],"content_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":156,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_5.3","url":"https://openstax.org/books/college-physics-2e/pages/9-3-stability","page_or_section":"9-3-stability","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":156,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_5.3","url":"https://openstax.org/books/college-physics-2e/pages/9-3-stability","page_or_section":"9-3-stability","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"平行力题先定共同正方向，再带符号算总力和矩","method":"x_G=Σmx/Σm。","principle":"各重力矩等效于总重力在重心。","worked_example_index":2,"verification":"4.8g=4.8g。","pitfall":"用中点2 m而不考虑质量差。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“求平行力的合力与作用线”的抽样复核：合力矩40×1.5=60 N·m，原矩30×2=60；位置靠30 N。；若出现“总力对了却把位置取1 m。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"p3","review_module":5,"feedback":"目标“用力矩确定重心并判断稳定性”的抽样复核：负支反力揭示超出支撑范围。；若出现“把−20取正后说仍平衡。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"把无定义商直接替成零。","correction":"不能；必须分类审查合矩。","verification":"同量反向平行力分离就是反例。"}],"illustration_spec":{"title":"平行力合力位置与重心","objects":["同向10/30 N","反向30/10 N","x轴","合力作用线","支撑区"],"relations":["同向合力x=1.5 m","反向合力x=−1 m","R=0不强画有限单力"],"labels":["x/m","40 N","20 N","ΣFᵢxᵢ","支撑范围"],"format":"SVG","priority":"P0","reuse":"需准确比例和带符号位置的新SVG","english":"Construct exact parallel-force diagrams: downward 10 N at x=0 and 30 N at x=2 m give 40 N at x=1.5 m; downward 30 N at x=0 and upward 10 N at x=2 give downward 20 N at x=-1 m. Keep force and moment equivalence visible."}}},"物理7":{"7.1":{"subject":"物理","subject_code":"physics","chapter_id":7,"section_id":"7.1","goals":["由力与位移判断功的正负","区分平均功率和瞬时功率"],"prerequisites":["力与位移","三角函数与单位"],"flow":["力与位移","正负功","总功","平均与瞬时功率","效率收支"],"concept_relation":"力与位移；正负功；总功；平均与瞬时功率；效率收支","deep":["功率描述做功或能量传递的快慢，不是功的大小。平均功率为一段时间的功除时间；瞬时功率可写为F·v，需同一时刻、同一对象的力与速度。匀速拖拉时不代表所有功率都为零，只说明合力净功率可为零。","额定或输入功率、输出功率与效率不能混写。若效率η=有用输出能量/输入能量，在相同时间下也可用输出功率/输入功率；损耗能量不是从总能量中消失，而是转向不作为目标输出的形式。","单位1 J=1 N·m，1 W=1 J/s；kWh为能量单位，不能因为带W就称功率。设备一段时间的能耗需考虑功率随时间变化，恒功率模型才可直接用Pt。","解应用题先确定算哪一个力的功或哪一环节功率，审查给的是平均还是瞬时、输入还是输出。角度从力与位移量起，不能把题图中力与竖直的角未经转换就代入cos。"],"derive":["恒力功W=Fs cosθ；多个力总功W总=ΣWᵢ。","P平均=W/Δt；瞬时P=Fv cosθ。","η=W有用/W输入=P输出/P输入（同时间边界）；1 kWh=1000 W×3600 s=3.6×10⁶ J。"],"examples":[{"q":"20 N恒力与水平位移夹角60°，物体水平移动5 m，该力做功？","given":"夹角指力与位移。","analysis":"只取沿位移分量。","method":"W=Fs cosθ。","principle":"恒力做功定义。","steps":["沿位移分量20×0.5=10 N。","W=10×5=50 J。"],"ans":"+50 J。","verification":"垂直分量不做这段水平位移的功。","pitfall":"直接20×5忽略角度。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.1","related_sections":[]},{"q":"起重机5 s把100 kg负载匀速提高2 m，g=10，忽略其他负载，输出功率？","given":"求负载获得的机械能率。","analysis":"匀速不代表拉力不做功。","method":"W=mgh，再P=W/t。","principle":"拉力克服重力增加势能。","steps":["W=100×10×2=2000 J。","P=2000/5=400 W。"],"ans":"400 W有用输出。","verification":"拉力1000 N、速度0.4 m/s，Fv=400 W。","pitfall":"以合力零推出起重机功率零。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.1","related_sections":[]},{"q":"电机输入功率1.0 kW，效率80%，以2 m/s匀速拉物体，拉力同向，求输出功率与拉力。","given":"效率在该工作状态给定。","analysis":"Fv对应输出而非输入。","method":"P出=ηP入，再F=P出/v。","principle":"同时间功率效率。","steps":["P出=0.80×1000=800 W。","F=800/2=400 N。"],"ans":"800 W、400 N。","verification":"输出800加损耗200等输入1000 W。","pitfall":"直接1000/2得500 N。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.1","related_sections":[]}],"practice":[{"q":"水平支持力竖直向上，物体水平移动3 m，这个力做功？","given":"支持方向与位移垂直。","analysis":"不是所有非零力都有非零功。","method":"cos90°=0。","principle":"功取沿位移分量。","steps":["W=Ns cos90°。","余弦0，故功0。"],"ans":"0 J。","verification":"支持力可存在但无水平分量。","pitfall":"只看有力有位移就说做功。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.1","related_sections":[]},{"q":"摩擦力恒定5 N与位移反向，移动4 m，摩擦功？","given":"方向始终相反。","analysis":"负号代表阻碍。","method":"W=Fs cos180°。","principle":"反向力做负功。","steps":["5×4×(−1)=−20 J。","大小20 J但带负方向意义。"],"ans":"−20 J。","verification":"若只它做功，动能减少20 J。","pitfall":"答0因为反向。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.1","related_sections":[]},{"q":"2 kWh是多少J？这是功率吗？","given":"kWh是功率乘时间。","analysis":"组合单位量纲。","method":"2×3.6×10⁶。","principle":"能量=功率×时间。","steps":["等于7.2×10⁶ J。","单位是能量，不是功率。"],"ans":"7.2×10⁶ J，能量。","verification":"2 kW连续1 h的能量。","pitfall":"把kWh读成千瓦每小时的功率。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.1","related_sections":[]},{"q":"车受500 N恒定驱动力，同方向速度由10变20 m/s，瞬时驱动功率各多少？能直接说平均功率为后者吗？","given":"力恒定，未给速度随时间过程。","analysis":"瞬时量与区间平均不同。","method":"分别P=Fv。","principle":"功率依同一时刻速度。","steps":["起初5000 W。","末10000 W；平均需对应总功和总时间或额外速度过程。"],"ans":"5 kW、10 kW；不能把末值当平均。","verification":"若速度线性随时变才可另算平均7.5 kW。","pitfall":"用末速替代整个过程平均。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.1","related_sections":[]}],"quiz":{"q":"人抱重物静止，手累且身体消耗能量，是否与“手对重物机械功为零”矛盾？","given":"重物没有位移，人体内部过程另论。","analysis":"对象和能量过程不同。","method":"分别划定重物外力功与人体代谢。","principle":"机械功依所研究物体位移。","steps":["重物位移0，手对它W=0。","人体肌肉维持状态仍可消耗化学能并散热。"],"ans":"不矛盾。","verification":"同一事件可有不同系统内部能量转换。","pitfall":"以主观疲劳替代物理功定义。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.1","related_sections":[]},"exam":["功题明确施力者、对象、位移与夹角","功率题分平均/瞬时及输入/输出，匀速不等于驱动力功率零","效率题先画能量收支，损耗不说消失"],"quick":["力与位移","正负功","总功","平均与瞬时功率","效率收支"],"exam_evidence":[],"content_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":222,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_7.1","url":"https://openstax.org/books/college-physics-2e/pages/7-1-work-the-scientific-definition","page_or_section":"7-1-work-the-scientific-definition","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":222,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_7.1","url":"https://openstax.org/books/college-physics-2e/pages/7-1-work-the-scientific-definition","page_or_section":"7-1-work-the-scientific-definition","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"功题明确施力者、对象、位移与夹角","method":"P出=ηP入，再F=P出/v。","principle":"同时间功率效率。","worked_example_index":2,"verification":"输出800加损耗200等输入1000 W。","pitfall":"直接1000/2得500 N。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“由力与位移判断功的正负”的抽样复核：垂直分量不做这段水平位移的功。；若出现“直接20×5忽略角度。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"p3","review_module":5,"feedback":"目标“区分平均功率和瞬时功率”的抽样复核：若速度线性随时变才可另算平均7.5 kW。；若出现“用末速替代整个过程平均。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"以主观疲劳替代物理功定义。","correction":"不矛盾。","verification":"同一事件可有不同系统内部能量转换。"}],"illustration_spec":{"title":"功的分量与功率边界","objects":["斜拉力20 N","水平位移5 m","60°夹角","输入输出损耗功率"],"relations":["沿位移分量10 N","W=50 J","输入1000=输出800+损耗200 W"],"labels":["θ=60°","Fcosθ","W/J","P/W","η=80%"],"format":"SVG","priority":"P0","reuse":"V22相关功图可核后复用，题值不同须说明","english":"Show a 20 N force at 60 degrees to a 5 m horizontal displacement, giving 50 J of work. Add a separate power balance of 1000 W input, 800 W useful output and 200 W loss; do not imply uniform motion means zero driving power."}},"7.2":{"subject":"物理","subject_code":"physics","chapter_id":7,"section_id":"7.2","goals":["由力位移图求有向功","用分段与面积处理变力并核条件"],"prerequisites":["恒力功","图象面积"],"flow":["恒力矩形","线性梯形","一般曲线","弹力与外力","总功检查"],"concept_relation":"恒力矩形；线性梯形；一般曲线；弹力与外力；总功检查","deep":["弹簧在胡克定律近似范围内，弹簧对物体的力与相对平衡位置的位移反向：F弹=−kx。把弹簧从0拉至伸长x时，若准静态外力平衡弹力，外力F外=+kx，其功与弹力功大小相等、符号相反。","变力功取决路径上的力分量分布，图下面积只表示所画力做功，并不自动是总功。若还存在摩擦或重力等其他做功力，求动能变化需加总所有相关功；“图给了一个力”不代表其他力不存在。","使用实验F-x数据估功时，应统一单位，辨测力的是外拉力还是弹力、x是位移还是伸长，并注意加载卸载曲线可能不同。若存在滞后，不能只按一条理想直线把储能和耗散全部合并。","对结果可用量纲、分段加法以及力是否助推或阻碍判断正负。若整段力分量非负且x增加，总功不应为负；若图面积相消为零，物体仍可能在中途先加速后减速，净功零不表示过程里每段无功。"],"derive":["一维W为Fₓ-x图有向面积；分段功可相加。","线性由F₁变F₂、位移Δx时W=(F₁+F₂)Δx/2；一般非线性不可只取端点平均。","胡克范围：0至x的准静态外力功+kx²/2，弹力功−kx²/2。"],"examples":[{"q":"F-x图0到3 m恒为4 N，求该力功。","given":"F为沿x分量，x增加。","analysis":"矩形面积。","method":"W=FΔx。","principle":"功对应F-x有向面积。","steps":["面积4×3=12 N·m。","图在正区，功为正。"],"ans":"+12 J。","verification":"与恒力公式一致。","pitfall":"把F-t面积冲量公式混用。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.2","related_sections":[]},{"q":"力随x由0 m时2 N线性增到4 m时10 N，求功并比较末力乘位移。","given":"沿运动方向的线性变力。","analysis":"梯形面积或线性平均。","method":"W=(2+10)×4/2。","principle":"线性情况下端点平均为位移平均力。","steps":["平均力6 N。","W=6×4=24 J；末力法10×4=40 J高估。"],"ans":"24 J。","verification":"矩形2×4=8加三角形8×4/2=16，共24。","pitfall":"所有变力都拿末值乘总位移。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.2","related_sections":[]},{"q":"弹簧k=200 N/m，从自然长准静态拉长0.10 m，外力与弹力分别做功？","given":"胡克定律有效，无其他耗散。","analysis":"两力方向相反且线性。","method":"各取三角形面积及符号。","principle":"F外=kx，F弹=−kx。","steps":["末外力20 N，外力功0.5×20×0.10=1.0 J。","弹力功−1.0 J。"],"ans":"外力+1.0 J，弹力−1.0 J。","verification":"准静态动能变化近0，两力总功相消。","pitfall":"把20 N乘0.1得2 J或两功同号。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.2","related_sections":[]}],"practice":[{"q":"0到2 m力+3 N，2到5 m力−2 N，总功？","given":"力分量图，x单调增。","analysis":"负区有向面积抵消。","method":"分段相加。","principle":"W=ΣFᵢΔxᵢ。","steps":["前段+6 J。","后段−6 J，合0。"],"ans":"0 J。","verification":"可中间先增能6再减6，不表示无作用。","pitfall":"把面积都取正得到12 J。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.2","related_sections":[]},{"q":"F-x图面积单位是什么？与F-t图面积是否相同物理量？","given":"横轴分别m与s。","analysis":"单位乘积决定基本解释。","method":"分别相乘。","principle":"力位移给功，力时间给冲量。","steps":["N·m=J。","N·s=kg·m/s，两个不同物理量。"],"ans":"前为功，后为冲量。","verification":"不能把m与s互换。","pitfall":"不看横轴只认力图面积。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.2","related_sections":[]},{"q":"一曲线起末力相同均为0，中间有正峰，能以端点平均0推功0吗？","given":"中间力在一段为正且x增加。","analysis":"非线性端点不代表平均。","method":"看整个曲线面积。","principle":"功累积所有位置贡献。","steps":["正峰下有正面积。","端点平均只对线性等条件成立，此处不能套。"],"ans":"不能；功应为正。","verification":"曲线可类似正半波，端点0不消除内部面积。","pitfall":"把梯形公式用于任意曲线。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.2","related_sections":[]},{"q":"k=100 N/m弹簧由0.10拉至0.20 m，准静态外功？","given":"胡克范围，无耗散。","analysis":"计算储能差而非末储能。","method":"W外=k(x₂²−x₁²)/2。","principle":"面积为两三角形之差。","steps":["0.5×100×(0.04−0.01)=1.5 J。","等价力从10到20 N，平均15乘0.10=1.5 J。"],"ans":"+1.5 J。","verification":"两个方法相合。","pitfall":"直接算到0.2的2 J而忘初已伸长。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.2","related_sections":[]}],"quiz":{"q":"给出某拉力F-x面积10 J，能否直接说物体动能增加10 J？","given":"未说明其他力功。","analysis":"单力功与总功不同。","method":"列其他力并求总功。","principle":"动能变化等于合力总功。","steps":["摩擦等可做负功。","只有其他总功为0等条件下，ΔK才等10 J。"],"ans":"不能无条件。","verification":"若摩擦功−10 J，净功0而动能不变。","pitfall":"把所画一个力当成所有力。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.2","related_sections":[]},"exam":["面积题先核横轴与力的分量，分正负段求和","端点平均只在线性条件用，曲线需更多信息","弹簧题明确外力或弹力、起末伸长与准静态条件"],"quick":["恒力矩形","线性梯形","一般曲线","弹力与外力","总功检查"],"exam_evidence":[],"content_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":229,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_7.2","url":"https://openstax.org/books/college-physics-2e/pages/7-2-kinetic-energy-and-the-work-energy-theorem","page_or_section":"7-2-kinetic-energy-and-the-work-energy-theorem","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":229,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_7.2","url":"https://openstax.org/books/college-physics-2e/pages/7-2-kinetic-energy-and-the-work-energy-theorem","page_or_section":"7-2-kinetic-energy-and-the-work-energy-theorem","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"面积题先核横轴与力的分量，分正负段求和","method":"各取三角形面积及符号。","principle":"F外=kx，F弹=−kx。","worked_example_index":2,"verification":"准静态动能变化近0，两力总功相消。","pitfall":"把20 N乘0.1得2 J或两功同号。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“由力位移图求有向功”的抽样复核：与恒力公式一致。；若出现“把F-t面积冲量公式混用。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“用分段与面积处理变力并核条件”的抽样复核：准静态动能变化近0，两力总功相消。；若出现“把20 N乘0.1得2 J或两功同号。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"把所画一个力当成所有力。","correction":"不能无条件。","verification":"若摩擦功−10 J，净功0而动能不变。"}],"illustration_spec":{"title":"力位移面积与弹簧功","objects":["2到10 N线性图","正负分段图","弹力/外力对称图"],"relations":["0至4 m面积24 J","正负面积可抵消","外力与弹力方向相反"],"labels":["Fₓ/N","x/m","24 J","F外=kx","F弹=−kx"],"format":"SVG","priority":"P0","reuse":"V22 P25力位移图可复用经核数值，勿重复展示同图","english":"Plot F_x increasing linearly from 2 to 10 N over 0 to 4 m and shade exactly 24 J. In a separate Hookean spring panel distinguish applied quasi-static force +kx from restoring force -kx, with signed work areas."}},"7.3":{"subject":"物理","subject_code":"physics","chapter_id":7,"section_id":"7.3","goals":["由总功求动能及速度变化","区分动能、动量和参考系依赖"],"prerequisites":["牛顿第二定律","匀变速关系"],"flow":["运动参考系","平方关系","总功","初末动能","物理可行性"],"concept_relation":"运动参考系；平方关系；总功；初末动能；物理可行性","deep":["一维恒定合力推导时，F=ma与v²−u²=2as联立得到Fs=mv²/2−mu²/2。该推导中的恒力是方便的起点，不意味着动能定理只适用于恒力；对变力可分段并求极限或用图面积累积。","净功为正使速率增加，负使速率下降，零使初末动能相同。但总功零不保证运动方向不变，圆周运动的向心力可改变速度方向而不改变速率；动能定理也不直接给出运动轨迹方向。","制动距离可在阻力恒定等假设下由动能定理估计：制动力做负功把初动能减少至零。真实刹车还包括反应距离和随条件改变的摩擦，不能把纯制动模型当作任何道路的安全停车距离保证。","求速度时由平方只得到速率大小，方向要结合几何、过程和初始条件判断。若算得末动能负值，通常说明物体在预设位置前已停下、假设不成立或计算有误，不能对负数取平方根后忽略其物理含义。"],"derive":["由Fs=mas、2as=v²−u²，得W总=m(v²−u²)/2。","K=mv²/2；p=mv时K=p²/(2m)，仅同一经典平动模型。","恒定反向阻力f使物体停止：fs=mu²/2，s=mu²/(2f)，需阻力恒定且不含反应阶段。"],"examples":[{"q":"质量2 kg物体速率3 m/s，动能多少？若速度改成−3 m/s呢？","given":"同一参考系，经典平动。","analysis":"平方使用速率大小。","method":"K=mv²/2。","principle":"动能非负。","steps":["K=0.5×2×9=9 J。","−3平方仍9，动能也9 J。"],"ans":"均9 J。","verification":"方向相反改变动量但不改变相同速率的K。","pitfall":"把负速度代成负动能。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.3","related_sections":[]},{"q":"2 kg物体初速2 m/s，驱动力功20 J、摩擦功−8 J，其余功0，末速率？","given":"总功12 J。","analysis":"先求初能再加净功。","method":"K末=K初+W总。","principle":"动能定理。","steps":["K初=0.5×2×4=4 J，K末=4+20−8=16 J。","v=√(2×16/2)=4 m/s。"],"ans":"4 m/s。","verification":"动能增加12 J正等于净功。","pitfall":"只用20或把初K漏掉。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.3","related_sections":[]},{"q":"1000 kg车初速10 m/s，恒定制动力5000 N反向，忽略反应距离，制动距离？若初速加倍呢？","given":"水平，无其他净功，阻力恒定。","analysis":"停止需要耗掉初动能。","method":"−fs=0−mu²/2。","principle":"动能定理。","steps":["s=1000×100/(2×5000)=10 m。","初速20时s=1000×400/10000=40 m。"],"ans":"10 m；加倍初速为40 m。","verification":"距离与u²成正比，增为4倍。","pitfall":"说速度两倍距离仅两倍，或包含未计算的反应距离。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.3","related_sections":[]}],"practice":[{"q":"质量不变、速率由2到6 m/s，动能变几倍？","given":"同一模型参考系。","analysis":"速率比平方。","method":"(6/2)²。","principle":"K∝v²。","steps":["速率3倍。","动能9倍。"],"ans":"9倍。","verification":"若m=1，K从2到18 J。","pitfall":"按线性比答3倍。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.3","related_sections":[]},{"q":"两物体动量大小同为6 kg·m/s，质量2与3 kg，动能各多少？","given":"经典平动。","analysis":"固定p时反比于m。","method":"K=p²/(2m)。","principle":"由p=mv代入。","steps":["2 kg者36/4=9 J。","3 kg者36/6=6 J。"],"ans":"9 J与6 J。","verification":"速度分别3和2 m/s，直接计算相同。","pitfall":"固定p仍说质量大K必大。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.3","related_sections":[]},{"q":"匀速圆周运动向心力的功为0，是否速度矢量不变？","given":"力处处垂直瞬时位移。","analysis":"速率与方向不同。","method":"说明动能与动量变化。","principle":"垂直力不做功但可改变方向。","steps":["动能不变即速率不变。","方向持续变化，所以速度矢量变。"],"ans":"不是，只有速率恒定。","verification":"向心加速度非零支持方向变化。","pitfall":"总功0推出合力0。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.3","related_sections":[]},{"q":"1 kg物体初速4 m/s，受恒阻力2 N，想计算走5 m后的动能得到−2 J，应如何解释？","given":"除阻力外无净功，阻力始终反向。","analysis":"预设5 m超过停距。","method":"先求初K和停距。","principle":"动能不可能负。","steps":["K初=8 J，s停=8/2=4 m。","已在4 m停下，不能仍按同方向滑动5 m模型计算。"],"ans":"5 m状态假设不成立，须重新描述停止后的过程。","verification":"4 m时K=0；负值是模型外推警报。","pitfall":"把负动能取绝对值或虚构速度。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.3","related_sections":[]}],"quiz":{"q":"物体受恒力转向，初末速率相同，能由动能定理断言初末动量相同吗？","given":"只知速率大小相同。","analysis":"动能为标量不包含方向。","method":"比较K与p定义。","principle":"K依v²，p依速度矢量。","steps":["ΔK=0说明总功0。","若方向改变，p可改变；需方向信息才能求Δp。"],"ans":"不能。","verification":"反向同速可有Δp大小2mv而ΔK0。","pitfall":"以能量守恒替代矢量关系。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.3","related_sections":[]},"exam":["能量题先加总各力功并保留初动能","比较题说清固定m还是固定p，不同约束结论不同","求得负K要检查是否提前停止，速率根号不提供方向"],"quick":["运动参考系","平方关系","总功","初末动能","物理可行性"],"exam_evidence":[],"content_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":232,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_7.3","url":"https://openstax.org/books/college-physics-2e/pages/7-2-kinetic-energy-and-the-work-energy-theorem","page_or_section":"7-2-kinetic-energy-and-the-work-energy-theorem","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":232,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_7.3","url":"https://openstax.org/books/college-physics-2e/pages/7-2-kinetic-energy-and-the-work-energy-theorem","page_or_section":"7-2-kinetic-energy-and-the-work-energy-theorem","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"能量题先加总各力功并保留初动能","method":"−fs=0−mu²/2。","principle":"动能定理。","worked_example_index":2,"verification":"距离与u²成正比，增为4倍。","pitfall":"说速度两倍距离仅两倍，或包含未计算的反应距离。"},"diagnostics":[{"goal_index":0,"question_ref":"e1","review_module":4,"feedback":"目标“由总功求动能及速度变化”的抽样复核：动能增加12 J正等于净功。；若出现“只用20或把初K漏掉。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"q","review_module":5,"feedback":"目标“区分动能、动量和参考系依赖”的抽样复核：反向同速可有Δp大小2mv而ΔK0。；若出现“以能量守恒替代矢量关系。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"以能量守恒替代矢量关系。","correction":"不能。","verification":"反向同速可有Δp大小2mv而ΔK0。"}],"illustration_spec":{"title":"动能平方关系与制动距离","objects":["同质量不同速度","K对v²直线","恒阻力制动图","停距标记"],"relations":["速度2倍K4倍","恒阻力停距与初速平方正比","不画负动能实态"],"labels":["K=mv²/2","W总=ΔK","10 m","40 m","不含反应距离"],"format":"SVG","priority":"P0","reuse":"相关V22能量图可补充，需核是否对应本题","english":"Show kinetic energy proportional to speed squared and compare ideal constant-force braking distances 10 m and 40 m for initial speeds 10 and 20 m/s. State that reaction distance and road variability are excluded, and never depict negative kinetic energy as a real state."}},"7.4":{"subject":"物理","subject_code":"physics","chapter_id":7,"section_id":"7.4","goals":["用保守力功定义势能差","分别求重力与弹性势能并说明零点"],"prerequisites":["功与能","胡克定律"],"flow":["相互作用系统","保守力","零点与差","重力势能","弹性势能"],"concept_relation":"相互作用系统；保守力；零点与差；重力势能；弹性势能","deep":["重力功由高度差决定，不由路径总长度决定。缓坡路径较长但重力沿运动分量较小，固定起终高度下二者效果相抵；外力做功是否相同还需审查摩擦等其他作用，不能把重力路径无关推广所有力。","理想弹簧在胡克范围内以自然长度为零形变，U_s=kx²/2。伸长与压缩相同大小时势能相同，但弹力方向相反；x是相对自然长度的形变量，不是弹簧总长，也不是物体任意位移。","弹簧势能公式可由准静态外力F=kx的F-x三角形面积得到。若材料有明显滞后或超出弹性范围，输入功不一定全部变成可恢复弹性势能，模型需要修改。","使用势能差时先选系统、零点和符号，再求初末差。负势能不代表系统不可能，负的ΔU说明势能降低；不要为了结果为正随意改零点或取绝对值，尤其在守恒方程中必须前后使用同一约定。"],"derive":["W重=mg(h_i−h_f)=−ΔU_g；近地面U_g=mgh+C。","U_s=kx²/2，x为自然长起算的伸长或压缩；W弹=U_s初−U_s末。","改零点只加同一常数，不改势能差、保守力功或可观测运动。"],"examples":[{"q":"2 kg物体从所选h=1 m升到h=4 m，g=10，势能增加及重力功？","given":"均匀重力场。","analysis":"势能增量与重力功反号。","method":"ΔU=mgΔh，W重=−ΔU。","principle":"保守力功关系。","steps":["Δh=3 m，ΔU=2×10×3=60 J。","重力功−60 J。"],"ans":"势能+60 J，重力功−60 J。","verification":"升高时重力与位移相反，负功合理。","pitfall":"把重力功也写+60。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.4","related_sections":[]},{"q":"k=100 N/m弹簧自然长0.30 m，被拉到0.40 m，势能？","given":"胡克范围，以自然长为零形变。","analysis":"应取伸长而非总长。","method":"x=0.40−0.30，U=kx²/2。","principle":"外力准静态输入三角形功储为弹性势能。","steps":["x=0.10 m。","U=0.5×100×0.01=0.50 J。"],"ans":"0.50 J。","verification":"末弹力10 N，平均外力5 N乘0.1 m=0.5 J。","pitfall":"把0.40当x。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.4","related_sections":[]},{"q":"同一物体在两个零点约定下初末势能分别为20到50 J、−80到−50 J，运动预测会不同吗？","given":"两套能量只差共同常数100 J。","analysis":"绝对值不同但差相同。","method":"比较ΔU与保守力功。","principle":"势能零点不影响差值。","steps":["第一套ΔU=30 J。","第二套ΔU=(−50)−(−80)=30 J，W保均−30 J。"],"ans":"不会仅因零点不同而改变预测。","verification":"各状态差100，但初末变化一致。","pitfall":"看到负势能就判不可能。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.4","related_sections":[]}],"practice":[{"q":"1 kg物体下降2 m，g=10，重力功和势能变化？","given":"均匀重力场。","analysis":"下降与重力同向。","method":"W=mg×下降高度。","principle":"W重=−ΔU。","steps":["W=1×10×2=20 J。","ΔU=−20 J。"],"ans":"+20 J、−20 J。","verification":"势能减少可供其他形式能增加。","pitfall":"把下降高度带负后又多加一次负号。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.4","related_sections":[]},{"q":"同弹簧伸长0.05与压缩0.05 m，储能相同吗、弹力方向相同吗？","given":"胡克模型，以自然长为原点。","analysis":"平方与带符号力不同。","method":"比较U和F。","principle":"U=kx²/2，F=−kx。","steps":["两种x²相同故U相同。","x符号相反故F方向相反。"],"ans":"能量相同，弹力方向相反。","verification":"恢复力都指向自然长。","pitfall":"势能相同就说力方向也相同。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.4","related_sections":[]},{"q":"同起终高度沿两不同无摩擦路径，重力功会因路径长而更大吗？","given":"仅比较重力功。","analysis":"重力为保守力。","method":"用mg(h_i−h_f)。","principle":"功只由高度差。","steps":["两路径高度差相同。","故重力功相同，不用路程总长乘mg。"],"ans":"不会。","verification":"长缓坡的重力沿程分量较小。","pitfall":"把重力大小mg乘全部曲线长度。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.4","related_sections":[]},{"q":"k=200 N/m弹簧形变由0.20变0.10 m，弹力做多少功？","given":"均为伸长，胡克范围。","analysis":"弹力释放储能。","method":"W弹=U初−U末。","principle":"保守力功等于势能减少。","steps":["U初=0.5×200×0.04=4 J。","U末=1 J，W=3 J。"],"ans":"+3 J。","verification":"伸长减小，弹力与收缩位移同向。","pitfall":"只算末U=1 J当作功。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.4","related_sections":[]}],"quiz":{"q":"某点重力势能−40 J，可以用“能量不能为负”判错吗？","given":"零点任意选定。","analysis":"势能与动能的非负性质不同。","method":"问零点并比较势能差。","principle":"势能加常数不影响物理。","steps":["该点可位于所选零点下方。","检查初末零点一致与差值，而非强迫U≥0。"],"ans":"不能仅据负号判错。","verification":"同点换零面可得到正值而运动不变。","pitfall":"把K非负推广所有能量定义。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.4","related_sections":[]},"exam":["势能题先选系统零点并写初末，不只记mgh","弹簧题先求形变量再平方，区分总长和伸长","路径题明确只讨论保守力功，其他力功另审"],"quick":["相互作用系统","保守力","零点与差","重力势能","弹性势能"],"exam_evidence":[],"content_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":239,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_7.4","url":"https://openstax.org/books/college-physics-2e/pages/7-3-gravitational-potential-energy","page_or_section":"7-3-gravitational-potential-energy","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":239,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_7.4","url":"https://openstax.org/books/college-physics-2e/pages/7-3-gravitational-potential-energy","page_or_section":"7-3-gravitational-potential-energy","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"势能题先选系统零点并写初末，不只记mgh","method":"比较ΔU与保守力功。","principle":"势能零点不影响差值。","worked_example_index":2,"verification":"各状态差100，但初末变化一致。","pitfall":"看到负势能就判不可能。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“用保守力功定义势能差”的抽样复核：升高时重力与位移相反，负功合理。；若出现“把重力功也写+60。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“分别求重力与弹性势能并说明零点”的抽样复核：各状态差100，但初末变化一致。；若出现“看到负势能就判不可能。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"把K非负推广所有能量定义。","correction":"不能仅据负号判错。","verification":"同点换零面可得到正值而运动不变。"}],"illustration_spec":{"title":"势能零点和弹簧形变","objects":["同高度两零点","初末高度","自然长弹簧","伸长与压缩"],"relations":["改零点差值不变","伸压同大小U相同","弹力恢复方向相反"],"labels":["ΔU","W保=−ΔU","x相对自然长","U_s=kx²/2"],"format":"SVG","priority":"P0","reuse":"V22 P18弹簧能图可复用，需说明自然长与零点","english":"Show two gravitational potential references yielding the same delta U, and an ideal spring at natural length, equal extension and compression. Mark deformation x from natural length and opposite restoring-force arrows with equal stored energies."}},"7.5":{"subject":"物理","subject_code":"physics","chapter_id":7,"section_id":"7.5","goals":["按做功类别判定机械能是否守恒","用能量收支求速度高度及耗散"],"prerequisites":["动能与势能","功和系统边界"],"flow":["选系统零点","初末K与U","其他力功","分段收支","可达与接触"],"concept_relation":"选系统零点；初末K与U；其他力功；分段收支；可达与接触","deep":["选零点并列初末状态有助于减少中间过程计算。沿曲线运动仍可用相同起终能量关系，只要条件满足；但求运动方向、接触力和是否离轨，能量方程通常不够，还需动力学与几何约束。","弹簧与重力共同作用时应把相应势能都列入，先区分自然长度、初形变与高度变化。弹簧由压缩释放可以把储能转为动能，但物体是否继续接触弹簧、何时脱离等需按装置条件分析。","多个过程可分段：粗糙段有耗散、光滑段可守恒、碰撞段机械能可能突变。不能因为整个题出现某个光滑面就把碰撞和粗糙段也一并守恒；系统和条件可随问题分段明确。","解完检查所需能量是否充足、末速率是否实数，以及机械能差与其他力功是否一致。若能量不足到达某高度，应求转向点或说明不可达，不把负的v²继续当作正常数值答案。"],"derive":["由W总=ΔK及W保=−ΔU，得Δ(K+U)=W其他。","W其他=0时K初+U初=K末+U末；有摩擦等时保留其功。","近地面无耗散下v²=v₀²+2g(h₀−h)，只给速率关系，接触与方向需另判。"],"examples":[{"q":"1 kg物体从5 m高静止滑到地面，光滑且保持接触，g=10，地面速率？","given":"重力势能零面取地面，法向力不做功。","analysis":"机械能守恒。","method":"mgh=mv²/2。","principle":"其他力总功0。","steps":["初U=1×10×5=50 J。","末K=50 J，v=√100=10 m/s。"],"ans":"10 m/s。","verification":"0.5×1×100=50 J，与初能一致。","pitfall":"把路径总长当h或忘平方根。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.5","related_sections":[]},{"q":"2 kg物体初速4 m/s，从3 m高到1 m高，摩擦功−8 J，g=10，末速率？","given":"起末高度同零点，已给摩擦总功。","analysis":"不能机械能守恒，需收支。","method":"K末=K初+mg(h初−h末)+W摩。","principle":"Δ(K+U)=W其他。","steps":["K初=16 J，势能降低40 J。","K末=16+40−8=48 J，v=√(2×48/2)=√48≈6.93 m/s。"],"ans":"约6.93 m/s。","verification":"末机械能48+20=68，初16+60=76，差−8。","pitfall":"因有势能就把摩擦忽略。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.5","related_sections":[]},{"q":"0.5 kg物体靠在压缩0.10 m、k=200 N/m弹簧上，在光滑水平面释放，弹簧回自然长后物体速率？","given":"理想接触，弹簧不再拉物体，无其他耗散。","analysis":"形变储能转平动能。","method":"kx²/2=mv²/2。","principle":"选物体弹簧系统，其他功0。","steps":["初弹性能1 J。","0.25v²=1，v=2 m/s。"],"ans":"2 m/s。","verification":"初末均1 J，形变到0时储能释放完。","pitfall":"把最大弹力20 N当全程恒力。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.5","related_sections":[]}],"practice":[{"q":"光滑轨道上有电机持续驱动，能无条件机械能守恒吗？","given":"无摩擦但电机可做功。","analysis":"无摩擦不等于无能量输入。","method":"核其他力功。","principle":"ΔE机械=W其他。","steps":["电机正功输入机械能。","若未把能源系统完整纳入，机械能一般增加。"],"ans":"不能。","verification":"无摩擦只排除了一个耗散项。","pitfall":"只看光滑一词决定守恒。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.5","related_sections":[]},{"q":"初机械能30 J，其他力总功−12 J，末机械能多少？总能量消失了吗？","given":"同一系统机械形式。","analysis":"负功转出机械能。","method":"E末=E初+W其他。","principle":"能量收支。","steps":["E末=30−12=18 J。","12 J可转内能等，总能量并未因此消失。"],"ans":"18 J；未消失。","verification":"初30=末机械18+转出12。","pitfall":"把机械能损失称总能量消灭。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.5","related_sections":[]},{"q":"物体以10 m/s向上运动，g=10，无阻力，最高再升多高？","given":"末速0，均匀g。","analysis":"初动能转重力势能。","method":"mv₀²/2=mgΔh。","principle":"机械能守恒。","steps":["Δh=v₀²/(2g)=100/20=5 m。","质量相消。"],"ans":"5 m。","verification":"运动学0=100−2×10×5相合。","pitfall":"用v₀/g=1 s当高度。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.5","related_sections":[]},{"q":"1 kg从高3 m静止出发，到高1 m处前累计摩擦功−25 J，g=10，能到吗？","given":"无外部输入。","analysis":"可释放势能只有20 J。","method":"估可用K并判负值。","principle":"能量必须满足K≥0。","steps":["K末=30−10−25=−5 J。","负值说明不能按该过程到该状态，需更早停止或条件改变。"],"ans":"不能依题设过程到达。","verification":"目标路径所需耗散超出可用势能5 J。","pitfall":"对负能量取绝对值得速度。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.5","related_sections":[]}],"quiz":{"q":"过山车能量计算给出某位置正的速率，是否已经证明车不会离开轨道？","given":"未给向心力和接触约束分析。","analysis":"能量不包含全部力与接触信息。","method":"另列径向动力学并查法向力。","principle":"接触通常需N≥0等条件。","steps":["能量方程仅提供候选速率。","用该v审查径向合力及支持约束，若需负N则假设接触失效。"],"ans":"尚未证明。","verification":"同一速率在不同曲率位置的N不同。","pitfall":"把能量可达等同所有动力学条件可行。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.5","related_sections":[]},"exam":["能量题先定系统，重力功与势能别重复算","分段题逐段审查摩擦、驱动和碰撞，不能全程一式守恒","算出v后若涉及轨道再查接触，负v²说明预设状态不可达"],"quick":["选系统零点","初末K与U","其他力功","分段收支","可达与接触"],"exam_evidence":[],"content_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":245,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_7.5","url":"https://openstax.org/books/college-physics-2e/pages/7-6-conservation-of-energy","page_or_section":"7-6-conservation-of-energy","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":245,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_7.5","url":"https://openstax.org/books/college-physics-2e/pages/7-6-conservation-of-energy","page_or_section":"7-6-conservation-of-energy","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"能量题先定系统，重力功与势能别重复算","method":"kx²/2=mv²/2。","principle":"选物体弹簧系统，其他功0。","worked_example_index":2,"verification":"初末均1 J，形变到0时储能释放完。","pitfall":"把最大弹力20 N当全程恒力。"},"diagnostics":[{"goal_index":0,"question_ref":"p0","review_module":4,"feedback":"目标“按做功类别判定机械能是否守恒”的抽样复核：无摩擦只排除了一个耗散项。；若出现“只看光滑一词决定守恒。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e1","review_module":5,"feedback":"目标“用能量收支求速度高度及耗散”的抽样复核：末机械能48+20=68，初16+60=76，差−8。；若出现“因有势能就把摩擦忽略。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"把能量可达等同所有动力学条件可行。","correction":"尚未证明。","verification":"同一速率在不同曲率位置的N不同。"}],"illustration_spec":{"title":"机械能收支与适用条件","objects":["高低两状态","K/U能量条","摩擦转出箭头","弹簧释放","轨道接触检查"],"relations":["初机械76末68差8","W其他=ΔE机械","能量可达与N约束分开"],"labels":["K","U_g","U_s","W其他","N≥0另查"],"format":"SVG","priority":"P0","reuse":"V22 P07可复核复用，需注明具体示例区别","english":"Draw energy-accounting bars with 76 J initial mechanical energy and 68 J final plus 8 J transferred to other forms. Show conservation only when other work is zero, and keep track-contact force constraints as a separate check."}},"7.6":{"subject":"物理","subject_code":"physics","chapter_id":7,"section_id":"7.6","goals":["区分静能、动能与系统质量变化","用质能关系换算能量并保持系统边界一致"],"prerequisites":["科学记数法","能量单位"],"flow":["静能定义","系统边界","质量差","单位换算","可用能与限制"],"concept_relation":"静能定义；系统边界；质量差；单位换算；可用能与限制","deep":["用原子质量计算时要审查电子数是否在两边抵消，不能混用原子质量、裸核质量和自由核子质量而不处理电子。题目直接给质量差时可换算，但完整核反应的质量差还需可靠质量数据与反应条件。","c很大，因此日常数量的能量对应质量变化极小。并非所有质量都能在任意装置中完全转为可用输出能量；给定质量所对应静能是能量尺度，不自动等于某种燃料现实可提取的能量。","光子静质量为零但有能量和动量，这提醒E₀=mc²说的是静能关系，不可把它解释为任何有能量实体都必须有非零静质量。更一般的能量动量关系超出本节基础计算时应单独说明，不能用低速K式求光子动能。","换算MeV与J时写清每反应、每个粒子或总量；乘反应次数才得到总能量。结果核验可先看数量级和单位，再核是否把能量变化、静能与可用输出混成一项。"],"derive":["静能E₀=mc²；同边界前后ΔE=Δmc²，符号需按吸收或释放解释。","本节数值题取c=3.00×10⁸ m/s；1 eV=1.602176634×10⁻¹⁹ J。","题设可用1 u c²≈931.5 MeV；质量差为u时乘该能量因子，不把u直接当kg。"],"examples":[{"q":"1.00 g质量对应多少静能？取c=3.00×10⁸ m/s。是否等于现实任意1 g燃料都可输出此能量？","given":"只求静能尺度。","analysis":"先g转kg，后解释可提取性。","method":"E₀=mc²。","principle":"质能关系不是装置效率承诺。","steps":["m=1.00×10⁻³ kg。","E₀=10⁻³×9.00×10¹⁶=9.00×10¹³ J。"],"ans":"9.00×10¹³ J；不保证现实燃料全可提取。","verification":"kg·m²/s²=J，1 kg对应9×10¹⁶ J。","pitfall":"漏g转kg或把静能当必然可用能。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.6","related_sections":[]},{"q":"某假设核反应前后质量差0.0100 u，给1 u c²=931.5 MeV，释放能量多少？","given":"正质量差表示初静质量更大，其他守恒条件已满足。","analysis":"给的换算量已经含c²。","method":"Q=Δm×931.5 MeV/u。","principle":"静质量降低可转为其他能量。","steps":["Q=0.0100×931.5=9.315 MeV。","按3位有效数字约9.32 MeV。"],"ans":"约9.32 MeV/次反应。","verification":"0.01 u约百分之一931.5 MeV，数量级约9。","pitfall":"再额外乘c²或把质量差当kg。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.6","related_sections":[]},{"q":"一隔离容器释放3.00×10⁸ J辐射到系统外，取c=3×10⁸，静止系统质量减少多少？若把辐射也算系统内呢？","given":"初末整体静止，其他交换忽略。","analysis":"质量变化取决边界是否含离开能量。","method":"Δm大小=E离开/c²。","principle":"同边界能量与质量收支。","steps":["减少3×10⁸/(9×10¹⁶)=3.33×10⁻⁹ kg。","若边界包含辐射，总系统能量仍需包含它，不能把它再次记成丢失。"],"ans":"容器系统少约3.33×10⁻⁹ kg；总系统账目另含辐射。","verification":"乘c²回得3×10⁸ J。","pitfall":"忽略系统边界而说总能量无故消失。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.6","related_sections":[]}],"practice":[{"q":"2.0 MeV是多少J？","given":"1 MeV=10⁶ eV。","analysis":"先指数再基本换算。","method":"乘10⁶与eV到J因子。","principle":"能量单位换算。","steps":["2.0×10⁶×1.602176634×10⁻¹⁹=3.20435×10⁻¹³ J。","按2位约3.2×10⁻¹³ J。"],"ans":"约3.2×10⁻¹³ J。","verification":"MeV是单次微观能量仍可对应很小J。","pitfall":"把Mega写成10⁻⁶。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.6","related_sections":[]},{"q":"低速物体静质量不变，其速度增加时总能量会增加吗？","given":"外界做正功加速。","analysis":"静能与动能不同项。","method":"区分E₀和K。","principle":"能量可通过动能增加，不需把静质量定义改成速度变量。","steps":["静能mc²保持。","动能随速度增加，总能量增加。"],"ans":"会。","verification":"低速ΔK≈m(v₂²−v₁²)/2。","pitfall":"说质量不变所以任何能量都不变。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.6","related_sections":[]},{"q":"质量亏损是否意味着核反应可不守恒电荷和核子数？","given":"讨论所给普通核反应模型。","analysis":"质能关系不取代其他守恒律。","method":"分别检查反应式。","principle":"能量与电荷等守恒是不同约束。","steps":["质量差可对应释放能。","仍需核反应两侧电荷和核子等相应守恒。"],"ans":"不意味着。","verification":"错误配平不能因Q算得正就变合法。","pitfall":"把质能可转换当作所有粒子数随意改变。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.6","related_sections":[]},{"q":"每反应释放4.0×10⁻¹³ J，共10¹⁵次反应，总能量及理想等效质量变化？取c=3×10⁸。","given":"各反应相同，能量全部计总释放。","analysis":"微观单次量先乘次数。","method":"E=NQ，再Δm=E/c²。","principle":"可加能量与质能关系。","steps":["E=10¹⁵×4.0×10⁻¹³=4.0×10² J。","Δm=400/(9×10¹⁶)≈4.4×10⁻¹⁵ kg。"],"ans":"400 J，约4.4×10⁻¹⁵ kg。","verification":"400 J虽宏观可测，等效质量仍极小。","pitfall":"用每次能量直接求整个系统变化而漏N。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.6","related_sections":[]}],"quiz":{"q":"光子有能量但静质量0，是否否定E₀=mc²？","given":"E₀定义为静能，光子没有静止参考系。","analysis":"不能把静能式当所有能量的唯一表达。","method":"区分适用对象与完整能量动量关系。","principle":"光子能量不由非零静质量的静能来解释。","steps":["零静质量不等于零能量。","E₀=mc²不声称光子能量全是静能，低速mv²/2也不适用于光子。"],"ans":"不否定，是误用公式范围造成表面矛盾。","verification":"光子无静止态，不能把其速度设0来定义静能实验。","pitfall":"以有能量推出必须有非零静质量。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":7,"primary_section":"7.6","related_sections":[]},"exam":["质能题先定静能或能量变化、系统边界及单位","核能换算明确每次与总量，原子/核质量数据不混用","解释题不把mc²静能等同任意燃料实际可用输出，不以其替代配平"],"quick":["静能定义","系统边界","质量差","单位换算","可用能与限制"],"exam_evidence":[],"content_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":250,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_7.6","url":"https://openstax.org/books/college-physics-2e/pages/28-6-relativistic-energy","page_or_section":"28-6-relativistic-energy","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":250,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_7.6","url":"https://openstax.org/books/college-physics-2e/pages/28-6-relativistic-energy","page_or_section":"28-6-relativistic-energy","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"质能题先定静能或能量变化、系统边界及单位","method":"Δm大小=E离开/c²。","principle":"同边界能量与质量收支。","worked_example_index":2,"verification":"乘c²回得3×10⁸ J。","pitfall":"忽略系统边界而说总能量无故消失。"},"diagnostics":[{"goal_index":0,"question_ref":"p1","review_module":4,"feedback":"目标“区分静能、动能与系统质量变化”的抽样复核：低速ΔK≈m(v₂²−v₁²)/2。；若出现“说质量不变所以任何能量都不变。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“用质能关系换算能量并保持系统边界一致”的抽样复核：乘c²回得3×10⁸ J。；若出现“忽略系统边界而说总能量无故消失。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"以有能量推出必须有非零静质量。","correction":"不否定，是误用公式范围造成表面矛盾。","verification":"光子无静止态，不能把其速度设0来定义静能实验。"}],"illustration_spec":{"title":"质能关系的系统边界","objects":["初末静止容器","离开辐射箭头","外部总系统框","单位换算框"],"relations":["容器能量减少对应质量减少","把辐射计入时不可再漏记","静能与动能分项"],"labels":["E₀=mc²","ΔE=Δmc²","1 u c²≈931.5 MeV","不是全量可提取承诺"],"format":"SVG","priority":"P1","reuse":"无完全对应旧图；公式应SVG文字层","english":"Show a stationary container losing radiation across a defined boundary, with corresponding mass decrease delta E/c squared. Use a larger boundary to include radiation and keep total energy accounting consistent. Separate rest energy from kinetic energy and from practically extractable fuel energy."}}},"物理8":{"8.1":{"subject":"物理","subject_code":"physics","chapter_id":8,"section_id":"8.1","goals":["用方向和时间范围计算冲量","由力时间图求动量变化并反推平均力"],"prerequisites":["牛顿第二定律","向量与图象面积"],"flow":["选方向","初末动量","力时间面积","外冲量","平均力与缓冲"],"concept_relation":"选方向；初末动量；力时间面积；外冲量；平均力与缓冲","deep":["选正方向后先分别写初、末速度带符号值，再作p末−p初。反弹从负向到正向时，两者相减可能使变化大小等于速率之和乘质量；盲用“末速率减初速率”会把方向改变漏掉。","缓冲装置在相同初末动量变化下延长作用时间，可降低平均合力大小。峰值是否降低还依力时间曲线形状，不能只靠平均力公式保证任何峰值都下降。安全应用还要考虑位移空间、材料和允许加速度等约束。","碰撞过程中力随时间剧烈变化，冲量法避免追踪每一时刻细节。若题目给F-t图，需要确定是接触力、合力还是某一方向分量，面积单位和正负要与动量分量对应。","求得平均力后应检查作用对象和方向，并避免把球受墙力与墙受球力混在同一方程。它们大小相等方向相反，但分别属于不同对象；用同一质量解释两边运动会产生错误。"],"derive":["p=mv；Δp=mv_f−mv_i，矢量或带符号分量计算。","J外=Δp；F平均=Δp/Δt，指所选时段的合外力平均值。","三角形F-t脉冲J=底×高/2；单位N·s=kg·m/s。"],"examples":[{"q":"质量0.20 kg球沿正向以5 m/s运动，被挡停，求合外冲量。","given":"v_i=+5，v_f=0。","analysis":"冲量方向与原动量相反。","method":"Δp=m(v_f−v_i)。","principle":"合外冲量等于动量变化。","steps":["p_i=0.20×5=1.0 kg·m/s。","Δp=0−1.0=−1.0 N·s。"],"ans":"−1.0 N·s，沿负方向。","verification":"初动量加冲量=0，符合停止。","pitfall":"只给正的1.0而漏方向。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":8,"primary_section":"8.1","related_sections":[]},{"q":"0.10 kg球向左8 m/s撞墙后向右6 m/s，接触0.02 s，忽略其他水平方向冲量，平均墙力？","given":"取右为正，v_i=−8、v_f=+6。","analysis":"反弹须带符号相减。","method":"F平均=m(v_f−v_i)/Δt。","principle":"水平方向动量定理。","steps":["Δp=0.10[6−(−8)]=1.4 N·s。","F平均=1.4/0.02=70 N向右。"],"ans":"70 N向右，作用于球。","verification":"−0.8+1.4=+0.6 kg·m/s。","pitfall":"用6−8得到力方向和大小都错。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":8,"primary_section":"8.1","related_sections":[]},{"q":"一F-t三角形脉冲底宽0.04 s、峰值100 N，质量0.5 kg物体初静止，只受该方向合力，末速度？","given":"力图是合力且全为正。","analysis":"面积给冲量而非峰值乘全时。","method":"J=半底高，再Δp。","principle":"合力冲量改变动量。","steps":["J=0.5×0.04×100=2 N·s。","v=J/m=2/0.5=4 m/s。"],"ans":"+4 m/s。","verification":"平均力50 N×0.04 s=2 N·s。","pitfall":"用峰值100 N当平均值。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":8,"primary_section":"8.1","related_sections":[]}],"practice":[{"q":"2 kg物体速度由+3变+7 m/s，冲量？","given":"质量恒定。","analysis":"同方向仍需末减初。","method":"mΔv。","principle":"动量定理。","steps":["Δv=4 m/s。","J=2×4=8 N·s。"],"ans":"+8 N·s。","verification":"初6加8=末14 kg·m/s。","pitfall":"算末动量14当冲量。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":8,"primary_section":"8.1","related_sections":[]},{"q":"同样Δp=6 N·s，作用0.02与0.06 s，平均力大小？","given":"方向不变作大小比较。","analysis":"时间延长平均力下降。","method":"F=J/Δt。","principle":"平均力定义。","steps":["6/0.02=300 N。","6/0.06=100 N。"],"ans":"300 N与100 N。","verification":"时间3倍，平均力1/3。","pitfall":"推断峰值也必精确降至1/3。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":8,"primary_section":"8.1","related_sections":[]},{"q":"动量大小相同的两物体，方向相反，它们的动量相同吗？","given":"矢量方向相反。","analysis":"大小不等于矢量。","method":"取共同正方向表示。","principle":"动量与速度同方向。","steps":["可记p与−p。","两者矢量不相等，总动量可为0。"],"ans":"不相同。","verification":"相加0不等于单体各自0。","pitfall":"把标量大小当矢量。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":8,"primary_section":"8.1","related_sections":[]},{"q":"0至1 s合力+4 N、1至3 s合力−1 N，质量1 kg初速+3 m/s，末速？","given":"分段恒力。","analysis":"有向面积相加。","method":"J=4×1−1×2。","principle":"Δp=J外。","steps":["J=2 N·s。","p末=3+2=5 kg·m/s，v末=5 m/s。"],"ans":"+5 m/s。","verification":"分段a给先到7再降到5，结果一致。","pitfall":"负力区域取绝对值加成6。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":8,"primary_section":"8.1","related_sections":[]}],"quiz":{"q":"若只给接触力冲量，能否永远令它等于物体全部动量变化？","given":"其他外力可能作用同一时间段。","analysis":"定理要求合外冲量。","method":"列所有外力并估其冲量。","principle":"各外冲量矢量和等于Δp。","steps":["接触冲量与重力等需相加。","仅在其他有关分量抵消或可忽略时，才能直接等于Δp。"],"ans":"不能无条件。","verification":"较长接触时mgΔt可不可忽略。","pitfall":"把一个力和合外力混写。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":8,"primary_section":"8.1","related_sections":[]},"exam":["冲量题先选对象方向和起止时刻，列带符号初末速度","F-t图分有向面积，峰值不是平均值","缓冲题说同Δp下延时降平均力，峰值另需曲线证据"],"quick":["选方向","初末动量","力时间面积","外冲量","平均力与缓冲"],"exam_evidence":[],"content_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":264,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_8.1","url":"https://openstax.org/books/college-physics-2e/pages/8-2-impulse","page_or_section":"8-2-impulse","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":264,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_8.1","url":"https://openstax.org/books/college-physics-2e/pages/8-2-impulse","page_or_section":"8-2-impulse","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"冲量题先选对象方向和起止时刻，列带符号初末速度","method":"J=半底高，再Δp。","principle":"合力冲量改变动量。","worked_example_index":2,"verification":"平均力50 N×0.04 s=2 N·s。","pitfall":"用峰值100 N当平均值。"},"diagnostics":[{"goal_index":0,"question_ref":"e1","review_module":4,"feedback":"目标“用方向和时间范围计算冲量”的抽样复核：−0.8+1.4=+0.6 kg·m/s。；若出现“用6−8得到力方向和大小都错。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“由力时间图求动量变化并反推平均力”的抽样复核：平均力50 N×0.04 s=2 N·s。；若出现“用峰值100 N当平均值。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"把一个力和合外力混写。","correction":"不能无条件。","verification":"较长接触时mgΔt可不可忽略。"}],"illustration_spec":{"title":"反弹动量与三角形冲量","objects":["球向左8后向右6","右正轴","三角形F-t脉冲"],"relations":["Δp=0.1×(6+8)=1.4","0.04×100/2=2 N·s","峰值与平均值分开"],"labels":["v_i=−8 m/s","v_f=+6 m/s","Δp","F/N","t/s"],"format":"SVG","priority":"P0","reuse":"V22 P10可复用原理，具体数值需说明不同例题","english":"Show signed initial and final velocities for a rebounding ball, then a separate triangular net-force pulse of height 100 N and duration 0.04 s with impulse 2 N s. Explicitly distinguish peak force from average force."}},"8.2":{"subject":"物理","subject_code":"physics","chapter_id":8,"section_id":"8.2","goals":["判定所选系统能否用动量守恒","由矢量总动量求相互作用后的速度"],"prerequisites":["动量定理","系统与外力"],"flow":["系统边界","内外冲量","方向守恒","共同或分别速度","能量独立审查"],"concept_relation":"系统边界；内外冲量；方向守恒；共同或分别速度；能量独立审查","deep":["守恒式写Σmᵢvᵢ前=Σmᵢvᵢ后，所有速度需相对同一惯性参考系和同一正方向。两物体碰后速度不必相同，只有黏合或题给共同运动才可合并为(m₁+m₂)v。","动量守恒与动能守恒条件不同。内力能把机械能转为形变、热等而不改变系统总动量；有爆炸释放内能时，动能甚至可增加。不能因用了动量守恒就附送动能守恒。","有摩擦并不自动否定任何短时近似，但必须比较外冲量与相互作用的动量变化尺度，并清楚标为近似。严格等式与忽略小量的近似要分开，不能只写“时间短所以一切外力消失”。","验证解时检查初末总动量、方向与约束。若总初动量为零，最终各物体仍可以运动，只要矢量和为零；“总量零”不等于每个分量或每个个体都静止。"],"derive":["ΔP系统=J合外；J合外=0时P前=P后。","一维：m₁u₁+m₂u₂=m₁v₁+m₂v₂；若黏合，v₁=v₂=v。","分方向守恒只在该方向合外冲量可忽略时使用；动能须独立审查。"],"examples":[{"q":"2 kg小车以3 m/s与静止1 kg小车黏合，水平外冲量忽略，共同速度？","given":"取初运动方向正。","analysis":"黏合使末速度相同。","method":"动量守恒。","principle":"系统水平方向合外冲量近0。","steps":["P前=2×3+1×0=6。","3v=6，v=2 m/s。"],"ans":"+2 m/s。","verification":"P后3×2=6；初动能9 J，末6 J，动量守恒不要求动能守恒。","pitfall":"把末速度设3或强用动能守恒。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":8,"primary_section":"8.2","related_sections":[]},{"q":"1 kg以+4 m/s、2 kg以−1 m/s运动，后者相互作用后速度+1 m/s，前者末速？","given":"系统水平外冲量忽略。","analysis":"方向需共同符号。","method":"列初末动量。","principle":"内冲量不改变总动量。","steps":["P前=1×4+2×(−1)=2。","v₁+2×1=2，故v₁=0。"],"ans":"前者末速0。","verification":"末总动量0+2=2。","pitfall":"把反向初速写正使总量错。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":8,"primary_section":"8.2","related_sections":[]},{"q":"系统初动量10 N·s，0.2 s内外力恒定向正10 N，能设末动量仍10吗？","given":"外力与初动量同向。","analysis":"必须先算外冲量。","method":"ΔP=FΔt。","principle":"有非零外冲量时不守恒。","steps":["J外=10×0.2=2 N·s。","P后=10+2=12 N·s。"],"ans":"不能；应为12 N·s。","verification":"总量增2与外冲量一致。","pitfall":"看到相互作用就忽略明确给出的外力。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":8,"primary_section":"8.2","related_sections":[]}],"practice":[{"q":"总动量0是否表示两个物体都静止？","given":"总量是矢量和。","analysis":"非零反向量可抵消。","method":"构造等大反向动量。","principle":"总动量相加。","steps":["1 kg以+2 m/s、2 kg以−1 m/s。","动量+2与−2总0，但两者都运动。"],"ans":"不是。","verification":"动能却为2+1=3 J大于0。","pitfall":"把总量零当各项零。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":8,"primary_section":"8.2","related_sections":[]},{"q":"黏合前总动量−9 kg·m/s，总质量3 kg，末速度？","given":"无相关外冲量，共同运动。","analysis":"符号是方向。","method":"v=P/M。","principle":"动量守恒。","steps":["v=−9/3=−3 m/s。","负号表示所选正向的反方向。"],"ans":"−3 m/s。","verification":"3×(−3)=−9。","pitfall":"把负号删成+3。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":8,"primary_section":"8.2","related_sections":[]},{"q":"为什么两个物体之间内力很大仍可守恒总动量？","given":"系统同时包括二者。","analysis":"内力成对而非不存在。","method":"将两动量定理相加。","principle":"内冲量等大反向。","steps":["J₁₂+J₂₁=0。","总变化只剩外冲量，可为0。"],"ans":"内力冲量在系统求和中抵消。","verification":"单个物体动量仍可明显改变。","pitfall":"误写内力为0或每个动量都守恒。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":8,"primary_section":"8.2","related_sections":[]},{"q":"1 kg车以6 m/s与静止2 kg车黏合，若另受合外冲量−0.6 N·s，末速多少？","given":"外冲量题给不忽略。","analysis":"用动量定理修正守恒式。","method":"Mv=P前+J外。","principle":"系统动量变化等于合外冲量。","steps":["P后=6−0.6=5.4。","v=5.4/3=1.8 m/s。"],"ans":"+1.8 m/s。","verification":"若忽略外冲量得2，题给负冲量使速度更小合理。","pitfall":"仍机械用6/3=2。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":8,"primary_section":"8.2","related_sections":[]}],"quiz":{"q":"只把小球列为系统却把它受墙的力说成内力，为什么不成立？","given":"系统边界不含墙。","analysis":"内外分类依边界。","method":"说明施力物体是否在系统内。","principle":"外部物体对系统的力是外力。","steps":["墙在系统之外。","墙对球的冲量是外冲量，因此球动量可改变。"],"ans":"系统选择与内力分类矛盾。","verification":"球反弹的动量改变正需墙冲量。","pitfall":"为了守恒任意把外力改称内力。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":8,"primary_section":"8.2","related_sections":[]},"exam":["守恒题先写系统、方向、时段及外冲量依据，再列式","黏合才可共同速度，分离题每物体保留末速变量","算完同时核总动量，能量需另审，不自动守恒"],"quick":["系统边界","内外冲量","方向守恒","共同或分别速度","能量独立审查"],"exam_evidence":[],"content_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":272,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_8.2","url":"https://openstax.org/books/college-physics-2e/pages/8-3-conservation-of-momentum","page_or_section":"8-3-conservation-of-momentum","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":272,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_8.2","url":"https://openstax.org/books/college-physics-2e/pages/8-3-conservation-of-momentum","page_or_section":"8-3-conservation-of-momentum","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"守恒题先写系统、方向、时段及外冲量依据，再列式","method":"ΔP=FΔt。","principle":"有非零外冲量时不守恒。","worked_example_index":2,"verification":"总量增2与外冲量一致。","pitfall":"看到相互作用就忽略明确给出的外力。"},"diagnostics":[{"goal_index":0,"question_ref":"e2","review_module":4,"feedback":"目标“判定所选系统能否用动量守恒”的抽样复核：总量增2与外冲量一致。；若出现“看到相互作用就忽略明确给出的外力。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e1","review_module":5,"feedback":"目标“由矢量总动量求相互作用后的速度”的抽样复核：末总动量0+2=2。；若出现“把反向初速写正使总量错。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"为了守恒任意把外力改称内力。","correction":"系统选择与内力分类矛盾。","verification":"球反弹的动量改变正需墙冲量。"}],"illustration_spec":{"title":"系统边界与动量收支","objects":["两车系统框","内力成对箭头","外冲量箭头","初末动量条"],"relations":["内力只在两车都纳入时相消","非零外冲量改变总量","动能另算"],"labels":["P前","P后","J外","ΔP=J外","同一参考系"],"format":"SVG","priority":"P0","reuse":"V22 P10原理可补充，不重复同一题材","english":"Draw a system boundary around two interacting carts, cancel paired internal impulses, and keep external impulse crossing the boundary. Show P_after=P_before+J_external; do not imply kinetic-energy conservation."}},"8.3":{"subject":"物理","subject_code":"physics","chapter_id":8,"section_id":"8.3","goals":["用系统动量解释反冲方向","区分地面速度、相对速度与系统边界"],"prerequisites":["动量守恒","相对速度"],"flow":["系统分离","初总动量","同参考系速度","相对速度条件","能源与外冲量"],"concept_relation":"系统分离；初总动量；同参考系速度；相对速度条件；能源与外冲量","deep":["火箭通过向后排出物质获得向前动量变化，不需要推空气，因此可以在真空工作。排气与火箭间的作用力遵守相互作用，但若只取火箭本体，其质量随排气改变，不能把整个燃烧过程无条件写成固定质量的F=ma或简单两块一次分离公式。","本节可用一次分离的离散模型说明反冲，对连续变质量火箭的完整方程则需进一步考虑质量流和相对排气速度。模型层次应明确，不能把忽略外力的一瞬或一小段结论扩展为真实起飞全程速度。","反冲获得动能的来源可能是化学内能、弹性势能或人做功。系统动量保持零不代表总动能为零，也不能说为了反冲必须从静止状态“创造动量”；相反方向动量可以各自非零而合为零。","实际发射存在支架、地面、空气和重力等外部作用。固定发射装置与自由可动装置条件不同，是否可忽略某方向外冲量要具体说明；不能把所有枪弹题都默认完全孤立而不看题设。"],"derive":["初静止的一次分离模型：mv+MV=0，v和V必须相对同一参考系。","若给相对速度u=v−V，与mv+MV=0联立，V=−mu/(M+m)，v=Mu/(M+m)。","反冲动能K=m v²/2+M V²/2可大于0，能量来自系统内部或外部做功，不来自动量守恒本身。"],"examples":[{"q":"自由小车质量2 kg，向右抛出0.5 kg物体，物体地面速度4 m/s，初静止且水平外冲量忽略，小车速度？","given":"抛出后车质量2 kg，物体速度相对地面。","analysis":"两部分动量和0。","method":"0.5×4+2V=0。","principle":"所选系统动量守恒。","steps":["物体动量+2 kg·m/s。","小车V=−2/2=−1 m/s。"],"ans":"1 m/s向左。","verification":"两部分动量+2与−2相消。","pitfall":"把抛出前总质量2.5当剩余车质量。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":8,"primary_section":"8.3","related_sections":[]},{"q":"同样车2 kg、物体0.5 kg，但4 m/s为物体相对车的速度，求地面速度。","given":"初静止，水平外冲量忽略。","analysis":"相对速度不能直接代地面值。","method":"联立v−V=4与0.5v+2V=0。","principle":"速度相对变换及动量守恒。","steps":["v=V+4，代入0.5(V+4)+2V=0。","2.5V=−2，V=−0.8，v=3.2 m/s。"],"ans":"车−0.8 m/s，物体+3.2 m/s。","verification":"3.2−(−0.8)=4，动量1.6−1.6=0。","pitfall":"照前题得−1与4而相对速度变成5。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":8,"primary_section":"8.3","related_sections":[]},{"q":"质量3 kg与1 kg两块初静止分离，1 kg块以6 m/s向右，求另一块速度和总动能。","given":"一次分离，外冲量忽略。","analysis":"动量零但动能可增加。","method":"先求反向速度，再求两部分动能。","principle":"内能释放可在动量守恒下增加动能。","steps":["3V+1×6=0，V=−2 m/s。","K=0.5×3×4+0.5×1×36=6+18=24 J。"],"ans":"3 kg块向左2 m/s，总动能24 J。","verification":"动量−6+6=0；能量24 J须有释放来源。","pitfall":"以初动能0推断末动能也0。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":8,"primary_section":"8.3","related_sections":[]}],"practice":[{"q":"火箭在真空能否靠排气推进？","given":"无空气但可携带并排出物质。","analysis":"推进不是推空气。","method":"考察火箭与排气总系统。","principle":"内部相互作用分配相反动量。","steps":["排气向后带走动量。","火箭获得相反方向动量变化，外部空气并非必要。"],"ans":"可以。","verification":"与动量守恒相容。","pitfall":"必须有空气给火箭反作用。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":8,"primary_section":"8.3","related_sections":[]},{"q":"两部分初静止分离后质量比1:4，速度大小比？","given":"两部分总动量0，一维。","analysis":"动量大小相等。","method":"m₁|v₁|=m₂|v₂|。","principle":"守恒且方向相反。","steps":["|v₁|/|v₂|=m₂/m₁=4。","方向相反。"],"ans":"4:1，反向。","verification":"小质量需更大速度达到等动量。","pitfall":"把质量比直接作为速度比。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":8,"primary_section":"8.3","related_sections":[]},{"q":"枪固定在地面上，能只对枪和弹无条件用自由反冲公式吗？","given":"支架可提供外冲量。","analysis":"系统边界未含支架地球。","method":"审查外冲量。","principle":"动量变化由外冲量决定。","steps":["固定约束可传递明显动量给地面。","枪弹两体系统不再满足忽略外冲量的自由模型。"],"ans":"不能无条件。","verification":"固定枪末速0也不妨碍弹获动量，因为有外部交换。","pitfall":"忽略固定条件。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":8,"primary_section":"8.3","related_sections":[]},{"q":"4 kg车抛1 kg物体，物体相对车5 m/s，初静止，求两者地面速度并验证。","given":"水平外冲量忽略。","analysis":"给的是相对速度。","method":"v−V=5，v+4V=0。","principle":"动量与相对速度两式。","steps":["v=V+5，5V+5=0，V=−1。","v=4 m/s。"],"ans":"车−1，物体+4 m/s。","verification":"4−(−1)=5；4+4×(−1)=0。","pitfall":"把5直接当物体地面速度。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":8,"primary_section":"8.3","related_sections":[]}],"quiz":{"q":"真实火箭燃烧时剩余质量变化，可以直接把起飞全程当固定两块瞬间分离计算吗？","given":"连续排气且外力可能存在。","analysis":"系统和质量在时间中变化。","method":"限定离散模型或采用质量流分析。","principle":"连续变质量过程需逐段计动量通量及外力。","steps":["一次两块模型可说明方向和局部理想例子。","全程须处理持续排气、变质量和重力等，不能原式无条件外推。"],"ans":"不可以无条件。","verification":"不同排气时刻有不同火箭速度，不能归为一个固定末速度块。","pitfall":"把演示模型冒充完整航天计算。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":8,"primary_section":"8.3","related_sections":[]},"exam":["反冲题先确认抛出后质量与速度参考系","给相对速度须列v抛−v体=u并与守恒联立","解释题用排气动量与内部能源，说明真空可推进及模型限制"],"quick":["系统分离","初总动量","同参考系速度","相对速度条件","能源与外冲量"],"exam_evidence":[],"content_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":282,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_8.3","url":"https://openstax.org/books/college-physics-2e/pages/8-7-introduction-to-rocket-propulsion","page_or_section":"8-7-introduction-to-rocket-propulsion","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":282,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_8.3","url":"https://openstax.org/books/college-physics-2e/pages/8-7-introduction-to-rocket-propulsion","page_or_section":"8-7-introduction-to-rocket-propulsion","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"反冲题先确认抛出后质量与速度参考系","method":"先求反向速度，再求两部分动能。","principle":"内能释放可在动量守恒下增加动能。","worked_example_index":2,"verification":"动量−6+6=0；能量24 J须有释放来源。","pitfall":"以初动能0推断末动能也0。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“用系统动量解释反冲方向”的抽样复核：两部分动量+2与−2相消。；若出现“把抛出前总质量2.5当剩余车质量。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e1","review_module":5,"feedback":"目标“区分地面速度、相对速度与系统边界”的抽样复核：3.2−(−0.8)=4，动量1.6−1.6=0。；若出现“照前题得−1与4而相对速度变成5。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"把演示模型冒充完整航天计算。","correction":"不可以无条件。","verification":"不同排气时刻有不同火箭速度，不能归为一个固定末速度块。"}],"illustration_spec":{"title":"反冲的参考系与相对速度","objects":["小车2 kg","抛出物0.5 kg","地面坐标","速度箭头","相对速度括号"],"relations":["V=−0.8","v=+3.2","v−V=4","两动量等大反向"],"labels":["相对地面","相对车4 m/s","P总=0","内部能源"],"format":"SVG","priority":"P0","reuse":"须用明确参考系的新示意，旧反冲图可核后辅助","english":"For a freely moving 2 kg cart ejecting a 0.5 kg object, show ground velocities -0.8 and +3.2 m/s, with object speed relative to cart 4 m/s. Distinguish relative and ground arrows and show equal opposite momenta, not equal speeds."}},"8.4":{"subject":"物理","subject_code":"physics","chapter_id":8,"section_id":"8.4","goals":["先用动量再按碰撞类型审查能量","求一维碰撞速度并核方向与能量损失"],"prerequisites":["动量守恒","动能与联立方程"],"flow":["系统动量","碰撞类型","第二条件","总动能","分离与验算"],"concept_relation":"系统动量；碰撞类型；第二条件；总动能；分离与验算","deep":["同质量正碰且一个初静止，在理想一维弹性条件下可交换速度；若黏合则共同速度为初速度的一半。两个结果都可满足动量守恒，说明只用一个守恒方程不足以判定两个独立末速度。","动能损失要用两物体的总动能前后比较，不可只看一个物体变慢。某个物体可能变快而系统总动能仍减少。若题给可释放内能的爆发性相互作用，末动能可能增加，此时也不属于普通仅耗散的非弹性模型。","实际二维碰撞要分方向列动量方程，动能为各速度大小的平方；先画方向能避免把不同轴分量混用。本节典型计算聚焦一维，不把二维条件简化成所有速度带一个正负号。","最终检查包括碰后是否满足黏合或分离条件、动量总量是否一致、动能变化是否符合类型。代数联立可能包含“仍保持碰前状态”的根，须用实际碰撞与分离条件排除不合物理的分支。"],"derive":["一维动量：m₁u₁+m₂u₂=m₁v₁+m₂v₂。","弹性另有m₁u₁²/2+m₂u₂²/2=m₁v₁²/2+m₂v₂²/2，可推出v₂−v₁=u₁−u₂。","黏合共同速度v=(m₁u₁+m₂u₂)/(m₁+m₂)；损失ΔK=K前−K后，不必等于K前。"],"examples":[{"q":"1 kg车以4 m/s撞静止1 kg车并黏合，求共同速度与动能损失。","given":"水平外冲量忽略。","analysis":"黏合可合并末质量，不能守恒动能。","method":"动量求v再算K。","principle":"完全非弹性模型。","steps":["2v=4，v=2 m/s。","K前=0.5×1×16=8 J，K后=0.5×2×4=4 J，损失4 J。"],"ans":"共同+2 m/s，损失4 J。","verification":"动量前4后4，末动能仍4不为0。","pitfall":"完全非弹性误写末动能零。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":8,"primary_section":"8.4","related_sections":[]},{"q":"同样两辆1 kg车，初速4与0，改为一维弹性碰撞，末速？","given":"外冲量忽略且弹性。","analysis":"需动量与弹性相对速度两条件。","method":"v₁+v₂=4，v₂−v₁=4。","principle":"一维弹性守恒两量。","steps":["两式相加2v₂=8，v₂=4。","v₁=0。"],"ans":"第一车停，第二车+4 m/s。","verification":"总动量4，动能8 J均与初相同。","pitfall":"只用动量任猜2和2。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":8,"primary_section":"8.4","related_sections":[]},{"q":"2 kg车以3 m/s撞静止1 kg车，一维弹性，求两末速并核算。","given":"正方向沿初车速度。","analysis":"两质量不等，不能直接交换速度。","method":"2v₁+v₂=6，v₂−v₁=3。","principle":"动量和一维弹性关系。","steps":["代v₂=v₁+3得3v₁=3，v₁=1。","v₂=4 m/s。","K后=0.5×2×1²+0.5×1×4²=1+8=9 J。"],"ans":"2 kg车+1、1 kg车+4 m/s。","verification":"初K=0.5×2×9=9 J，动量2+4=6。","pitfall":"把等质量交换速度推广不等质量。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":8,"primary_section":"8.4","related_sections":[]}],"practice":[{"q":"碰后两物体黏合，能默认动能守恒吗？","given":"非特殊零相对速度情境。","analysis":"黏合限制末速度但一般耗散动能。","method":"动量后独立算K。","principle":"完全非弹性不要求动能守恒。","steps":["共同速度由动量确定。","通常存在形变热等，需比较总K。"],"ans":"不能。","verification":"1 kg、4与0的例子损失一半动能。","pitfall":"把所有守恒定律捆绑使用。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":8,"primary_section":"8.4","related_sections":[]},{"q":"1 kg以+3、1 kg以−3 m/s相向黏合，末速与损失？","given":"外冲量忽略。","analysis":"总动量零但初动能正。","method":"动量求共同速度。","principle":"相反动量抵消。","steps":["P前=0，v=0。","K前=4.5+4.5=9 J，K后0，损失9 J。"],"ans":"末速0，损失9 J。","verification":"这是末K为0的特殊条件，非所有黏合都如此。","pitfall":"从该特例推出所有完全非弹性末能0。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":8,"primary_section":"8.4","related_sections":[]},{"q":"某车碰撞后动能增加2 J，另一辆减少5 J，总动能变化？","given":"只有这两辆车构成所比系统。","analysis":"应求总和。","method":"ΔK总=ΣΔK。","principle":"局部获得可伴总体损失。","steps":["2+(−5)=−3 J。","系统损失3 J。"],"ans":"减少3 J。","verification":"一辆把5 J中的2 J给另一辆，其余3 J转其他形式。","pitfall":"只看一辆增能就称系统弹性或增能。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":8,"primary_section":"8.4","related_sections":[]},{"q":"3 kg以2 m/s撞静止1 kg并黏合，求v、动能损失与损失率。","given":"忽略水平外冲量。","analysis":"先动量后能量。","method":"v=P/M，再算K。","principle":"黏合共同速度。","steps":["P=6，v=6/4=1.5 m/s。","K前=6 J，K后=0.5×4×2.25=4.5 J。","损失1.5 J，比例1.5/6=25%。"],"ans":"+1.5 m/s，损失1.5 J、25%。","verification":"末P=4×1.5=6，末能为初75%。","pitfall":"把总质量4代进初车动能。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":8,"primary_section":"8.4","related_sections":[]}],"quiz":{"q":"只给两物体初速度、质量与总动量守恒，未说明碰撞类型，通常能唯一确定两个独立末速度吗？","given":"一维但没有黏合或能量等第二条件。","analysis":"一个独立方程通常有两个未知。","method":"说明缺何物理条件。","principle":"守恒动量限制总量，不确定分配唯一性。","steps":["可有不同v₁、v₂组合满足同一总P。","需弹性、恢复系数或黏合等额外信息，不能擅自添加。"],"ans":"通常不能唯一确定。","verification":"等质量4与0初态，末0与4或2与2均满足动量而类型不同。","pitfall":"看见碰撞便自动假定弹性。","question_origin":"original","paper_no":null,"subject_code":"physics","chapter_id":8,"primary_section":"8.4","related_sections":[]},"exam":["碰撞题先写系统外冲量，再从弹性/黏合/其他条件选第二关系","能量损失按两物体总K前后求，明确非总能量消失","一维弹性相对速度仅在适用模型用，最后核分离方向"],"quick":["系统动量","碰撞类型","第二条件","总动能","分离与验算"],"exam_evidence":[],"content_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":287,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_8.4","url":"https://openstax.org/books/college-physics-2e/pages/8-4-elastic-collisions-in-one-dimension","page_or_section":"8-4-elastic-collisions-in-one-dimension","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"authoring_sources":[{"source_id":"directory_phys","url":"https://www.scribd.com/document/896069659/曾国兴-黄宝玉-艺诚文化-高中适用-物理-上册-Dong-Zong-2017","page":287,"version":"教材内容表/目录对照；非考试纲要","access_date":"2026-11-18","verification_status":"partially_verified"},{"source_id":"theory_phys_8.4","url":"https://openstax.org/books/college-physics-2e/pages/8-4-elastic-collisions-in-one-dimension","page_or_section":"8-4-elastic-collisions-in-one-dimension","version":"原理参考；不是2027范围声明","access_date":"2026-11-18","verification_status":"partially_verified"}],"verification_status":"partially_verified","strategy":{"trigger":"碰撞题先写系统外冲量，再从弹性/黏合/其他条件选第二关系","method":"2v₁+v₂=6，v₂−v₁=3。","principle":"动量和一维弹性关系。","worked_example_index":2,"verification":"初K=0.5×2×9=9 J，动量2+4=6。","pitfall":"把等质量交换速度推广不等质量。"},"diagnostics":[{"goal_index":0,"question_ref":"e0","review_module":4,"feedback":"目标“先用动量再按碰撞类型审查能量”的抽样复核：动量前4后4，末动能仍4不为0。；若出现“完全非弹性误写末动能零。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"},{"goal_index":1,"question_ref":"e2","review_module":5,"feedback":"目标“求一维碰撞速度并核方向与能量损失”的抽样复核：初K=0.5×2×9=9 J，动量2+4=6。；若出现“把等质量交换速度推广不等质量。”，回读本节概念与适用条件，再重做本题。此题不是该目标全部子技能的唯一验收。"}],"error_analysis":[{"wrong_approach":"看见碰撞便自动假定弹性。","correction":"通常不能唯一确定。","verification":"等质量4与0初态，末0与4或2与2均满足动量而类型不同。"}],"illustration_spec":{"title":"弹性与黏合碰撞的双重核查","objects":["等质量初4与0","弹性末0与4","黏合末2与2","动量条","动能条"],"relations":["两例P均4","弹性K8保持","黏合K由8到4，差为其他形式"],"labels":["kg","m/s","P/(kg·m/s)","K/J","转为内能等"],"format":"SVG","priority":"P0","reuse":"V22 P27优先复核复用，避免与P11重复显示","english":"Compare two 1 kg carts initially at 4 and 0 m/s. Elastic final velocities are 0 and 4; sticking final velocity is 2. Plot momentum total 4 in both and kinetic energies 8 to 8 versus 8 to 4 J. Do not label dissipated kinetic energy as destroyed energy."}}}});
